module.exports = {
  "index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>SpinQuest PS | Problem Statement Roulette</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"style.css?v=20261005_6\">\n  <script src=\"https://cdn.jsdelivr.net/npm/canvas-confetti@1.9.3/dist/confetti.browser.min.js\"></script>\n</head>\n<body>\n\n  <!-- ═══════════════════════════════════════════════════════════ -->\n  <!-- TEAM ENTRY GATE (shown first, before main app)             -->\n  <!-- ═══════════════════════════════════════════════════════════ -->\n  <div id=\"entryGate\" class=\"entry-gate-overlay\">\n    <!-- Top-Right Admin Badge for direct organizer access -->\n    <a href=\"/admin\" class=\"entry-top-admin-badge\" title=\"Go to Admin Dashboard\">\n      <span class=\"badge-icon\">🔐</span> Admin Portal\n    </a>\n\n    <div class=\"entry-gate-card\">\n      <div class=\"entry-gate-logo\">\n        <div class=\"entry-logo-icon\">🎯</div>\n        <h1 class=\"entry-title\">SpinQuest <span class=\"brand-accent\">PS</span></h1>\n        <p class=\"entry-subtitle\">Problem Statement Roulette — Hackathon Edition</p>\n      </div>\n\n      <div class=\"entry-divider\"></div>\n\n      <h3 class=\"entry-form-heading\">Team Login — CODIENYCH 1.0</h3>\n      <p style=\"font-size: 0.8rem; color: var(--text-muted); text-align: center; margin: -8px 0 16px;\">\n        Enter your registered Reg ID (Team Name is optional)\n      </p>\n\n      <form id=\"teamEntryForm\" class=\"entry-form\" autocomplete=\"off\">\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"entryTeamId\">\n            <span class=\"label-icon\">🏷️</span> Reg ID / Team ID\n          </label>\n          <input type=\"text\" id=\"entryTeamId\" class=\"form-input\" placeholder=\"e.g. CODIENYCH-2026-0001\" required maxlength=\"35\">\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"entryTeamName\">\n            <span class=\"label-icon\">👥</span> Team Name <span style=\"font-size: 0.72rem; color: var(--text-muted); font-weight: normal; margin-left: 4px;\">(Optional)</span>\n          </label>\n          <input type=\"text\" id=\"entryTeamName\" class=\"form-input\" placeholder=\"e.g. Technical coders (Optional)\" maxlength=\"60\">\n        </div>\n\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"entryGithubLink\">\n            <span class=\"label-icon\">🔗</span> GitHub Repository\n          </label>\n          <input type=\"url\" id=\"entryGithubLink\" class=\"form-input\" placeholder=\"https://github.com/your-team/repo\">\n        </div>\n\n        <div id=\"entryErrorMsg\" class=\"form-error hidden\"></div>\n\n        <button type=\"submit\" id=\"entrySubmitBtn\" class=\"btn btn-accent btn-full btn-lg entry-submit-btn\">\n          <span class=\"btn-icon\">🚀</span>\n          <span id=\"entrySubmitLabel\">Verify &amp; Enter</span>\n        </button>\n      </form>\n\n      <p class=\"entry-footer-note\">Only registered teams from CODIENYCH 1.0 are authorized to access the roulette wheel.</p>\n\n      <!-- Organizer / Admin Access on First Page -->\n      <div class=\"entry-admin-access\">\n        <div class=\"entry-admin-divider\">\n          <span>EVENT ORGANIZER</span>\n        </div>\n        <a href=\"/admin\" class=\"entry-admin-btn\" title=\"Open Admin Login Portal\">\n          <span class=\"btn-icon\">🔐</span> Admin / Organizer Login\n        </a>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════════════════ -->\n  <!-- MAIN APPLICATION (revealed after team registration)        -->\n  <!-- ═══════════════════════════════════════════════════════════ -->\n  <div class=\"app-container hidden\" id=\"mainApp\">\n\n    <!-- Top Navigation Bar -->\n    <header class=\"navbar\">\n      <div class=\"nav-brand\">\n        <div class=\"logo-icon\">🎯</div>\n        <div class=\"brand-text\">\n          <h1>SpinQuest <span class=\"brand-accent\">PS</span></h1>\n          <p class=\"tagline\">Smart Domain Problem Statement Roulette</p>\n        </div>\n      </div>\n\n      <!-- Active Domain Pill -->\n      <div class=\"nav-center\">\n        <div class=\"active-domain-pill\" id=\"navActiveDomainBadge\">\n          <span class=\"pill-dot\"></span>\n          <span class=\"pill-label\">Domain:</span>\n          <strong id=\"navActiveDomainText\">Artificial Intelligence &amp; ML</strong>\n        </div>\n      </div>\n\n      <!-- Nav Right: Team Info + Explore + Admin -->\n      <div class=\"nav-actions\">\n        <div class=\"team-nav-pill\" id=\"teamNavPill\">\n          <span class=\"team-nav-icon\">👥</span>\n          <span id=\"teamNavName\">Team</span>\n        </div>\n        <button id=\"viewProblemsBtn\" class=\"btn btn-secondary btn-sm\" title=\"Explore available problem statements\">\n          📚 Explore Pool\n        </button>\n        <button id=\"logoutBtn\" class=\"btn btn-outline btn-sm logout-btn\" title=\"Log out from team session\">\n          🚪 Logout\n        </button>\n        <a href=\"/admin\" class=\"btn btn-outline btn-sm admin-nav-link\" title=\"Open Admin Portal\">\n          🔐 Admin\n        </a>\n      </div>\n    </header>\n\n    <!-- Main Workspace: Left | Center | Right -->\n    <main class=\"main-layout\">\n\n      <!-- LEFT SIDEBAR: Domain Selector & Cycle Tracker -->\n      <aside class=\"sidebar sidebar-left\">\n        <div class=\"panel-card domain-panel\">\n          <div class=\"panel-header\">\n            <div class=\"panel-title-group\">\n              <span class=\"panel-icon\">📂</span>\n              <div>\n                <h2>Choose Domain</h2>\n                <p class=\"panel-sub\">Select category to spin from</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Domain List -->\n          <div class=\"domains-scroll\" id=\"domainListContainer\">\n            <!-- Rendered by JS -->\n          </div>\n\n          <!-- Cycle Tracker (shows how many problems seen in this domain) -->\n          <div class=\"cycle-tracker\" style=\"margin-top: 12px; padding: 10px; background: rgba(255,255,255,0.03); border-top: 1px solid var(--border-color); border-radius: 0 0 8px 8px;\">\n            <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;\">\n              <span style=\"font-size: 0.72rem; font-weight: 600; color: var(--text-muted);\">Domain Cycle</span>\n              <button id=\"resetCycleBtn\" class=\"btn-text-subtle\" style=\"font-size: 0.68rem; color: var(--accent-cyan); background: none; border: none; cursor: pointer; padding: 0;\">↺ Reset</button>\n            </div>\n            <div style=\"background: var(--border-color); border-radius: 4px; height: 4px; overflow: hidden; margin-bottom: 5px;\">\n              <div id=\"cycleProgressBar\" style=\"height: 100%; width: 0%; background: var(--accent-cyan); transition: width 0.4s ease; border-radius: 4px;\"></div>\n            </div>\n            <div style=\"display: flex; justify-content: space-between;\">\n              <span id=\"cycleCountText\" style=\"font-size: 0.68rem; color: var(--text-muted);\">0 / 0 seen</span>\n              <span id=\"cycleRemainingText\" style=\"font-size: 0.68rem; color: var(--text-muted);\">0 remaining</span>\n            </div>\n          </div>\n        </div>\n      </aside>\n\n      <!-- CENTER: Spin Wheel -->\n      <section class=\"center-stage\">\n        <div class=\"wheel-wrapper\">\n          <div class=\"wheel-pointer\" id=\"wheelPointer\">\n            <div class=\"pointer-arrow\"></div>\n          </div>\n          <div class=\"canvas-container\">\n            <canvas id=\"wheelCanvas\" width=\"520\" height=\"520\"></canvas>\n            <div class=\"wheel-center-overlay\" id=\"spinCenterBtn\">\n              <div class=\"inner-hub\">\n                <span class=\"hub-spin-text\">SPIN</span>\n                <span class=\"hub-sub-text\">CLICK OR SPACE</span>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"spin-controls\">\n          <div class=\"spin-info-pill\" id=\"spinStatusMessage\">\n            Ready to spin for <strong id=\"spinDomainTarget\">Artificial Intelligence &amp; ML</strong>\n          </div>\n          <div class=\"action-btn-row\">\n            <button id=\"spinMainBtn\" class=\"btn btn-primary btn-xl\">\n              <span class=\"btn-icon\">⚡</span>\n              <span>SPIN PROBLEM WHEEL</span>\n            </button>\n          </div>\n          <p class=\"keyboard-hint\" id=\"keyboardHint\">Tip: Press <kbd>Spacebar</kbd> anytime to spin!</p>\n        </div>\n\n        <!-- Assigned Problem Card (Revealed after the 1 allowed spin is used) -->\n        <div id=\"assignedProblemCard\" class=\"assigned-problem-card hidden\">\n          <div class=\"assigned-card-header\">\n            <span class=\"assigned-lock-pill\">🔒 Your Allocated Challenge (1/1 Spin Completed)</span>\n            <span class=\"assigned-domain-tag\" id=\"assignedCardDomain\">Artificial Intelligence &amp; ML</span>\n          </div>\n          <h3 class=\"assigned-card-title\" id=\"assignedCardTitle\">Problem Statement Title</h3>\n\n          <div class=\"assigned-split-view\">\n            <div class=\"assigned-subcard subcard-problem\">\n              <span class=\"subcard-label\">📌 Problem Statement:</span>\n              <p class=\"assigned-card-desc\" id=\"assignedCardProblem\"></p>\n            </div>\n            <div class=\"assigned-subcard subcard-solution\">\n              <span class=\"subcard-label\">💡 Expected Solution:</span>\n              <p class=\"assigned-card-desc\" id=\"assignedCardSolution\"></p>\n            </div>\n          </div>\n          <p class=\"assigned-card-desc hidden\" id=\"assignedCardDesc\"></p>\n          <div class=\"assigned-card-actions\">\n            <button id=\"assignedCardDownloadPdfBtn\" class=\"btn btn-accent btn-md\">\n              📄 Download Problem Statement (PDF)\n            </button>\n            <button id=\"assignedCardViewBtn\" class=\"btn btn-secondary btn-md\">\n              🔍 View Full Statement\n            </button>\n          </div>\n\n          <!-- GitHub Repo Placing Option on Assigned Challenge Card -->\n          <div id=\"assignedCardGithubRow\" style=\"margin-top: 14px; padding: 10px 14px; background: rgba(255,255,255,0.03); border: 1px dashed var(--border-color); border-radius: 8px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px;\">\n            <div style=\"display: flex; align-items: center; gap: 6px; font-size: 0.82rem;\">\n              <span>🔗</span>\n              <span style=\"color: var(--text-muted);\">Team Repository:</span>\n              <span id=\"assignedCardGithubValue\" style=\"color: var(--text-primary); font-family: var(--font-mono, monospace); font-size: 0.8rem;\">Not linked yet</span>\n            </div>\n            <button type=\"button\" id=\"assignedCardGithubActionBtn\" class=\"btn btn-outline btn-sm\" style=\"font-size: 0.75rem; padding: 4px 10px;\">\n              + Place GitHub Link\n            </button>\n          </div>\n        </div>\n      </section>\n\n      <!-- RIGHT SIDEBAR: Team Info + Recent Draws -->\n      <aside class=\"sidebar sidebar-right\">\n\n        <!-- Team Info Card -->\n        <div class=\"panel-card team-info-panel\">\n          <div class=\"panel-header\">\n            <div class=\"panel-title-group\">\n              <span class=\"panel-icon\">👥</span>\n              <div>\n                <h2>Your Team</h2>\n                <p class=\"panel-sub\">Session active</p>\n              </div>\n            </div>\n            <span class=\"team-session-badge\">🟢 Live</span>\n          </div>\n          <div class=\"team-info-body\">\n            <div class=\"team-info-row\">\n              <span class=\"team-info-label\">Team ID</span>\n              <span class=\"team-info-value\" id=\"teamInfoId\">—</span>\n            </div>\n            <div class=\"team-info-row\">\n              <span class=\"team-info-label\">Team Name</span>\n              <span class=\"team-info-value\" id=\"teamInfoName\">—</span>\n            </div>\n            <div class=\"team-info-row\">\n              <span class=\"team-info-label\">Spin Status</span>\n              <span class=\"team-info-value team-spin-counter\" id=\"teamSpinStatusBadge\" style=\"color:var(--accent-emerald);\">0 / 1 Available</span>\n            </div>\n\n            <!-- Interactive GitHub Repository Section on Main Page -->\n            <div class=\"team-github-section\" style=\"margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--border-color);\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;\">\n                <span class=\"team-info-label\" style=\"display: flex; align-items: center; gap: 5px; font-weight: 600;\">\n                  <span>🔗</span> GitHub Repository\n                </span>\n                <button type=\"button\" id=\"editGithubBtn\" class=\"btn-text-subtle hidden\" style=\"font-size: 0.72rem; color: var(--accent-cyan); cursor: pointer; background: none; border: none; padding: 0;\">\n                  ✏️ Edit\n                </button>\n              </div>\n\n              <!-- Display Mode (when GitHub link is saved) -->\n              <div id=\"teamGithubDisplay\" class=\"hidden\" style=\"background: rgba(6,182,212,0.06); border: 1px solid rgba(6,182,212,0.25); border-radius: 8px; padding: 7px 10px; display: flex; align-items: center; justify-content: space-between; gap: 6px;\">\n                <a id=\"teamInfoGithub\" class=\"team-info-link\" href=\"#\" target=\"_blank\" rel=\"noopener\" style=\"font-size: 0.78rem; text-overflow: ellipsis; overflow: hidden; white-space: nowrap; max-width: 175px; color: var(--accent-cyan); text-decoration: none;\" title=\"Open GitHub Repository\">\n                  —\n                </a>\n                <span style=\"font-size: 0.72rem; color: var(--accent-emerald); font-weight: 600;\" title=\"Saved to team record\">✓ Saved</span>\n              </div>\n\n              <!-- Input Form Mode (to place or change GitHub link) -->\n              <form id=\"teamGithubForm\" style=\"display: flex; gap: 6px; margin-top: 4px;\">\n                <input type=\"url\" id=\"mainGithubInput\" class=\"form-input\" placeholder=\"https://github.com/org/repo\" style=\"padding: 6px 8px; font-size: 0.78rem; flex: 1;\" required>\n                <button type=\"submit\" id=\"saveGithubBtn\" class=\"btn btn-primary btn-sm\" style=\"padding: 6px 10px; font-size: 0.75rem; white-space: nowrap;\">\n                  Save\n                </button>\n              </form>\n            </div>\n\n            <!-- Quick Download Box in sidebar once spun -->\n            <div id=\"teamSidebarPdfBox\" class=\"hidden\" style=\"margin-top:6px;\">\n              <button id=\"teamSidebarDownloadPdfBtn\" class=\"btn btn-accent btn-full btn-sm\">\n                📄 Download Problem PDF\n              </button>\n            </div>\n          </div>\n        </div>\n\n        <!-- Recent Draws History -->\n        <div class=\"panel-card history-panel\">\n          <div class=\"panel-header\">\n            <div class=\"panel-title-group\">\n              <span class=\"panel-icon\">🕒</span>\n              <div>\n                <h3>Assigned Problem</h3>\n                <p class=\"panel-sub\">Your team allocation</p>\n              </div>\n            </div>\n          </div>\n          <div class=\"history-list\" id=\"recentSpinsList\">\n            <div class=\"empty-state\">No spins yet. Choose a domain and spin! (1 spin allowed)</div>\n          </div>\n        </div>\n      </aside>\n    </main>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════════════════ -->\n  <!-- MODAL: Problem Statement Popup                             -->\n  <!-- ═══════════════════════════════════════════════════════════ -->\n  <div class=\"modal-overlay hidden\" id=\"problemModal\">\n    <div class=\"modal-card problem-card-modal\">\n      <button class=\"modal-close\" id=\"closeProblemModal\">&times;</button>\n\n      <div id=\"cycleCompletionAlert\" class=\"cycle-banner hidden\">\n        🎉 <strong>Problem Statement Assigned!</strong> This is your team's official challenge.\n      </div>\n\n      <div class=\"modal-badge-row\">\n        <span class=\"domain-tag\" id=\"modalDomainTag\">Artificial Intelligence &amp; ML</span>\n        <span class=\"difficulty-tag\" id=\"modalDifficultyTag\">Advanced</span>\n        <span class=\"source-tag\" id=\"modalSourceTag\">1/1 Spin Allocated</span>\n      </div>\n\n      <h2 class=\"problem-title\" id=\"modalProblemTitle\">Problem Statement Title</h2>\n\n      <!-- Structured Problem & Solution Presentation (Title | Problem | Expected Solution) -->\n      <div class=\"problem-structure-wrap\">\n        <div class=\"problem-detail-box box-problem\">\n          <div class=\"detail-box-header\">\n            <span class=\"detail-icon\">📌</span>\n            <span class=\"detail-title\">PROBLEM STATEMENT</span>\n          </div>\n          <div class=\"detail-box-content\" id=\"modalProblemText\"></div>\n        </div>\n\n        <div class=\"problem-detail-box box-solution\">\n          <div class=\"detail-box-header\">\n            <span class=\"detail-icon\">💡</span>\n            <span class=\"detail-title\">EXPECTED SOLUTION &amp; DELIVERABLES</span>\n          </div>\n          <div class=\"detail-box-content\" id=\"modalSolutionText\"></div>\n        </div>\n      </div>\n      <p class=\"problem-description hidden\" id=\"modalProblemDescription\"></p>\n\n      <div class=\"tags-container\" id=\"modalTagsContainer\"></div>\n\n      <div class=\"modal-cycle-indicator\">\n        <span class=\"indicator-icon\">🔒</span>\n        <span id=\"modalCycleStatusText\">Permanent Team Allocation (1/1 Spin Used)</span>\n      </div>\n\n      <div class=\"modal-footer-actions\">\n        <button id=\"modalDownloadPdfBtn\" class=\"btn btn-accent\">\n          📄 Download Problem PDF\n        </button>\n        <button id=\"copyProblemBtn\" class=\"btn btn-secondary\">\n          📋 Copy Statement\n        </button>\n        <button id=\"dismissProblemModalBtn\" class=\"btn btn-primary\">\n          ✕ Close\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════════════════ -->\n  <!-- MODAL: Explore Problem Pool (read-only view)               -->\n  <!-- ═══════════════════════════════════════════════════════════ -->\n  <div class=\"modal-overlay hidden\" id=\"exploreModal\">\n    <div class=\"modal-card manager-modal\">\n      <div class=\"manager-modal-header\">\n        <div>\n          <h2>📚 Problem Statement Pool</h2>\n          <p class=\"panel-sub\">Browse all available problem statements</p>\n        </div>\n        <button class=\"modal-close\" id=\"closeExploreModal\">&times;</button>\n      </div>\n\n      <div class=\"filter-bar\">\n        <input type=\"text\" id=\"exploreSearchInput\" class=\"form-input\" placeholder=\"Search by title, description, or tag...\">\n        <select id=\"exploreDomainFilter\" class=\"form-select\">\n          <option value=\"All\">All Domains</option>\n        </select>\n      </div>\n      <div class=\"table-container\">\n        <table class=\"data-table\">\n          <thead>\n            <tr>\n              <th>Domain</th>\n              <th>Title &amp; Description</th>\n              <th>Difficulty</th>\n              <th>Source</th>\n            </tr>\n          </thead>\n          <tbody id=\"exploreProblemsTableBody\">\n            <!-- Rendered by JS -->\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- Toast Notifications -->\n  <div id=\"toastContainer\" class=\"toast-container\"></div>\n\n  <!-- Subtle Admin Access Link -->\n  <a href=\"/admin\" class=\"admin-corner-link\" title=\"Admin Dashboard\">⚙️ Admin</a>\n\n  <script src=\"app.js?v=20261005_8\"></script>\n</body>\n</html>\n",
  "admin.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>SpinQuest PS — Admin Dashboard</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"style.css?v=20261005_6\">\n  <style>\n    /* ─── ADMIN PAGE SPECIFIC STYLES ─────────────────────────────────── */\n    .admin-login-screen {\n      min-height: 100vh;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      background: var(--bg-primary);\n      background-image:\n        radial-gradient(circle at 50% 0%, rgba(99,102,241,0.18) 0%, transparent 60%),\n        radial-gradient(circle at 10% 80%, rgba(6,182,212,0.1) 0%, transparent 40%);\n    }\n    .admin-login-card {\n      background: var(--bg-card);\n      border: 1px solid var(--border-color);\n      border-radius: var(--radius-lg);\n      padding: 48px 44px;\n      width: 100%;\n      max-width: 420px;\n      box-shadow: var(--shadow-card);\n    }\n    .admin-login-logo {\n      text-align: center;\n      margin-bottom: 28px;\n    }\n    .admin-login-logo .logo-circle {\n      width: 64px; height: 64px; border-radius: 50%;\n      background: linear-gradient(135deg, rgba(6,182,212,0.2), rgba(139,92,246,0.2));\n      border: 1px solid rgba(255,255,255,0.15);\n      display: flex; align-items: center; justify-content: center;\n      font-size: 28px; margin: 0 auto 14px;\n      box-shadow: 0 0 20px rgba(6,182,212,0.3);\n    }\n    .admin-login-logo h2 { font-size: 1.4rem; font-weight: 800; margin-bottom: 4px; }\n    .admin-login-logo p { color: var(--text-muted); font-size: 0.85rem; }\n\n    /* Dashboard layout */\n    .admin-dashboard { min-height: 100vh; display: flex; flex-direction: column; }\n    .admin-navbar {\n      height: 68px; display: flex; align-items: center;\n      justify-content: space-between; padding: 0 32px;\n      background: rgba(18,24,38,0.9); backdrop-filter: blur(14px);\n      border-bottom: 1px solid var(--border-color);\n      position: sticky; top: 0; z-index: 100;\n    }\n    .admin-nav-brand { display: flex; align-items: center; gap: 12px; }\n    .admin-badge {\n      background: rgba(16,185,129,0.15); color: #34d399;\n      border: 1px solid rgba(16,185,129,0.3);\n      padding: 4px 12px; border-radius: var(--radius-full);\n      font-size: 0.78rem; font-weight: 700;\n    }\n    .admin-content { flex: 1; padding: 28px 32px; max-width: 1400px; margin: 0 auto; width: 100%; }\n\n    /* Tabs */\n    .admin-tabs {\n      display: flex;\n      gap: 4px;\n      border-bottom: 1px solid var(--border-color);\n      margin-bottom: 20px;\n      overflow-x: auto;\n      white-space: nowrap;\n      -webkit-overflow-scrolling: touch;\n      scrollbar-width: none;\n      padding-bottom: 2px;\n    }\n    .admin-tabs::-webkit-scrollbar { display: none; }\n    .admin-tab {\n      padding: 10px 18px; font-size: 0.86rem; font-weight: 600;\n      color: var(--text-muted); background: none; border: none;\n      border-bottom: 3px solid transparent; cursor: pointer;\n      transition: all 0.2s; border-radius: var(--radius-sm) var(--radius-sm) 0 0;\n      flex-shrink: 0;\n    }\n    .admin-tab:hover { color: var(--text-main); background: rgba(255,255,255,0.04); }\n    .admin-tab.active { color: var(--accent-cyan); border-bottom-color: var(--accent-cyan); }\n\n    /* Stats grid */\n    .stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; margin-bottom: 24px; }\n    .stat-card {\n      background: var(--bg-card); border: 1px solid var(--border-color);\n      border-radius: var(--radius-md); padding: 20px;\n    }\n    .stat-card-value { font-size: 2rem; font-weight: 800; color: var(--accent-cyan); line-height: 1; }\n    .stat-card-label { font-size: 0.8rem; color: var(--text-muted); margin-top: 6px; }\n\n    /* Teams table */\n    .teams-table-wrap {\n      background: var(--bg-card);\n      border: 1px solid var(--border-color);\n      border-radius: var(--radius-md);\n      overflow-x: auto;\n      -webkit-overflow-scrolling: touch;\n      width: 100%;\n      max-width: 100%;\n    }\n    .teams-table { width: 100%; min-width: 880px; border-collapse: collapse; }\n    .teams-table th { padding: 12px 16px; font-size: 0.75rem; font-weight: 700; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.05em; background: rgba(255,255,255,0.03); border-bottom: 1px solid var(--border-color); text-align: left; }\n    .teams-table td { padding: 12px 16px; font-size: 0.85rem; border-bottom: 1px solid rgba(255,255,255,0.04); vertical-align: top; }\n    .teams-table tr:last-child td { border-bottom: none; }\n    .teams-table tr:hover td { background: rgba(255,255,255,0.02); }\n    .expand-btn { background: none; border: 1px solid var(--border-color); color: var(--text-muted); padding: 4px 10px; border-radius: var(--radius-sm); font-size: 0.75rem; cursor: pointer; }\n    .expand-btn:hover { color: var(--accent-cyan); border-color: var(--accent-cyan); }\n    .spins-detail { background: rgba(0,0,0,0.2); border-radius: var(--radius-sm); margin: 8px 0; padding: 10px 12px; display: none; }\n    .spin-entry { padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.05); font-size: 0.8rem; }\n    .spin-entry:last-child { border-bottom: none; }\n    .spin-domain-badge { display: inline-block; font-size: 0.68rem; background: rgba(6,182,212,0.15); color: var(--accent-cyan); border-radius: 4px; padding: 1px 7px; margin-right: 6px; }\n\n    /* Upload form */\n    .upload-section { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: var(--radius-md); padding: 24px; margin-bottom: 20px; }\n\n    /* Toolbar */\n    .section-toolbar { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; gap: 12px; flex-wrap: wrap; }\n    .toolbar-left { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }\n    .toolbar-right { display: flex; gap: 10px; }\n\n    .back-to-main { display: inline-flex; align-items: center; gap: 6px; color: var(--text-muted); font-size: 0.82rem; text-decoration: none; }\n    .back-to-main:hover { color: var(--text-main); }\n\n    .empty-table-row td { text-align: center; padding: 36px; color: var(--text-muted); font-size: 0.9rem; }\n\n    /* Mobile scroll hint */\n    .mobile-scroll-hint {\n      display: none;\n      font-size: 0.75rem;\n      color: var(--accent-cyan);\n      background: rgba(6, 182, 212, 0.08);\n      border: 1px solid rgba(6, 182, 212, 0.2);\n      border-radius: var(--radius-sm);\n      padding: 6px 10px;\n      margin-bottom: 8px;\n      text-align: center;\n      font-weight: 600;\n    }\n\n    /* ─── MOBILE RESPONSIVE MEDIA QUERIES ──────────────────────── */\n    @media (max-width: 860px) {\n      .admin-navbar {\n        height: auto;\n        min-height: 56px;\n        padding: 10px 14px;\n        flex-wrap: wrap;\n        gap: 8px;\n        justify-content: space-between;\n      }\n      .admin-content {\n        padding: 14px 10px;\n        width: 100%;\n        max-width: 100%;\n      }\n      .mobile-scroll-hint {\n        display: block;\n      }\n      .section-toolbar {\n        flex-direction: column !important;\n        align-items: stretch !important;\n        gap: 10px !important;\n        margin-bottom: 14px !important;\n      }\n      .toolbar-left {\n        flex-direction: column !important;\n        width: 100% !important;\n        gap: 8px !important;\n      }\n      .toolbar-left .form-input,\n      .toolbar-left .form-select,\n      #teamSearchInput,\n      #teamStatusFilter,\n      #teamDomainFilter,\n      #psSearchInput,\n      #psDomainFilter,\n      #newDomainName {\n        width: 100% !important;\n        min-width: 100% !important;\n        min-height: 42px;\n        font-size: 14px;\n        box-sizing: border-box;\n      }\n      .toolbar-right {\n        display: grid !important;\n        grid-template-columns: repeat(2, 1fr) !important;\n        width: 100% !important;\n        gap: 8px !important;\n      }\n      .toolbar-right #downloadPdfBtn {\n        grid-column: 1 / -1 !important;\n        width: 100% !important;\n        justify-content: center !important;\n        text-align: center !important;\n        padding: 10px 12px !important;\n        font-weight: 700 !important;\n        min-height: 40px !important;\n      }\n      .toolbar-right .btn-sm {\n        width: 100% !important;\n        justify-content: center !important;\n        text-align: center !important;\n        padding: 9px 8px !important;\n        font-size: 0.78rem !important;\n        min-height: 38px !important;\n      }\n      .stats-grid {\n        grid-template-columns: repeat(2, 1fr);\n        gap: 10px;\n        margin-bottom: 16px;\n      }\n      .stat-card {\n        padding: 12px 14px;\n      }\n      .stat-card-value {\n        font-size: 1.5rem;\n      }\n      .stat-card-label {\n        font-size: 0.74rem;\n      }\n      #teamDetailsModal .modal-card {\n        padding: 16px 12px !important;\n        width: 96% !important;\n        max-width: 100% !important;\n        max-height: 94vh !important;\n      }\n      #teamDetailsModal .modal-card > div[style*=\"grid-template-columns\"] {\n        grid-template-columns: 1fr !important;\n        gap: 8px !important;\n        padding: 10px !important;\n      }\n      #teamDetailsModal .modal-card > div:last-child {\n        flex-direction: column !important;\n        align-items: stretch !important;\n        gap: 8px !important;\n      }\n      #teamDetailsModal .modal-card > div:last-child > div {\n        width: 100% !important;\n        display: flex !important;\n        gap: 8px !important;\n      }\n      #teamDetailsModal .modal-card > div:last-child button {\n        width: 100% !important;\n        justify-content: center !important;\n      }\n    }\n\n    @media (max-width: 500px) {\n      .admin-login-screen {\n        padding: 12px;\n      }\n      .admin-login-card {\n        padding: 26px 16px 20px;\n        width: 100%;\n        max-width: 100%;\n        border-radius: var(--radius-md);\n      }\n      .admin-login-logo .logo-circle {\n        width: 50px;\n        height: 50px;\n        font-size: 22px;\n        margin-bottom: 8px;\n      }\n      .admin-login-logo h2 {\n        font-size: 1.25rem;\n      }\n      #adminWelcomeText {\n        display: none;\n      }\n    }\n  </style>\n</head>\n<body>\n\n  <!-- ═══════════════════════════════════════════════════ -->\n  <!-- ADMIN LOGIN SCREEN                                  -->\n  <!-- ═══════════════════════════════════════════════════ -->\n  <div id=\"adminLoginScreen\" class=\"admin-login-screen\">\n    <div class=\"admin-login-card\">\n      <div class=\"admin-login-logo\">\n        <div class=\"logo-circle\">🔐</div>\n        <h2>Admin Dashboard</h2>\n        <p>SpinQuest PS — Event Management</p>\n      </div>\n\n      <form id=\"adminLoginForm\" autocomplete=\"off\">\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"adminUsername\">Username</label>\n          <input type=\"text\" id=\"adminUsername\" class=\"form-input\" placeholder=\"Enter admin username\" required autocomplete=\"username\">\n        </div>\n        <div class=\"form-group\">\n          <label class=\"form-label\" for=\"adminPassword\">Password</label>\n          <div class=\"password-input-wrap\">\n            <input type=\"password\" id=\"adminPassword\" class=\"form-input\" placeholder=\"Enter admin password\" required autocomplete=\"current-password\">\n            <button type=\"button\" id=\"toggleAdminPwd\" class=\"btn-toggle-eye\" title=\"Toggle visibility\">👁️</button>\n          </div>\n        </div>\n        <div id=\"adminLoginError\" class=\"form-error hidden\"></div>\n        <button type=\"submit\" class=\"btn btn-accent btn-full btn-lg\" style=\"margin-top:8px;\">\n          Sign In as Admin\n        </button>\n      </form>\n\n      <div style=\"text-align:center; margin-top:20px;\">\n        <a href=\"/\" class=\"back-to-main\">← Back to SpinQuest PS</a>\n      </div>\n    </div>\n  </div>\n\n  <!-- ═══════════════════════════════════════════════════ -->\n  <!-- ADMIN DASHBOARD (shown after login)                 -->\n  <!-- ═══════════════════════════════════════════════════ -->\n  <div id=\"adminDashboard\" class=\"admin-dashboard hidden\">\n\n    <!-- Admin Navbar -->\n    <nav class=\"admin-navbar\">\n      <div class=\"admin-nav-brand\">\n        <div class=\"logo-icon\" style=\"font-size:22px; width:38px; height:38px;\">🎯</div>\n        <div>\n          <span style=\"font-weight:800; font-size:1.05rem;\">SpinQuest <span class=\"brand-accent\">PS</span></span>\n          <span class=\"admin-badge\" style=\"margin-left:10px;\">🛡️ Admin</span>\n        </div>\n      </div>\n      <div style=\"display:flex; align-items:center; gap:16px;\">\n        <span id=\"adminWelcomeText\" style=\"font-size:0.85rem; color:var(--text-muted);\"></span>\n        <a href=\"/\" class=\"btn btn-secondary btn-sm\">← Main Site</a>\n        <button id=\"adminLogoutBtn\" class=\"btn btn-outline btn-sm\">Logout</button>\n      </div>\n    </nav>\n\n    <div class=\"admin-content\">\n\n      <!-- Dashboard Tabs -->\n      <div class=\"admin-tabs\">\n        <button class=\"admin-tab active\" data-atab=\"tabTeams\">👥 Teams Activity</button>\n        <button class=\"admin-tab\" data-atab=\"tabDomains\">📂 Domains</button>\n        <button class=\"admin-tab\" data-atab=\"tabProblems\">📋 Problem Statements</button>\n        <button class=\"admin-tab\" data-atab=\"tabUpload\">📤 Upload Documents</button>\n        <button class=\"admin-tab\" data-atab=\"tabDocuments\">🗂️ Uploaded Files</button>\n        <button class=\"admin-tab\" data-atab=\"tabAddTeams\" style=\"color:#34d399;\">➕ Add Teams</button>\n      </div>\n\n      <!-- ── TAB: TEAMS ACTIVITY ─────────────────────────────────── -->\n      <div id=\"tabTeams\" class=\"admin-tab-content\">\n        <!-- Stats -->\n        <div class=\"stats-grid\">\n          <div class=\"stat-card\">\n            <div class=\"stat-card-value\" id=\"statTotalTeams\">101</div>\n            <div class=\"stat-card-label\">Total Registered Teams</div>\n          </div>\n          <div class=\"stat-card\">\n            <div class=\"stat-card-value\" id=\"statTotalAllocated\" style=\"color:#34d399;\">0</div>\n            <div class=\"stat-card-label\">Problems Allocated</div>\n          </div>\n          <div class=\"stat-card\">\n            <div class=\"stat-card-value\" id=\"statTotalPending\" style=\"color:#f59e0b;\">0</div>\n            <div class=\"stat-card-label\">Pending Allocation</div>\n          </div>\n          <div class=\"stat-card\">\n            <div class=\"stat-card-value\" id=\"statActiveDomains\" style=\"color:#a855f7;\">5</div>\n            <div class=\"stat-card-label\">Hackathon Tracks</div>\n          </div>\n        </div>\n\n        <!-- Actions row -->\n        <div class=\"section-toolbar\" style=\"gap:12px; flex-wrap:wrap;\">\n          <div class=\"toolbar-left\" style=\"gap:10px; flex-wrap:wrap;\">\n            <input type=\"text\" id=\"teamSearchInput\" class=\"form-input\" style=\"width:230px;\" placeholder=\"Search ID, Team, Leader, College...\">\n            <select id=\"teamStatusFilter\" class=\"form-input\" style=\"width:140px;\">\n              <option value=\"All\">All Statuses</option>\n              <option value=\"Allocated\">🟢 Allocated</option>\n              <option value=\"Pending\">⏳ Pending</option>\n            </select>\n            <select id=\"teamDomainFilter\" class=\"form-input\" style=\"width:160px;\">\n              <option value=\"All\">All Tracks</option>\n            </select>\n          </div>\n          <div class=\"toolbar-right\" style=\"gap:8px; flex-wrap:wrap;\">\n            <button id=\"exportCsvBtn\" class=\"btn btn-secondary btn-sm\" title=\"Download Excel-compatible CSV of all teams\">📊 Export CSV</button>\n            <button id=\"backupJsonBtn\" class=\"btn btn-secondary btn-sm\" title=\"Download complete database JSON backup\">💾 Backup JSON</button>\n            <button id=\"triggerRestoreBtn\" class=\"btn btn-secondary btn-sm\" title=\"Restore database from JSON file\">📂 Restore</button>\n            <input type=\"file\" id=\"restoreJsonInput\" accept=\".json\" style=\"display:none;\">\n            <button id=\"refreshTeamsBtn\" class=\"btn btn-secondary btn-sm\">🔄 Refresh</button>\n            <a id=\"downloadPdfBtn\" href=\"#\" class=\"btn btn-accent btn-sm\">📄 Master PDF Report</a>\n          </div>\n        </div>\n\n        <!-- Mobile Scroll Hint -->\n        <div class=\"mobile-scroll-hint\">👉 Swipe table horizontally to view full team details (Leader, College, PS, Actions)</div>\n\n        <!-- Teams Table -->\n        <div class=\"teams-table-wrap\">\n          <table class=\"teams-table\">\n            <thead>\n              <tr>\n                <th style=\"width: 36px;\">#</th>\n                <th style=\"width: 130px;\">Reg ID</th>\n                <th style=\"width: 150px;\">Team Name</th>\n                <th style=\"width: 160px;\">Leader &amp; Contact</th>\n                <th style=\"width: 180px;\">College</th>\n                <th style=\"width: 150px;\">Track / Domain</th>\n                <th>Allocated Problem Statement</th>\n                <th style=\"width: 95px;\">Status</th>\n                <th style=\"width: 120px;\">Actions</th>\n              </tr>\n            </thead>\n            <tbody id=\"teamsTableBody\">\n              <tr class=\"empty-table-row\"><td colspan=\"9\">Loading teams...</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n      <!-- ── TAB: DOMAINS ────────────────────────────────────────── -->\n      <div id=\"tabDomains\" class=\"admin-tab-content hidden\">\n        <div class=\"section-toolbar\">\n          <h3 style=\"font-size:1rem; font-weight:700;\">Manage Domains</h3>\n          <div class=\"toolbar-right\">\n            <input type=\"text\" id=\"newDomainName\" class=\"form-input\" style=\"width:240px;\" placeholder=\"e.g. Robotics & Automation\">\n            <button id=\"addDomainBtn\" class=\"btn btn-primary btn-sm\">+ Add Domain</button>\n          </div>\n        </div>\n        <div class=\"teams-table-wrap\">\n          <table class=\"teams-table\">\n            <thead><tr><th>Domain Name</th><th>Problems</th><th>Actions</th></tr></thead>\n            <tbody id=\"domainsTableBody\">\n              <tr class=\"empty-table-row\"><td colspan=\"3\">Loading...</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n      <!-- ── TAB: PROBLEM STATEMENTS ────────────────────────────── -->\n      <div id=\"tabProblems\" class=\"admin-tab-content hidden\">\n        <div class=\"section-toolbar\">\n          <div class=\"toolbar-left\">\n            <input type=\"text\" id=\"psSearchInput\" class=\"form-input\" style=\"width:220px;\" placeholder=\"Search problems...\">\n            <select id=\"psDomainFilter\" class=\"form-select\" style=\"width:200px;\">\n              <option value=\"All\">All Domains</option>\n            </select>\n          </div>\n          <div class=\"toolbar-right\" style=\"display:flex; gap:8px;\">\n            <button id=\"clearAllPsBtn\" class=\"btn btn-sm\" style=\"background:rgba(239,68,68,0.15); border:1px solid rgba(239,68,68,0.35); color:#f87171; font-weight:600;\" title=\"Delete all problem statements\">🗑️ Clear All Problems</button>\n            <button id=\"showAddPsFormBtn\" class=\"btn btn-primary btn-sm\">+ Add Manually</button>\n          </div>\n        </div>\n\n        <!-- Add PS inline form -->\n        <div id=\"addPsFormWrap\" class=\"upload-section hidden\" style=\"margin-bottom:16px;\">\n          <h4 style=\"font-size:0.9rem; font-weight:700; margin-bottom:14px;\">Add Custom Problem Statement</h4>\n          <form id=\"addPsForm\">\n            <div class=\"form-row\">\n              <div class=\"form-group flex-1\">\n                <label class=\"form-label\">Domain</label>\n                <select id=\"psNewDomain\" class=\"form-select\" required></select>\n              </div>\n              <div class=\"form-group flex-1\">\n                <label class=\"form-label\">Difficulty</label>\n                <select id=\"psNewDifficulty\" class=\"form-select\">\n                  <option value=\"Beginner\">Beginner</option>\n                  <option value=\"Intermediate\" selected>Intermediate</option>\n                  <option value=\"Advanced\">Advanced</option>\n                </select>\n              </div>\n            </div>\n            <div class=\"form-group\">\n              <label class=\"form-label\">Problem Title</label>\n              <input type=\"text\" id=\"psNewTitle\" class=\"form-input\" placeholder=\"e.g. AI-Powered Smart Grid Balancer\" required>\n            </div>\n            <div class=\"form-group\">\n              <label class=\"form-label\">Challenge Description</label>\n              <textarea id=\"psNewDesc\" class=\"form-textarea\" rows=\"3\" placeholder=\"Detailed problem description...\" required></textarea>\n            </div>\n            <div class=\"form-group\">\n              <label class=\"form-label\">Tags (comma-separated)</label>\n              <input type=\"text\" id=\"psNewTags\" class=\"form-input\" placeholder=\"AI, Python, IoT\">\n            </div>\n            <div style=\"display:flex; gap:10px;\">\n              <button type=\"submit\" class=\"btn btn-accent btn-sm\">Add Problem Statement</button>\n              <button type=\"button\" id=\"cancelAddPsBtn\" class=\"btn btn-secondary btn-sm\">Cancel</button>\n            </div>\n          </form>\n        </div>\n\n        <div class=\"teams-table-wrap\">\n          <table class=\"teams-table\">\n            <thead><tr><th>Domain</th><th>Title & Description</th><th>Difficulty</th><th>Source</th><th>Actions</th></tr></thead>\n          <tbody id=\"psTableBody\">\n            <tr class=\"empty-table-row\"><td colspan=\"5\">Loading...</td></tr>\n          </tbody>\n          </table>\n        </div>\n      </div>\n\n      <!-- ── TAB: UPLOAD DOCUMENTS ──────────────────────────────── -->\n      <div id=\"tabUpload\" class=\"admin-tab-content hidden\">\n        <div class=\"upload-section\">\n          <h4 style=\"font-size:1rem; font-weight:700; margin-bottom:18px;\">Upload Problem Statement Documents</h4>\n          <form id=\"adminUploadForm\">\n            <div class=\"form-group\">\n              <label class=\"form-label\">Target Domain</label>\n              <select id=\"uploadDomainSelect\" class=\"form-select\" required style=\"max-width:360px;\"></select>\n            </div>\n            <div class=\"drop-zone-container\" style=\"margin-top:12px;\">\n              <div class=\"drop-zone\" id=\"adminDropZone\">\n                <input type=\"file\" id=\"adminFileInput\" name=\"file\" accept=\".pdf,.doc,.docx,.txt,.csv,.json,.md\" class=\"file-input-hidden\">\n                <div class=\"drop-zone-content\">\n                  <div class=\"drop-icon\">📤</div>\n                  <p class=\"drop-primary-text\">Drag &amp; drop your document here</p>\n                  <p class=\"drop-secondary-text\">or <span class=\"browse-link\">browse files</span></p>\n                  <div class=\"supported-formats-pills\">\n                    <span class=\"format-pill\">PDF</span><span class=\"format-pill\">DOCX</span>\n                    <span class=\"format-pill\">TXT</span><span class=\"format-pill\">CSV</span><span class=\"format-pill\">JSON</span>\n                  </div>\n                </div>\n              </div>\n              <div id=\"adminSelectedFile\" class=\"selected-file-card hidden\">\n                <div class=\"selected-file-info-left\">\n                  <span class=\"file-card-icon\">📄</span>\n                  <div class=\"selected-file-texts\">\n                    <strong id=\"adminFileName\">file.pdf</strong>\n                    <span id=\"adminFileSize\" class=\"file-size-sub\">0 KB</span>\n                  </div>\n                </div>\n                <button type=\"button\" id=\"adminRemoveFile\" class=\"btn-cancel-file\">✕ Cancel</button>\n              </div>\n            </div>\n            <button type=\"submit\" id=\"adminUploadBtn\" class=\"btn btn-accent btn-md\" style=\"margin-top:14px;\" disabled>\n              Extract &amp; Add Problem Statements\n            </button>\n          </form>\n        </div>\n        <div id=\"uploadResultBox\" class=\"hidden\" style=\"background:rgba(16,185,129,0.1);border:1px solid rgba(16,185,129,0.3);border-radius:var(--radius-md);padding:16px;margin-top:4px;\">\n          <strong style=\"color:#34d399;\">✅ Upload Successful!</strong>\n          <p id=\"uploadResultMsg\" style=\"color:#94a3b8;font-size:0.85rem;margin-top:6px;\"></p>\n        </div>\n      </div>\n\n      <!-- ── TAB: UPLOADED FILES ────────────────────────────────── -->\n      <div id=\"tabDocuments\" class=\"admin-tab-content hidden\">\n        <div class=\"section-toolbar\">\n          <h3 style=\"font-size:1rem; font-weight:700;\">Uploaded Documents</h3>\n          <button id=\"refreshDocsBtn\" class=\"btn btn-secondary btn-sm\">🔄 Refresh</button>\n        </div>\n        <div class=\"teams-table-wrap\">\n          <table class=\"teams-table\">\n            <thead><tr><th>Filename</th><th>Target Domain</th><th>Problems Extracted</th><th>Uploaded At</th><th>Actions</th></tr></thead>\n            <tbody id=\"docsTableBody\">\n              <tr class=\"empty-table-row\"><td colspan=\"5\">Loading...</td></tr>\n            </tbody>\n          </table>\n        </div>\n\n        <div style=\"margin-top:20px;padding-top:16px;border-top:1px solid var(--border-color);\">\n          <button id=\"resetDataBtn\" class=\"btn-text-subtle\" title=\"Restore default problem statements\">↺ Restore Default Problem Statements</button>\n        </div>\n      </div>\n\n      <!-- ── TAB: ADD TEAMS ─────────────────────────────────────────── -->\n      <div id=\"tabAddTeams\" class=\"admin-tab-content hidden\" style=\"margin-top: -20px; padding: 0 0 20px;\">\n\n        <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 24px; align-items: start;\">\n\n          <!-- Left: Add Team Form -->\n          <div class=\"upload-section\" style=\"margin-bottom:0;\">\n            <h3 style=\"font-size:1.05rem;font-weight:800;margin-bottom:4px;\">➕ Add New Team</h3>\n            <p style=\"font-size:0.8rem;color:var(--text-muted);margin-bottom:18px;\">Add teams beyond the original 101. New teams can log in and spin immediately.</p>\n\n            <form id=\"addTeamForm\" autocomplete=\"off\">\n              <div class=\"form-group\">\n                <label class=\"form-label\">Reg ID / Team ID <span style=\"color:#f43f5e;\">*</span></label>\n                <input type=\"text\" id=\"newTeamRegId\" class=\"form-input\" placeholder=\"e.g. CODIENYCH-2026-0102\" required maxlength=\"40\">\n                <small style=\"color:var(--text-muted);font-size:0.72rem;\">Must be unique. Teams log in using this ID.</small>\n              </div>\n              <div class=\"form-group\">\n                <label class=\"form-label\">Team Name <span style=\"color:#f43f5e;\">*</span></label>\n                <input type=\"text\" id=\"newTeamName\" class=\"form-input\" placeholder=\"e.g. The Code Wizards\" required maxlength=\"80\">\n              </div>\n              <div class=\"form-group\">\n                <label class=\"form-label\">Domain / Track</label>\n                <select id=\"newTeamDomain\" class=\"form-select\">\n                  <option value=\"Artificial Intelligence &amp; ML\">Artificial Intelligence &amp; ML</option>\n                  <option value=\"Web &amp; Mobile Development\">Web &amp; Mobile Development</option>\n                  <option value=\"Internet of Things (IoT)\">Internet of Things (IoT)</option>\n                  <option value=\"Cybersecurity &amp; Privacy\">Cybersecurity &amp; Privacy</option>\n                  <option value=\"Cloud &amp; DevOps\">Cloud &amp; DevOps</option>\n                </select>\n              </div>\n              <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px;\">\n                <div class=\"form-group\">\n                  <label class=\"form-label\">Leader Name</label>\n                  <input type=\"text\" id=\"newTeamLeader\" class=\"form-input\" placeholder=\"Team leader name\" maxlength=\"60\">\n                </div>\n                <div class=\"form-group\">\n                  <label class=\"form-label\">Phone</label>\n                  <input type=\"text\" id=\"newTeamPhone\" class=\"form-input\" placeholder=\"+91 XXXXXXXXXX\" maxlength=\"20\">\n                </div>\n              </div>\n              <div class=\"form-group\">\n                <label class=\"form-label\">College / Institution</label>\n                <input type=\"text\" id=\"newTeamCollege\" class=\"form-input\" placeholder=\"College name\" maxlength=\"100\">\n              </div>\n              <div class=\"form-group\">\n                <label class=\"form-label\">Members (comma-separated)</label>\n                <input type=\"text\" id=\"newTeamMembers\" class=\"form-input\" placeholder=\"Name1, Name2, Name3\" maxlength=\"200\">\n              </div>\n              <div id=\"addTeamMsg\" class=\"hidden\" style=\"margin-bottom:10px;padding:8px 12px;border-radius:6px;font-size:0.83rem;font-weight:600;\"></div>\n              <button type=\"submit\" id=\"addTeamSubmitBtn\" class=\"btn btn-accent btn-full\">\n                <span id=\"addTeamBtnLabel\">➕ Add Team</span>\n              </button>\n            </form>\n          </div>\n\n          <!-- Right: Custom Teams List -->\n          <div>\n            <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;\">\n              <div>\n                <h3 style=\"font-size:1.05rem;font-weight:800;margin-bottom:2px;\">📋 Custom Added Teams</h3>\n                <p style=\"font-size:0.78rem;color:var(--text-muted);\">Teams added by admin beyond the original 101</p>\n              </div>\n              <button id=\"refreshCustomTeamsBtn\" class=\"btn btn-secondary btn-sm\">🔄 Refresh</button>\n            </div>\n\n            <div id=\"customTeamsCount\" style=\"margin-bottom:10px;font-size:0.8rem;color:var(--text-muted);\">Loading...</div>\n\n            <div style=\"max-height:520px;overflow-y:auto;border:1px solid var(--border-color);border-radius:var(--radius-md);\">\n              <table class=\"teams-table\" style=\"min-width:auto;\">\n                <thead>\n                  <tr>\n                    <th>Reg ID</th>\n                    <th>Team Name</th>\n                    <th>Domain</th>\n                    <th>Action</th>\n                  </tr>\n                </thead>\n                <tbody id=\"customTeamsTableBody\">\n                  <tr class=\"empty-table-row\"><td colspan=\"4\">Loading...</td></tr>\n                </tbody>\n              </table>\n            </div>\n\n            <div style=\"margin-top:12px;padding:10px 14px;background:rgba(255,193,7,0.06);border:1px solid rgba(255,193,7,0.2);border-radius:8px;font-size:0.78rem;color:#fbbf24;\">\n              ⚠️ Deleting a custom team removes their login access. Their spin data in Teams Activity is unaffected.\n            </div>\n          </div>\n        </div>\n\n        <!-- Mobile: stack on small screens -->\n        <style>\n          @media(max-width:860px){\n            #tabAddTeams > div { grid-template-columns: 1fr !important; }\n          }\n        </style>\n      </div>\n      <!-- /tabAddTeams -->\n\n    </div><!-- /admin-content -->\n  </div><!-- /adminDashboard -->\n\n  <!-- Team Details Modal -->\n  <div id=\"teamDetailsModal\" class=\"modal-backdrop hidden\" style=\"position:fixed;inset:0;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;z-index:999;padding:16px;\">\n    <div class=\"modal-card\" style=\"background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius-lg);max-width:620px;width:100%;max-height:90vh;overflow-y:auto;padding:24px;box-shadow:0 20px 40px rgba(0,0,0,0.5);\">\n      <div style=\"display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px;border-bottom:1px solid var(--border-color);padding-bottom:12px;\">\n        <div>\n          <div style=\"display:flex;align-items:center;gap:8px;\">\n            <code id=\"modalTeamId\" style=\"color:#38bdf8;font-weight:700;font-size:0.95rem;\">CODIENYCH-2026-0001</code>\n            <span id=\"modalTeamStatusBadge\" class=\"domain-tag\" style=\"font-size:0.75rem;\">Status</span>\n          </div>\n          <h2 id=\"modalTeamName\" style=\"font-size:1.3rem;font-weight:800;color:#fff;margin-top:4px;\">Team Name</h2>\n        </div>\n        <button id=\"closeTeamModalBtn\" class=\"expand-btn\" style=\"font-size:1.1rem;padding:4px 10px;\">✕</button>\n      </div>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;background:rgba(255,255,255,0.02);padding:14px;border-radius:var(--radius-md);border:1px solid rgba(255,255,255,0.05);font-size:0.85rem;\">\n        <div><strong style=\"color:var(--text-muted);display:block;font-size:0.75rem;\">TEAM LEADER</strong> <span id=\"modalLeader\">—</span></div>\n        <div><strong style=\"color:var(--text-muted);display:block;font-size:0.75rem;\">PHONE / CONTACT</strong> <span id=\"modalPhone\">—</span></div>\n        <div><strong style=\"color:var(--text-muted);display:block;font-size:0.75rem;\">EMAIL</strong> <span id=\"modalEmail\">—</span></div>\n        <div><strong style=\"color:var(--text-muted);display:block;font-size:0.75rem;\">REGISTERED TRACK</strong> <span id=\"modalTrack\" style=\"color:#38bdf8;\">—</span></div>\n        <div style=\"grid-column:1 / -1;\"><strong style=\"color:var(--text-muted);display:block;font-size:0.75rem;\">COLLEGE / INSTITUTION</strong> <span id=\"modalCollege\">—</span></div>\n        <div style=\"grid-column:1 / -1;\"><strong style=\"color:var(--text-muted);display:block;font-size:0.75rem;\">TEAM MEMBERS</strong> <span id=\"modalMembers\">—</span></div>\n        <div><strong style=\"color:var(--text-muted);display:block;font-size:0.75rem;\">UTR / PAYMENT REF</strong> <span id=\"modalUtr\" style=\"font-family:monospace;font-size:0.8rem;color:#94a3b8;\">—</span></div>\n        <div><strong style=\"color:var(--text-muted);display:block;font-size:0.75rem;\">GITHUB REPO</strong> <span id=\"modalGithub\">—</span></div>\n      </div>\n\n      <!-- Problem statement section -->\n      <div id=\"modalProblemSection\" style=\"margin-bottom:18px;\">\n        <h4 style=\"font-size:0.85rem;text-transform:uppercase;color:#0284c7;letter-spacing:0.05em;margin-bottom:8px;\">Allocated Problem Statement</h4>\n        <div id=\"modalProblemBox\" style=\"background:#0f172a;border:1px solid #1e293b;border-radius:var(--radius-md);padding:14px;\">\n          <div style=\"font-size:0.7rem;font-weight:700;color:#0284c7;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:2px;\">Title</div>\n          <strong id=\"modalProblemTitle\" style=\"color:#fff;font-size:0.95rem;display:block;margin-bottom:10px;\">—</strong>\n          \n          <div style=\"background:rgba(56,189,248,0.06);border:1px solid rgba(56,189,248,0.25);border-radius:6px;padding:10px 12px;margin-bottom:10px;\">\n            <div style=\"font-size:0.7rem;font-weight:700;color:#38bdf8;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;\">📌 Problem Statement</div>\n            <p id=\"modalProblemText\" style=\"color:#e2e8f0;font-size:0.84rem;line-height:1.55;margin:0;\">—</p>\n          </div>\n\n          <div style=\"background:rgba(52,211,153,0.06);border:1px solid rgba(52,211,153,0.25);border-radius:6px;padding:10px 12px;margin-bottom:10px;\">\n            <div style=\"font-size:0.7rem;font-weight:700;color:#34d399;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;\">💡 Expected Solution &amp; Deliverables</div>\n            <p id=\"modalSolutionText\" style=\"color:#e2e8f0;font-size:0.84rem;line-height:1.55;margin:0;\">—</p>\n          </div>\n\n          <p id=\"modalProblemDesc\" class=\"hidden\" style=\"display:none;\">—</p>\n          <div style=\"display:flex;gap:8px;align-items:center;\">\n            <span id=\"modalProblemDiff\" class=\"difficulty-tag\" style=\"font-size:0.7rem;padding:2px 8px;\">Intermediate</span>\n            <span id=\"modalProblemDomain\" class=\"domain-tag\" style=\"font-size:0.7rem;padding:2px 8px;\">Domain</span>\n          </div>\n        </div>\n      </div>\n\n      <div style=\"display:flex;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid var(--border-color);padding-top:14px;\">\n        <button id=\"modalResetSpinBtn\" class=\"btn btn-secondary btn-sm\" style=\"color:#f43f5e;border-color:rgba(244,63,94,0.3);\">\n          🔄 Reset Spin (Allow Re-Spin)\n        </button>\n        <div style=\"display:flex;gap:8px;\">\n          <button id=\"modalDownloadPdfBtn\" class=\"btn btn-accent btn-sm\">📄 Download PDF</button>\n          <button id=\"modalDismissBtn\" class=\"btn btn-outline btn-sm\">Close</button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Toast Notifications -->\n  <div id=\"toastContainer\" class=\"toast-container\"></div>\n\n  <script src=\"admin-app.js?v=20261005_6\"></script>\n</body>\n</html>\n",
  "style.css": ":root {\n  --bg-primary: #0a0d14;\n  --bg-surface: #121826;\n  --bg-card: #182234;\n  --bg-card-hover: #1f2c42;\n  --border-color: rgba(255, 255, 255, 0.08);\n  --border-hover: rgba(255, 255, 255, 0.16);\n\n  --accent-cyan: #06b6d4;\n  --accent-blue: #3b82f6;\n  --accent-indigo: #6366f1;\n  --accent-purple: #8b5cf6;\n  --accent-emerald: #10b981;\n  --accent-amber: #f59e0b;\n  --accent-rose: #f43f5e;\n\n  --text-main: #f1f5f9;\n  --text-muted: #94a3b8;\n  --text-dim: #64748b;\n\n  --glow-cyan: rgba(6, 182, 212, 0.35);\n  --glow-purple: rgba(139, 92, 246, 0.35);\n  --shadow-card: 0 10px 30px -5px rgba(0, 0, 0, 0.45);\n  \n  --radius-sm: 8px;\n  --radius-md: 12px;\n  --radius-lg: 18px;\n  --radius-full: 9999px;\n  --font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;\n  --font-mono: 'JetBrains Mono', monospace;\n}\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  font-family: var(--font-family);\n  background-color: var(--bg-primary);\n  color: var(--text-main);\n  min-height: 100vh;\n  overflow-x: hidden;\n  background-image: \n    radial-gradient(circle at 50% 0%, rgba(99, 102, 241, 0.12) 0%, transparent 60%),\n    radial-gradient(circle at 10% 80%, rgba(6, 182, 212, 0.08) 0%, transparent 40%),\n    radial-gradient(circle at 90% 80%, rgba(244, 63, 94, 0.06) 0%, transparent 40%);\n}\n\n/* Scrollbars */\n::-webkit-scrollbar {\n  width: 6px;\n  height: 6px;\n}\n::-webkit-scrollbar-track {\n  background: var(--bg-surface);\n}\n::-webkit-scrollbar-thumb {\n  background: #2a374f;\n  border-radius: var(--radius-full);\n}\n::-webkit-scrollbar-thumb:hover {\n  background: #3c4f70;\n}\n\n.app-container {\n  display: flex;\n  flex-direction: column;\n  min-height: 100vh;\n}\n\n/* NAVBAR */\n.navbar {\n  height: 72px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 32px;\n  background: rgba(18, 24, 38, 0.75);\n  backdrop-filter: blur(14px);\n  border-bottom: 1px solid var(--border-color);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n}\n\n.nav-brand {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.logo-icon {\n  font-size: 28px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 44px;\n  height: 44px;\n  background: linear-gradient(135deg, rgba(6, 182, 212, 0.2), rgba(139, 92, 246, 0.2));\n  border: 1px solid rgba(255, 255, 255, 0.15);\n  border-radius: var(--radius-md);\n  box-shadow: 0 0 15px var(--glow-cyan);\n}\n\n.brand-text h1 {\n  font-size: 1.25rem;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n}\n\n.brand-accent {\n  background: linear-gradient(90deg, var(--accent-cyan), var(--accent-purple));\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n\n.tagline {\n  font-size: 0.75rem;\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n.nav-center {\n  display: flex;\n  align-items: center;\n}\n\n.active-domain-pill {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  background: var(--bg-card);\n  border: 1px solid var(--border-hover);\n  padding: 6px 16px;\n  border-radius: var(--radius-full);\n  font-size: 0.85rem;\n}\n\n.pill-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--accent-emerald);\n  box-shadow: 0 0 8px var(--accent-emerald);\n  animation: pulse-dot 2s infinite ease-in-out;\n}\n\n@keyframes pulse-dot {\n  0%, 100% { opacity: 1; transform: scale(1); }\n  50% { opacity: 0.4; transform: scale(0.85); }\n}\n\n.pill-label {\n  color: var(--text-dim);\n  font-size: 0.8rem;\n}\n\n.nav-actions {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n/* BUTTONS */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  font-family: inherit;\n  font-weight: 600;\n  border-radius: var(--radius-md);\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n  border: none;\n  text-decoration: none;\n}\n\n.btn-sm {\n  padding: 8px 14px;\n  font-size: 0.82rem;\n}\n\n.btn-md {\n  padding: 10px 18px;\n  font-size: 0.9rem;\n}\n\n.btn-lg {\n  padding: 12px 24px;\n  font-size: 1rem;\n}\n\n.btn-xl {\n  padding: 16px 36px;\n  font-size: 1.15rem;\n  font-weight: 800;\n  letter-spacing: 0.03em;\n}\n\n.btn-primary {\n  background: linear-gradient(135deg, #06b6d4, #3b82f6);\n  color: #ffffff;\n  box-shadow: 0 4px 20px rgba(6, 182, 212, 0.35);\n}\n\n.btn-primary:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 6px 25px rgba(6, 182, 212, 0.55);\n}\n\n.btn-accent {\n  background: linear-gradient(135deg, #8b5cf6, #ec4899);\n  color: #ffffff;\n  box-shadow: 0 4px 18px rgba(139, 92, 246, 0.35);\n}\n\n.btn-accent:hover {\n  transform: translateY(-1px);\n  box-shadow: 0 6px 22px rgba(139, 92, 246, 0.5);\n}\n\n.btn-secondary {\n  background: var(--bg-card);\n  color: var(--text-main);\n  border: 1px solid var(--border-color);\n}\n\n.btn-secondary:hover {\n  background: var(--bg-card-hover);\n  border-color: var(--border-hover);\n}\n\n.btn-outline {\n  background: transparent;\n  color: var(--accent-cyan);\n  border: 1px solid rgba(6, 182, 212, 0.3);\n}\n\n.btn-outline:hover {\n  background: rgba(6, 182, 212, 0.1);\n  border-color: var(--accent-cyan);\n}\n\n.logout-btn:hover {\n  background: rgba(244, 63, 94, 0.1) !important;\n  color: #f43f5e !important;\n  border-color: rgba(244, 63, 94, 0.45) !important;\n}\n\n.btn-full {\n  width: 100%;\n}\n\n.btn-text-danger {\n  background: none;\n  border: none;\n  color: var(--accent-rose);\n  font-size: 0.78rem;\n  font-weight: 600;\n  cursor: pointer;\n}\n.btn-text-danger:hover {\n  text-decoration: underline;\n}\n\n.btn-text-subtle {\n  background: none;\n  border: none;\n  color: var(--text-dim);\n  font-size: 0.78rem;\n  cursor: pointer;\n  margin-top: 8px;\n}\n.btn-text-subtle:hover {\n  color: var(--text-muted);\n}\n\n/* MAIN LAYOUT */\n.main-layout {\n  flex: 1;\n  display: grid;\n  grid-template-columns: 310px 1fr 340px;\n  gap: 24px;\n  padding: 24px 32px;\n  max-width: 1720px;\n  margin: 0 auto;\n  width: 100%;\n}\n\n/* SIDEBAR PANELS */\n.sidebar {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.panel-card {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 20px;\n  box-shadow: var(--shadow-card);\n  display: flex;\n  flex-direction: column;\n}\n\n.panel-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 16px;\n}\n\n.panel-title-group {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.panel-icon {\n  font-size: 1.35rem;\n}\n\n.panel-title-group h2,\n.panel-title-group h3 {\n  font-size: 1.05rem;\n  font-weight: 700;\n  color: var(--text-main);\n}\n\n.panel-sub {\n  font-size: 0.75rem;\n  color: var(--text-muted);\n}\n\n/* DOMAIN LIST */\n.domains-scroll {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  max-height: 410px;\n  overflow-y: auto;\n  padding-right: 4px;\n  margin-bottom: 16px;\n}\n\n.domain-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 12px 14px;\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.domain-item:hover {\n  background: var(--bg-card-hover);\n  border-color: rgba(255, 255, 255, 0.2);\n  transform: translateX(4px);\n}\n\n.domain-item.active {\n  background: linear-gradient(135deg, rgba(6, 182, 212, 0.18), rgba(99, 102, 241, 0.2));\n  border-color: var(--accent-cyan);\n  box-shadow: 0 0 16px rgba(6, 182, 212, 0.2);\n}\n\n.domain-item-left {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.domain-icon {\n  font-size: 1.25rem;\n}\n\n.domain-name {\n  font-size: 0.88rem;\n  font-weight: 600;\n  color: var(--text-main);\n}\n\n.domain-item-right {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.domain-delete-btn {\n  background: rgba(244, 63, 94, 0.15);\n  border: 1px solid rgba(244, 63, 94, 0.3);\n  color: #fb7185;\n  width: 24px;\n  height: 24px;\n  border-radius: var(--radius-sm);\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  font-size: 0.75rem;\n  transition: all 0.2s ease;\n  line-height: 1;\n}\n\n.domain-delete-btn:hover {\n  background: var(--accent-rose);\n  color: #ffffff;\n  transform: scale(1.1);\n}\n\n.new-domain-box {\n  background: rgba(14, 20, 32, 0.95);\n  border: 1px solid var(--accent-cyan);\n  border-radius: var(--radius-md);\n  padding: 12px;\n  margin-bottom: 14px;\n  box-shadow: 0 4px 15px rgba(6, 182, 212, 0.2);\n}\n\n.new-domain-actions {\n  display: flex;\n  gap: 8px;\n  justify-content: flex-end;\n}\n\n.form-input-sm {\n  padding: 6px 10px;\n  font-size: 0.82rem;\n}\n\n.mb-2 { margin-bottom: 8px; }\n.mb-3 { margin-bottom: 12px; }\n.mt-3 { margin-top: 12px; }\n\n/* CYCLE CARD */\n.cycle-card {\n  background: rgba(14, 20, 32, 0.8);\n  border: 1px dashed rgba(255, 255, 255, 0.15);\n  border-radius: var(--radius-md);\n  padding: 14px;\n  margin-top: auto;\n}\n\n.cycle-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 6px;\n}\n\n.cycle-title {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 0.88rem;\n}\n\n.cycle-icon {\n  color: var(--accent-emerald);\n}\n\n.cycle-desc {\n  font-size: 0.75rem;\n  color: var(--text-muted);\n  line-height: 1.4;\n  margin-bottom: 12px;\n}\n\n.progress-bar-bg {\n  width: 100%;\n  height: 8px;\n  background: rgba(255, 255, 255, 0.08);\n  border-radius: var(--radius-full);\n  overflow: hidden;\n  margin-bottom: 8px;\n}\n\n.progress-bar-fill {\n  height: 100%;\n  background: linear-gradient(90deg, var(--accent-emerald), var(--accent-cyan));\n  border-radius: var(--radius-full);\n  transition: width 0.4s ease-out;\n}\n\n.cycle-metrics {\n  display: flex;\n  justify-content: space-between;\n  font-size: 0.75rem;\n  font-family: var(--font-mono);\n  color: var(--text-muted);\n}\n\n/* CENTER STAGE (WHEEL) */\n.center-stage {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  position: relative;\n  min-height: 560px;\n}\n\n.wheel-wrapper {\n  position: relative;\n  width: 520px;\n  height: 520px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  filter: drop-shadow(0 0 35px rgba(6, 182, 212, 0.22));\n}\n\n.wheel-pointer {\n  position: absolute;\n  top: -16px;\n  left: 50%;\n  transform: translateX(-50%);\n  z-index: 30;\n  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.6));\n  transition: transform 0.06s ease;\n}\n\n.wheel-pointer.tick {\n  transform: translateX(-50%) rotate(-12deg) scale(1.15);\n}\n\n.pointer-arrow {\n  width: 0;\n  height: 0;\n  border-left: 18px solid transparent;\n  border-right: 18px solid transparent;\n  border-top: 36px solid #f43f5e;\n  position: relative;\n}\n\n.pointer-arrow::after {\n  content: '';\n  position: absolute;\n  top: -36px;\n  left: -9px;\n  width: 0;\n  height: 0;\n  border-left: 9px solid transparent;\n  border-right: 9px solid transparent;\n  border-top: 20px solid #ffffff;\n}\n\n.canvas-container {\n  position: relative;\n  width: 520px;\n  height: 520px;\n  border-radius: 50%;\n  box-shadow: \n    0 0 0 10px #1e293b,\n    0 0 0 14px rgba(255, 255, 255, 0.1),\n    0 0 50px rgba(6, 182, 212, 0.25);\n}\n\n#wheelCanvas {\n  display: block;\n  width: 100%;\n  height: 100%;\n  border-radius: 50%;\n  background: #0f172a;\n}\n\n/* Wheel Center Button Hub */\n.wheel-center-overlay {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  width: 110px;\n  height: 110px;\n  border-radius: 50%;\n  background: radial-gradient(circle, #25334c 0%, #0d1523 100%);\n  border: 4px solid #38bdf8;\n  box-shadow: \n    0 0 20px rgba(56, 189, 248, 0.6),\n    inset 0 0 15px rgba(0, 0, 0, 0.7);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  user-select: none;\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n  z-index: 25;\n}\n\n.wheel-center-overlay:hover {\n  transform: translate(-50%, -50%) scale(1.08);\n  border-color: #f43f5e;\n  box-shadow: 0 0 30px rgba(244, 63, 94, 0.7);\n}\n\n.wheel-center-overlay:active {\n  transform: translate(-50%, -50%) scale(0.95);\n}\n\n.inner-hub {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n}\n\n.hub-spin-text {\n  font-size: 1.15rem;\n  font-weight: 900;\n  letter-spacing: 0.05em;\n  color: #ffffff;\n  text-shadow: 0 2px 4px rgba(0,0,0,0.8);\n}\n\n.hub-sub-text {\n  font-size: 0.52rem;\n  font-weight: 700;\n  color: #94a3b8;\n  letter-spacing: 0.02em;\n}\n\n/* SPIN CONTROLS */\n.spin-controls {\n  margin-top: 28px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 12px;\n}\n\n.spin-info-pill {\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid var(--border-color);\n  padding: 6px 18px;\n  border-radius: var(--radius-full);\n  font-size: 0.85rem;\n  color: var(--text-muted);\n}\n\n.spin-info-pill strong {\n  color: var(--accent-cyan);\n}\n\n.keyboard-hint {\n  font-size: 0.75rem;\n  color: var(--text-dim);\n}\n\nkbd {\n  background: #1e293b;\n  border: 1px solid rgba(255, 255, 255, 0.2);\n  border-radius: 4px;\n  padding: 2px 6px;\n  font-family: var(--font-mono);\n  font-size: 0.72rem;\n  color: var(--text-main);\n}\n\n/* RIGHT SIDEBAR (UPLOAD & ADMIN) */\n.admin-lock-badge {\n  font-size: 0.72rem;\n  font-weight: 700;\n  padding: 4px 10px;\n  border-radius: var(--radius-full);\n  background: rgba(244, 63, 94, 0.15);\n  color: #fb7185;\n  border: 1px solid rgba(244, 63, 94, 0.3);\n}\n\n.admin-lock-badge.unlocked {\n  background: rgba(16, 185, 129, 0.15);\n  color: #34d399;\n  border-color: rgba(16, 185, 129, 0.3);\n}\n\n.locked-placeholder {\n  text-align: center;\n  padding: 24px 12px;\n  background: rgba(10, 14, 23, 0.6);\n  border: 1px dashed var(--border-color);\n  border-radius: var(--radius-md);\n}\n\n.lock-big-icon {\n  font-size: 2.5rem;\n  display: inline-block;\n  margin-bottom: 8px;\n}\n\n.locked-placeholder h3 {\n  font-size: 1rem;\n  margin-bottom: 8px;\n}\n\n.locked-placeholder p {\n  font-size: 0.78rem;\n  color: var(--text-muted);\n  line-height: 1.5;\n  margin-bottom: 18px;\n}\n\n/* FILE DROP ZONE */\n.drop-zone {\n  position: relative;\n  border: 2px dashed rgba(255, 255, 255, 0.2);\n  border-radius: var(--radius-md);\n  padding: 24px 16px;\n  text-align: center;\n  cursor: pointer;\n  background: rgba(10, 14, 23, 0.5);\n  transition: all 0.2s ease;\n  margin-bottom: 16px;\n}\n\n.drop-zone:hover,\n.drop-zone.dragover {\n  border-color: var(--accent-purple);\n  background: rgba(139, 92, 246, 0.08);\n}\n\n.file-input-hidden {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  opacity: 0;\n  cursor: pointer;\n}\n\n.drop-icon {\n  font-size: 2rem;\n  margin-bottom: 6px;\n}\n\n.drop-primary-text {\n  font-size: 0.88rem;\n  font-weight: 600;\n  color: var(--text-main);\n}\n\n.drop-secondary-text {\n  font-size: 0.75rem;\n  color: var(--text-muted);\n  margin-bottom: 12px;\n}\n\n.browse-link {\n  color: var(--accent-cyan);\n  text-decoration: underline;\n}\n\n.supported-formats-pills {\n  display: flex;\n  justify-content: center;\n  gap: 4px;\n}\n\n.format-pill {\n  font-size: 0.65rem;\n  font-family: var(--font-mono);\n  background: rgba(255, 255, 255, 0.06);\n  padding: 2px 6px;\n  border-radius: 4px;\n  color: var(--text-dim);\n}\n\n.selected-file-card {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  background: rgba(14, 23, 42, 0.95);\n  border: 1px solid rgba(6, 182, 212, 0.5);\n  padding: 14px 16px;\n  border-radius: var(--radius-md);\n  margin-top: 10px;\n  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.35);\n  animation: fileSlideIn 0.25s ease-out;\n}\n\n@keyframes fileSlideIn {\n  from { opacity: 0; transform: translateY(-8px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n.selected-file-info-left {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  overflow: hidden;\n}\n\n.file-card-icon {\n  font-size: 1.6rem;\n}\n\n.selected-file-texts {\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.selected-file-texts strong {\n  font-size: 0.85rem;\n  color: #38bdf8;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  max-width: 170px;\n}\n\n.file-size-sub {\n  font-size: 0.72rem;\n  color: var(--text-dim);\n  font-family: var(--font-mono);\n}\n\n.btn-cancel-file {\n  background: rgba(244, 63, 94, 0.15);\n  border: 1px solid rgba(244, 63, 94, 0.4);\n  color: #fb7185;\n  padding: 6px 12px;\n  border-radius: var(--radius-sm);\n  font-size: 0.8rem;\n  font-weight: 700;\n  cursor: pointer;\n  transition: all 0.2s ease;\n  white-space: nowrap;\n}\n\n.btn-cancel-file:hover {\n  background: #f43f5e;\n  color: #ffffff;\n  box-shadow: 0 0 10px rgba(244, 63, 94, 0.4);\n}\n\n.btn-danger-subtle {\n  background: rgba(244, 63, 94, 0.12);\n  border: 1px solid rgba(244, 63, 94, 0.35);\n  color: #fda4af;\n  padding: 8px 14px;\n  border-radius: var(--radius-md);\n  font-size: 0.85rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.btn-danger-subtle:hover {\n  background: #f43f5e;\n  color: #ffffff;\n}\n\n/* FORM ELEMENTS */\n.form-group {\n  margin-bottom: 14px;\n}\n\n.form-label {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 0.82rem;\n  font-weight: 600;\n  margin-bottom: 6px;\n  color: var(--text-main);\n}\n\n.label-hint {\n  font-size: 0.72rem;\n  color: var(--text-dim);\n  font-weight: normal;\n}\n\n.form-input,\n.form-select,\n.form-textarea {\n  width: 100%;\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  padding: 10px 14px;\n  color: var(--text-main);\n  font-family: inherit;\n  font-size: 0.88rem;\n  transition: all 0.2s ease;\n}\n\n.form-input:focus,\n.form-select:focus,\n.form-textarea:focus {\n  outline: none;\n  border-color: var(--accent-cyan);\n  box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.2);\n}\n\n.form-error {\n  background: rgba(244, 63, 94, 0.15);\n  border: 1px solid rgba(244, 63, 94, 0.3);\n  color: #fda4af;\n  padding: 8px 12px;\n  border-radius: var(--radius-sm);\n  font-size: 0.8rem;\n  margin-bottom: 12px;\n}\n\n.admin-quick-links {\n  margin-top: 16px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n}\n\n/* HISTORY LIST */\n.history-list {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  max-height: 220px;\n  overflow-y: auto;\n}\n\n.history-item {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  padding: 10px 12px;\n  border-radius: var(--radius-sm);\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.history-item:hover {\n  border-color: var(--accent-cyan);\n  background: var(--bg-card-hover);\n}\n\n.history-item-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 0.75rem;\n  margin-bottom: 4px;\n}\n\n.history-domain {\n  font-weight: 600;\n  color: var(--accent-cyan);\n}\n\n.history-time {\n  color: var(--text-dim);\n}\n\n.history-title {\n  font-size: 0.82rem;\n  color: var(--text-main);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.empty-state {\n  font-size: 0.78rem;\n  color: var(--text-dim);\n  text-align: center;\n  padding: 16px;\n}\n\n/* MODALS */\n.modal-overlay {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100vw;\n  height: 100vh;\n  background: rgba(4, 7, 13, 0.85);\n  backdrop-filter: blur(8px);\n  z-index: 1000;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n}\n\n.modal-card {\n  background: #141c2c;\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: var(--radius-lg);\n  padding: 32px;\n  position: relative;\n  box-shadow: 0 25px 60px -15px rgba(0, 0, 0, 0.7);\n  animation: modalPop 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n  max-height: 90vh;\n  overflow-y: auto;\n}\n\n@keyframes modalPop {\n  0% { transform: scale(0.92); opacity: 0; }\n  100% { transform: scale(1); opacity: 1; }\n}\n\n.modal-close {\n  position: absolute;\n  top: 20px;\n  right: 20px;\n  background: rgba(255, 255, 255, 0.08);\n  border: none;\n  color: var(--text-muted);\n  width: 34px;\n  height: 34px;\n  border-radius: 50%;\n  font-size: 1.2rem;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: all 0.2s;\n}\n\n.modal-close:hover {\n  background: rgba(255, 255, 255, 0.16);\n  color: #ffffff;\n}\n\n/* PROBLEM RESULT MODAL */\n.problem-card-modal {\n  width: 100%;\n  max-width: 680px;\n  border-top: 4px solid var(--accent-cyan);\n}\n\n.cycle-banner {\n  background: linear-gradient(135deg, rgba(16, 185, 129, 0.2), rgba(6, 182, 212, 0.2));\n  border: 1px solid var(--accent-emerald);\n  padding: 10px 14px;\n  border-radius: var(--radius-sm);\n  font-size: 0.84rem;\n  color: #6ee7b7;\n  margin-bottom: 16px;\n}\n\n.modal-badge-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-bottom: 16px;\n}\n\n.domain-tag {\n  background: rgba(6, 182, 212, 0.2);\n  color: #67e8f9;\n  border: 1px solid rgba(6, 182, 212, 0.4);\n  font-size: 0.78rem;\n  font-weight: 700;\n  padding: 4px 12px;\n  border-radius: var(--radius-full);\n}\n\n.difficulty-tag {\n  background: rgba(245, 158, 11, 0.2);\n  color: #fcd34d;\n  border: 1px solid rgba(245, 158, 11, 0.4);\n  font-size: 0.78rem;\n  font-weight: 700;\n  padding: 4px 12px;\n  border-radius: var(--radius-full);\n}\n\n.source-tag {\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--text-dim);\n  font-size: 0.75rem;\n  padding: 4px 10px;\n  border-radius: var(--radius-full);\n}\n\n.problem-title {\n  font-size: 1.45rem;\n  font-weight: 800;\n  line-height: 1.35;\n  margin-bottom: 16px;\n  color: #ffffff;\n}\n\n.problem-body {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  padding: 20px;\n  margin-bottom: 16px;\n}\n\n.section-label {\n  font-size: 0.72rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--accent-cyan);\n  display: block;\n  margin-bottom: 8px;\n}\n\n.problem-description {\n  font-size: 1rem;\n  line-height: 1.65;\n  color: #e2e8f0;\n}\n\n/* STRUCTURED PROBLEM DETAILS (Title | Problem | Expected Solution) */\n.problem-structure-wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n  margin-bottom: 16px;\n}\n\n.problem-detail-box {\n  border-radius: var(--radius-md);\n  padding: 18px 20px;\n  transition: all var(--transition-fast);\n}\n\n.problem-detail-box.box-problem {\n  border: 1px solid rgba(56, 189, 248, 0.35);\n  background: linear-gradient(135deg, rgba(56, 189, 248, 0.08), rgba(15, 23, 42, 0.7));\n  box-shadow: inset 0 0 20px rgba(56, 189, 248, 0.05);\n}\n\n.problem-detail-box.box-solution {\n  border: 1px solid rgba(52, 211, 153, 0.35);\n  background: linear-gradient(135deg, rgba(52, 211, 153, 0.08), rgba(15, 23, 42, 0.7));\n  box-shadow: inset 0 0 20px rgba(52, 211, 153, 0.05);\n}\n\n.detail-box-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n\n.box-problem .detail-title {\n  font-size: 0.76rem;\n  font-weight: 800;\n  letter-spacing: 0.06em;\n  color: #38bdf8;\n  text-transform: uppercase;\n}\n\n.box-solution .detail-title {\n  font-size: 0.76rem;\n  font-weight: 800;\n  letter-spacing: 0.06em;\n  color: #34d399;\n  text-transform: uppercase;\n}\n\n.detail-box-content {\n  font-size: 0.94rem;\n  line-height: 1.65;\n  color: #e2e8f0;\n  white-space: pre-line;\n}\n\n.tags-container {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-bottom: 18px;\n}\n\n.tag-badge {\n  font-size: 0.72rem;\n  background: rgba(255, 255, 255, 0.06);\n  padding: 3px 8px;\n  border-radius: 4px;\n  color: var(--text-muted);\n}\n\n.modal-cycle-indicator {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 0.8rem;\n  color: var(--text-dim);\n  margin-bottom: 24px;\n}\n\n.modal-footer-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 12px;\n}\n\n/* AUTH MODAL */\n.auth-modal {\n  width: 100%;\n  max-width: 440px;\n}\n\n.auth-header {\n  text-align: center;\n  margin-bottom: 24px;\n}\n\n.auth-icon-circle {\n  font-size: 2.2rem;\n  width: 64px;\n  height: 64px;\n  background: rgba(139, 92, 246, 0.15);\n  border: 1px solid rgba(139, 92, 246, 0.3);\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin: 0 auto 12px auto;\n}\n\n.password-input-wrap {\n  position: relative;\n  display: flex;\n  align-items: center;\n  width: 100%;\n}\n\n.password-input-wrap .form-input {\n  padding-right: 44px;\n}\n\n.btn-toggle-eye {\n  position: absolute;\n  right: 8px;\n  top: 50%;\n  transform: translateY(-50%);\n  background: none;\n  border: none;\n  cursor: pointer;\n  font-size: 1.15rem;\n  padding: 4px 8px;\n  border-radius: var(--radius-sm);\n  opacity: 0.65;\n  transition: opacity 0.2s ease;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.btn-toggle-eye:hover {\n  opacity: 1;\n}\n\n/* MANAGER MODAL (EXPLORER & DELETE) */\n.manager-modal {\n  width: 100%;\n  max-width: 980px;\n}\n\n.manager-modal-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  margin-bottom: 20px;\n}\n\n.tabs-nav {\n  display: flex;\n  gap: 8px;\n  border-bottom: 1px solid var(--border-color);\n  margin-bottom: 20px;\n}\n\n.tab-btn {\n  background: none;\n  border: none;\n  padding: 10px 16px;\n  color: var(--text-muted);\n  font-size: 0.88rem;\n  font-weight: 600;\n  cursor: pointer;\n  border-bottom: 2px solid transparent;\n  transition: all 0.2s;\n}\n\n.tab-btn:hover {\n  color: var(--text-main);\n}\n\n.tab-btn.active {\n  color: var(--accent-cyan);\n  border-bottom-color: var(--accent-cyan);\n}\n\n.filter-bar {\n  display: flex;\n  gap: 12px;\n  margin-bottom: 16px;\n}\n\n.table-container {\n  max-height: 420px;\n  overflow-y: auto;\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n}\n\n.data-table {\n  width: 100%;\n  border-collapse: collapse;\n  text-align: left;\n  font-size: 0.82rem;\n}\n\n.data-table th {\n  background: #192334;\n  padding: 12px 14px;\n  font-weight: 700;\n  color: var(--text-muted);\n  border-bottom: 1px solid var(--border-color);\n  position: sticky;\n  top: 0;\n  z-index: 10;\n}\n\n.data-table td {\n  padding: 12px 14px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.05);\n  color: var(--text-main);\n  vertical-align: middle;\n}\n\n.data-table tr:hover td {\n  background: rgba(255, 255, 255, 0.02);\n}\n\n.table-del-btn {\n  background: rgba(244, 63, 94, 0.15);\n  border: 1px solid rgba(244, 63, 94, 0.3);\n  color: #fb7185;\n  padding: 4px 10px;\n  border-radius: var(--radius-sm);\n  cursor: pointer;\n  font-size: 0.75rem;\n  font-weight: 600;\n  transition: all 0.2s;\n}\n\n.table-del-btn:hover {\n  background: var(--accent-rose);\n  color: #ffffff;\n}\n\n.form-row {\n  display: flex;\n  gap: 16px;\n}\n\n.flex-1 {\n  flex: 1;\n}\n\n/* TOASTS */\n.toast-container {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  z-index: 2000;\n}\n\n.toast {\n  background: var(--bg-card);\n  border: 1px solid var(--border-hover);\n  padding: 12px 18px;\n  border-radius: var(--radius-md);\n  box-shadow: 0 10px 25px rgba(0,0,0,0.5);\n  font-size: 0.88rem;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  animation: toastSlide 0.3s ease-out;\n}\n\n@keyframes toastSlide {\n  from { transform: translateX(100%); opacity: 0; }\n  to { transform: translateX(0); opacity: 1; }\n}\n\n.toast-success {\n  border-left: 4px solid var(--accent-emerald);\n}\n\n.toast-error {\n  border-left: 4px solid var(--accent-rose);\n}\n\n.toast-info {\n  border-left: 4px solid var(--accent-cyan);\n}\n\n/* UTILITY */\n.hidden {\n  display: none !important;\n}\n\n/* ═══════════════════════════════════════════════════════════ */\n/* COMPREHENSIVE RESPONSIVE DESIGN (PC, TABLET & MOBILE)       */\n/* ═══════════════════════════════════════════════════════════ */\n\n/* Base touch & mobile overflow safeguards */\nhtml, body {\n  max-width: 100vw;\n  overflow-x: hidden;\n  -webkit-text-size-adjust: 100%;\n}\n\n/* Touch device adjustments */\n@media (hover: none) and (pointer: coarse) {\n  .keyboard-hint {\n    display: none !important;\n  }\n}\n\n/* TABLET & SMALL LAPTOP (max-width: 1280px) */\n@media (max-width: 1280px) {\n  .main-layout {\n    grid-template-columns: 270px 1fr 290px;\n    gap: 16px;\n    padding: 16px 20px;\n  }\n  .wheel-wrapper, .canvas-container {\n    width: 440px;\n    height: 440px;\n  }\n}\n\n/* TABLET & COMPACT SCREENS (max-width: 1080px) */\n@media (max-width: 1080px) {\n  .main-layout {\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n    padding: 16px;\n  }\n  .center-stage {\n    grid-column: 1 / -1;\n    order: 1;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    width: 100%;\n  }\n  .sidebar-left {\n    order: 2;\n  }\n  .sidebar-right {\n    order: 3;\n  }\n}\n\n/* TABLET & MOBILE VIEWPORT (max-width: 860px) */\n@media (max-width: 860px) {\n  .navbar {\n    height: auto;\n    min-height: 58px;\n    padding: 10px 14px;\n    flex-wrap: wrap;\n    gap: 10px;\n    justify-content: space-between;\n  }\n\n  .nav-brand {\n    gap: 10px;\n  }\n\n  .logo-icon {\n    width: 38px;\n    height: 38px;\n    font-size: 22px;\n  }\n\n  .brand-text h1 {\n    font-size: 1.1rem;\n  }\n\n  .tagline {\n    display: none;\n  }\n\n  .nav-center {\n    display: none;\n  }\n\n  .nav-actions {\n    gap: 6px;\n    flex-wrap: wrap;\n    justify-content: flex-end;\n  }\n\n  .team-nav-pill {\n    padding: 5px 10px;\n    font-size: 0.75rem;\n  }\n\n  .nav-actions .btn-sm,\n  .nav-actions .admin-nav-link {\n    padding: 6px 10px;\n    font-size: 0.75rem;\n  }\n\n  .main-layout {\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n    padding: 12px 10px;\n    width: 100%;\n  }\n\n  .center-stage {\n    order: 1;\n    width: 100%;\n    min-height: auto;\n  }\n\n  .sidebar-left {\n    order: 2;\n    width: 100%;\n  }\n\n  .sidebar-right {\n    order: 3;\n    width: 100%;\n  }\n\n  .wheel-wrapper, .canvas-container {\n    width: 380px;\n    height: 380px;\n    max-width: 90vw;\n    max-height: 90vw;\n  }\n\n  .wheel-center-overlay {\n    width: 92px;\n    height: 92px;\n  }\n\n  .hub-spin-text {\n    font-size: 1rem;\n  }\n\n  .hub-sub-text {\n    font-size: 0.46rem;\n  }\n\n  .spin-controls {\n    margin-top: 18px;\n    width: 100%;\n  }\n\n  .spin-info-pill {\n    font-size: 0.8rem;\n    padding: 6px 14px;\n    max-width: 95%;\n    text-align: center;\n  }\n\n  .action-btn-row {\n    width: 100%;\n    display: flex;\n    justify-content: center;\n  }\n\n  #spinMainBtn {\n    width: 100%;\n    max-width: 340px;\n    padding: 14px 20px;\n    font-size: 1.05rem;\n  }\n}\n\n/* SMARTPHONE SCREENS (max-width: 600px) */\n@media (max-width: 600px) {\n  /* Prevent iOS input auto-zoom */\n  input, select, textarea {\n    font-size: 16px !important;\n  }\n\n  /* Entry Gate Mobile */\n  .entry-gate-overlay {\n    padding: 12px;\n    align-items: center;\n    overflow-y: auto;\n  }\n\n  .entry-gate-card {\n    padding: 24px 18px 20px;\n    margin: 10px auto;\n    width: 100%;\n    max-width: 100%;\n    border-radius: var(--radius-md);\n  }\n\n  .entry-top-admin-badge {\n    top: 12px;\n    right: 12px;\n    padding: 5px 10px;\n    font-size: 0.72rem;\n  }\n\n  .entry-logo-icon {\n    font-size: 32px;\n    margin-bottom: 6px;\n  }\n\n  .entry-title {\n    font-size: 1.45rem;\n  }\n\n  .entry-subtitle {\n    font-size: 0.78rem;\n  }\n\n  .entry-divider {\n    margin: 14px 0 12px;\n  }\n\n  .entry-form-heading {\n    font-size: 0.88rem;\n    margin-bottom: 12px;\n  }\n\n  .entry-form .form-group {\n    margin-bottom: 12px;\n  }\n\n  .form-label {\n    font-size: 0.78rem;\n    margin-bottom: 5px;\n  }\n\n  .form-input {\n    padding: 10px 12px;\n    min-height: 44px;\n  }\n\n  .entry-submit-btn {\n    min-height: 46px;\n    font-size: 0.95rem;\n  }\n\n  .entry-admin-btn {\n    padding: 10px 14px;\n    font-size: 0.82rem;\n  }\n\n  /* Wheel Mobile Scaling */\n  .wheel-wrapper, .canvas-container {\n    width: min(320px, 88vw);\n    height: min(320px, 88vw);\n  }\n\n  .wheel-center-overlay {\n    width: 80px;\n    height: 80px;\n    border-width: 3px;\n  }\n\n  .hub-spin-text {\n    font-size: 0.88rem;\n  }\n\n  .hub-sub-text {\n    font-size: 0.42rem;\n  }\n\n  .pointer-arrow {\n    border-left-width: 14px;\n    border-right-width: 14px;\n    border-top-width: 28px;\n  }\n\n  .pointer-arrow::after {\n    top: -28px;\n    left: -7px;\n    border-left-width: 7px;\n    border-right-width: 7px;\n    border-top-width: 16px;\n  }\n\n  .wheel-pointer {\n    top: -12px;\n  }\n\n  .keyboard-hint {\n    display: none !important;\n  }\n\n  /* Assigned Problem Card Mobile */\n  .assigned-problem-card {\n    padding: 18px 14px;\n    margin-top: 16px;\n    border-radius: var(--radius-md);\n    width: 100%;\n  }\n\n  .assigned-card-title {\n    font-size: 1.1rem;\n    margin-bottom: 6px;\n  }\n\n  .assigned-card-desc {\n    font-size: 0.82rem;\n    -webkit-line-clamp: 4;\n    margin-bottom: 14px;\n  }\n\n  .assigned-card-actions {\n    flex-direction: column;\n    width: 100%;\n    gap: 8px;\n  }\n\n  .assigned-card-actions .btn {\n    width: 100%;\n    justify-content: center;\n    text-align: center;\n  }\n\n  /* Domain & History Panels */\n  .panel-card {\n    padding: 16px 14px;\n    border-radius: var(--radius-md);\n  }\n\n  .panel-title-group h2, .panel-title-group h3 {\n    font-size: 1rem;\n  }\n\n  .domains-scroll {\n    max-height: 240px;\n  }\n\n  .domain-item {\n    padding: 10px 12px;\n    min-height: 48px;\n  }\n\n  /* Modals Mobile */\n  .modal-overlay {\n    padding: 8px;\n    align-items: center;\n  }\n\n  .modal-card {\n    width: 100% !important;\n    max-width: 100% !important;\n    padding: 18px 14px !important;\n    border-radius: var(--radius-md) !important;\n    max-height: 92vh !important;\n  }\n\n  .problem-title {\n    font-size: 1.15rem;\n    margin: 10px 0;\n  }\n\n  .modal-badge-row {\n    flex-wrap: wrap;\n    gap: 6px;\n  }\n\n  .modal-footer-actions {\n    flex-direction: column;\n    width: 100%;\n    gap: 8px;\n  }\n\n  .modal-footer-actions .btn {\n    width: 100%;\n    justify-content: center;\n  }\n\n  /* Explore Modal Table Mobile */\n  .filter-bar {\n    flex-direction: column;\n    gap: 8px;\n  }\n\n  .filter-bar .form-input, .filter-bar .form-select {\n    width: 100% !important;\n  }\n\n  .table-container {\n    overflow-x: auto;\n    -webkit-overflow-scrolling: touch;\n    max-height: 55vh;\n  }\n\n  .data-table {\n    min-width: 500px;\n  }\n\n  .data-table th, .data-table td {\n    padding: 8px 10px;\n    font-size: 0.78rem;\n  }\n}\n\n/* VERY SMALL SCREENS (iPhone SE, 320px - 360px) */\n@media (max-width: 360px) {\n  .wheel-wrapper, .canvas-container {\n    width: 260px;\n    height: 260px;\n  }\n\n  .wheel-center-overlay {\n    width: 66px;\n    height: 66px;\n    border-width: 2px;\n  }\n\n  .hub-spin-text {\n    font-size: 0.78rem;\n  }\n\n  .hub-sub-text {\n    display: none;\n  }\n\n  .navbar {\n    padding: 8px 10px;\n  }\n\n  .brand-text h1 {\n    font-size: 0.98rem;\n  }\n\n  .logo-icon {\n    width: 32px;\n    height: 32px;\n    font-size: 18px;\n  }\n}\n\n/* ═══════════════════════════════════════════════════════════ */\n/* TEAM ENTRY GATE & TEAM TRACKING STYLES                    */\n/* ═══════════════════════════════════════════════════════════ */\n\n.entry-gate-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 1000;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n  background: var(--bg-primary);\n  background-image: \n    radial-gradient(circle at 50% 15%, rgba(6, 182, 212, 0.18) 0%, transparent 60%),\n    radial-gradient(circle at 80% 80%, rgba(99, 102, 241, 0.14) 0%, transparent 50%),\n    radial-gradient(circle at 20% 85%, rgba(244, 63, 94, 0.1) 0%, transparent 50%);\n  backdrop-filter: blur(20px);\n}\n\n.entry-gate-card {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  box-shadow: 0 25px 60px -15px rgba(0, 0, 0, 0.7), 0 0 40px rgba(6, 182, 212, 0.15);\n  padding: 40px 36px;\n  max-width: 480px;\n  width: 100%;\n  position: relative;\n  animation: entryPop 0.4s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n@keyframes entryPop {\n  from {\n    opacity: 0;\n    transform: scale(0.94) translateY(20px);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n}\n\n.entry-gate-logo {\n  text-align: center;\n}\n\n.entry-logo-icon {\n  font-size: 42px;\n  display: inline-block;\n  margin-bottom: 12px;\n  filter: drop-shadow(0 0 16px rgba(6, 182, 212, 0.5));\n}\n\n.entry-title {\n  font-size: 1.85rem;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  margin-bottom: 4px;\n}\n\n.entry-subtitle {\n  color: var(--text-muted);\n  font-size: 0.85rem;\n}\n\n.entry-divider {\n  height: 1px;\n  background: linear-gradient(90deg, transparent, var(--border-color), transparent);\n  margin: 22px 0 20px;\n}\n\n.entry-form-heading {\n  font-size: 0.95rem;\n  font-weight: 700;\n  color: var(--text-main);\n  text-align: center;\n  margin-bottom: 20px;\n}\n\n.entry-form .form-group {\n  margin-bottom: 16px;\n}\n\n.label-icon {\n  margin-right: 4px;\n  font-size: 0.95rem;\n}\n\n.entry-submit-btn {\n  margin-top: 10px;\n}\n\n.entry-footer-note {\n  font-size: 0.74rem;\n  color: var(--text-dim);\n  text-align: center;\n  margin-top: 18px;\n  line-height: 1.4;\n}\n\n/* Team Nav Pill */\n.team-nav-pill {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  background: rgba(6, 182, 212, 0.12);\n  border: 1px solid rgba(6, 182, 212, 0.3);\n  padding: 6px 14px;\n  border-radius: var(--radius-full);\n  font-size: 0.82rem;\n  font-weight: 700;\n  color: var(--accent-cyan);\n}\n\n.team-nav-icon {\n  font-size: 0.95rem;\n}\n\n/* Team Info Panel in Sidebar */\n.team-info-panel {\n  margin-bottom: 20px;\n}\n\n.team-session-badge {\n  font-size: 0.72rem;\n  font-weight: 700;\n  color: #34d399;\n  background: rgba(16, 185, 129, 0.15);\n  border: 1px solid rgba(16, 185, 129, 0.3);\n  padding: 2px 8px;\n  border-radius: var(--radius-full);\n}\n\n.team-info-body {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  margin-top: 14px;\n}\n\n.team-info-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 0.82rem;\n  padding: 8px 12px;\n  background: rgba(255, 255, 255, 0.03);\n  border-radius: var(--radius-sm);\n  border: 1px solid rgba(255, 255, 255, 0.04);\n}\n\n.team-info-label {\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n.team-info-value {\n  color: var(--text-main);\n  font-weight: 700;\n  font-family: var(--font-mono);\n}\n\n.team-info-link {\n  color: var(--accent-cyan);\n  text-decoration: none;\n  font-size: 0.78rem;\n  max-width: 140px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.team-info-link:hover {\n  text-decoration: underline;\n}\n\n.team-spin-counter {\n  color: var(--accent-cyan);\n  font-size: 1rem;\n}\n\n/* Subtle corner admin link */\n.admin-corner-link {\n  position: fixed;\n  bottom: 12px;\n  right: 14px;\n  color: var(--text-dim);\n  font-size: 0.75rem;\n  text-decoration: none;\n  background: rgba(18, 24, 38, 0.7);\n  border: 1px solid var(--border-color);\n  padding: 4px 10px;\n  border-radius: var(--radius-full);\n  backdrop-filter: blur(8px);\n  transition: all 0.2s ease;\n  z-index: 1001;\n}\n\n.admin-corner-link:hover {\n  color: var(--accent-cyan);\n  border-color: var(--accent-cyan);\n  background: var(--bg-card);\n}\n\n/* Entry Gate Admin Access on First Page */\n.entry-admin-access {\n  margin-top: 20px;\n  text-align: center;\n}\n\n.entry-admin-divider {\n  display: flex;\n  align-items: center;\n  text-align: center;\n  margin: 16px 0 14px;\n}\n\n.entry-admin-divider::before,\n.entry-admin-divider::after {\n  content: '';\n  flex: 1;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n}\n\n.entry-admin-divider span {\n  padding: 0 10px;\n  font-size: 0.7rem;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--text-dim);\n  font-weight: 700;\n}\n\n.entry-admin-btn {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  width: 100%;\n  text-decoration: none;\n  border: 1px solid rgba(99, 102, 241, 0.4);\n  color: #c7d2fe;\n  background: rgba(99, 102, 241, 0.1);\n  font-size: 0.88rem;\n  padding: 10px 16px;\n  border-radius: var(--radius-md);\n  font-weight: 600;\n  transition: all 0.2s ease;\n}\n\n.entry-admin-btn:hover {\n  background: rgba(99, 102, 241, 0.25);\n  border-color: #818cf8;\n  color: #ffffff;\n  transform: translateY(-1px);\n  box-shadow: 0 4px 18px rgba(99, 102, 241, 0.3);\n}\n\n/* Top-Right Admin Badge on Entry Screen */\n.entry-top-admin-badge {\n  position: absolute;\n  top: 22px;\n  right: 26px;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  background: rgba(18, 24, 38, 0.85);\n  border: 1px solid rgba(255, 255, 255, 0.15);\n  color: var(--text-muted);\n  padding: 7px 14px;\n  border-radius: var(--radius-full);\n  font-size: 0.8rem;\n  font-weight: 600;\n  text-decoration: none;\n  backdrop-filter: blur(10px);\n  transition: all 0.2s ease;\n  z-index: 1002;\n}\n\n.entry-top-admin-badge:hover {\n  border-color: var(--accent-cyan);\n  color: var(--accent-cyan);\n  background: rgba(24, 34, 52, 0.95);\n  box-shadow: 0 0 15px rgba(6, 182, 212, 0.25);\n}\n\n.admin-nav-link {\n  text-decoration: none;\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  border-color: rgba(99, 102, 241, 0.4) !important;\n  color: #c7d2fe !important;\n}\n\n.admin-nav-link:hover {\n  background: rgba(99, 102, 241, 0.2) !important;\n  border-color: #818cf8 !important;\n  color: #ffffff !important;\n}\n\n/* Assigned Problem Card (Center Stage) */\n.assigned-problem-card {\n  margin-top: 24px;\n  background: linear-gradient(135deg, rgba(24, 34, 52, 0.95), rgba(18, 24, 38, 0.98));\n  border: 1px solid rgba(6, 182, 212, 0.35);\n  border-radius: var(--radius-lg);\n  padding: 24px 28px;\n  box-shadow: 0 15px 35px -10px rgba(0, 0, 0, 0.6), 0 0 30px rgba(6, 182, 212, 0.15);\n  animation: entryPop 0.4s ease-out;\n  text-align: left;\n}\n\n.assigned-card-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin-bottom: 12px;\n}\n\n.assigned-lock-pill {\n  font-size: 0.76rem;\n  font-weight: 700;\n  color: #38bdf8;\n  background: rgba(6, 182, 212, 0.15);\n  border: 1px solid rgba(6, 182, 212, 0.3);\n  padding: 3px 10px;\n  border-radius: var(--radius-full);\n}\n\n.assigned-domain-tag {\n  font-size: 0.76rem;\n  font-weight: 700;\n  color: var(--accent-purple);\n  background: rgba(139, 92, 246, 0.15);\n  border: 1px solid rgba(139, 92, 246, 0.3);\n  padding: 3px 10px;\n  border-radius: var(--radius-full);\n}\n\n.assigned-card-title {\n  font-size: 1.25rem;\n  font-weight: 800;\n  color: #ffffff;\n  margin-bottom: 8px;\n  line-height: 1.35;\n}\n\n.assigned-card-desc {\n  font-size: 0.88rem;\n  color: var(--text-muted);\n  line-height: 1.5;\n  margin-bottom: 18px;\n  display: -webkit-box;\n  -webkit-line-clamp: 3;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n}\n\n/* Assigned Problem Card Split View */\n.assigned-split-view {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  margin-bottom: 16px;\n}\n\n.assigned-subcard {\n  padding: 12px 14px;\n  border-radius: var(--radius-sm);\n  background: rgba(15, 23, 42, 0.7);\n}\n\n.assigned-subcard.subcard-problem {\n  border-left: 3px solid #38bdf8;\n  border-top: 1px solid rgba(56, 189, 248, 0.2);\n  border-right: 1px solid rgba(56, 189, 248, 0.2);\n  border-bottom: 1px solid rgba(56, 189, 248, 0.2);\n}\n\n.assigned-subcard.subcard-solution {\n  border-left: 3px solid #10b981;\n  border-top: 1px solid rgba(16, 185, 129, 0.2);\n  border-right: 1px solid rgba(16, 185, 129, 0.2);\n  border-bottom: 1px solid rgba(16, 185, 129, 0.2);\n}\n\n.subcard-label {\n  font-size: 0.72rem;\n  font-weight: 800;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  display: block;\n  margin-bottom: 4px;\n}\n\n.subcard-problem .subcard-label {\n  color: #38bdf8;\n}\n\n.subcard-solution .subcard-label {\n  color: #34d399;\n}\n\n.assigned-subcard .assigned-card-desc {\n  font-size: 0.85rem;\n  line-height: 1.5;\n  color: #cbd5e1;\n  margin-bottom: 0;\n  display: -webkit-box;\n  -webkit-line-clamp: 3;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n}\n\n.assigned-card-actions {\n  display: flex;\n  gap: 12px;\n  flex-wrap: wrap;\n}\n\n.btn-locked {\n  background: #243044 !important;\n  color: #94a3b8 !important;\n  cursor: not-allowed !important;\n  box-shadow: none !important;\n  border: 1px solid #3b4d6b !important;\n  transform: none !important;\n}\n\n.center-btn-locked {\n  pointer-events: none !important;\n  opacity: 0.65 !important;\n  filter: grayscale(0.5);\n}\n",
  "app.js": "// SpinQuest PS — User Application Logic\n(function () {\n  'use strict';\n\n  // ─── STATE ──────────────────────────────────────────────────────────────────\n  let domains = [];\n  let activeDomain = 'Artificial Intelligence & ML';\n  let seenProblems = JSON.parse(localStorage.getItem('spinquest_seen_problems') || '{}');\n  let recentSpins = JSON.parse(localStorage.getItem('spinquest_recent_spins') || '[]');\n  let teamSession = JSON.parse(localStorage.getItem('spinquest_team_session') || 'null');\n  let teamHasSpun = false;\n  let assignedProblem = null;\n  let isSpinning = false;\n  let currentAngle = 0;\n  let spinAnimationFrame = null;\n\n  // ─── WEB AUDIO TICK ─────────────────────────────────────────────────────────\n  let audioCtx = null;\n  function playTickSound() {\n    try {\n      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n      if (audioCtx.state === 'suspended') audioCtx.resume();\n      const osc = audioCtx.createOscillator();\n      const gain = audioCtx.createGain();\n      osc.type = 'triangle';\n      osc.frequency.setValueAtTime(420 + Math.random() * 100, audioCtx.currentTime);\n      gain.gain.setValueAtTime(0.08, audioCtx.currentTime);\n      gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + 0.04);\n      osc.connect(gain);\n      gain.connect(audioCtx.destination);\n      osc.start();\n      osc.stop(audioCtx.currentTime + 0.04);\n    } catch (e) {}\n  }\n\n  // ─── DOMAIN THEMES ──────────────────────────────────────────────────────────\n  const DOMAIN_THEMES = [\n    { name: 'Artificial Intelligence & ML', icon: '🤖', color: '#06b6d4', dark: '#083344' },\n    { name: 'Cybersecurity & Privacy', icon: '🛡️', color: '#f43f5e', dark: '#4c0519' },\n    { name: 'Web & Mobile Development', icon: '🌐', color: '#8b5cf6', dark: '#2e1065' },\n    { name: 'Internet of Things (IoT)', icon: '📡', color: '#10b981', dark: '#022c22' },\n    { name: 'Cloud & DevOps', icon: '☁️', color: '#3b82f6', dark: '#172554' }\n  ];\n\n  function getDomainTheme(name) {\n    const safeName = (name || activeDomain || 'Artificial Intelligence & ML').toString().trim();\n    const found = DOMAIN_THEMES.find(t => t.name.toLowerCase() === safeName.toLowerCase());\n    if (found) return found;\n    let hash = 0;\n    for (let i = 0; i < safeName.length; i++) hash = safeName.charCodeAt(i) + ((hash << 5) - hash);\n    const c = (hash & 0x00FFFFFF).toString(16).toUpperCase();\n    return { name: safeName, icon: '💡', color: '#' + '00000'.substring(0, 6 - c.length) + c, dark: '#1e293b' };\n  }\n\n  // ─── DOM REFS ───────────────────────────────────────────────────────────────\n  const entryGate = document.getElementById('entryGate');\n  const mainApp = document.getElementById('mainApp');\n  const teamEntryForm = document.getElementById('teamEntryForm');\n  const entryTeamId = document.getElementById('entryTeamId');\n  const entryTeamName = document.getElementById('entryTeamName');\n  const entryGithubLink = document.getElementById('entryGithubLink');\n  const entryErrorMsg = document.getElementById('entryErrorMsg');\n  const entrySubmitBtn = document.getElementById('entrySubmitBtn');\n  const entrySubmitLabel = document.getElementById('entrySubmitLabel');\n\n  const navActiveDomainText = document.getElementById('navActiveDomainText');\n  const domainListContainer = document.getElementById('domainListContainer');\n  const spinDomainTarget = document.getElementById('spinDomainTarget');\n  const spinStatusMessage = document.getElementById('spinStatusMessage');\n  const spinCenterBtn = document.getElementById('spinCenterBtn');\n  const spinMainBtn = document.getElementById('spinMainBtn');\n  const wheelCanvas = document.getElementById('wheelCanvas');\n  const wheelPointer = document.querySelector('.wheel-pointer');\n  const keyboardHint = document.getElementById('keyboardHint');\n\n  const assignedProblemCard = document.getElementById('assignedProblemCard');\n  const assignedCardDomain = document.getElementById('assignedCardDomain');\n  const assignedCardTitle = document.getElementById('assignedCardTitle');\n  const assignedCardDesc = document.getElementById('assignedCardDesc');\n  const assignedCardProblem = document.getElementById('assignedCardProblem');\n  const assignedCardSolution = document.getElementById('assignedCardSolution');\n  const assignedCardDownloadPdfBtn = document.getElementById('assignedCardDownloadPdfBtn');\n  const assignedCardViewBtn = document.getElementById('assignedCardViewBtn');\n\n  const cycleProgressBar = document.getElementById('cycleProgressBar');\n  const cycleCountText = document.getElementById('cycleCountText');\n  const cycleRemainingText = document.getElementById('cycleRemainingText');\n  const resetCycleBtn = document.getElementById('resetCycleBtn');\n\n  const teamNavPill = document.getElementById('teamNavPill');\n  const teamNavName = document.getElementById('teamNavName');\n  const logoutBtn = document.getElementById('logoutBtn') || document.getElementById('switchTeamBtn');\n  const switchTeamBtn = logoutBtn;\n  const teamInfoId = document.getElementById('teamInfoId');\n  const teamInfoName = document.getElementById('teamInfoName');\n  const teamInfoGithub = document.getElementById('teamInfoGithub');\n  const teamGithubDisplay = document.getElementById('teamGithubDisplay');\n  const teamGithubForm = document.getElementById('teamGithubForm');\n  const mainGithubInput = document.getElementById('mainGithubInput');\n  const editGithubBtn = document.getElementById('editGithubBtn');\n  const saveGithubBtn = document.getElementById('saveGithubBtn');\n  const assignedCardGithubRow = document.getElementById('assignedCardGithubRow');\n  const assignedCardGithubValue = document.getElementById('assignedCardGithubValue');\n  const assignedCardGithubActionBtn = document.getElementById('assignedCardGithubActionBtn');\n  const teamSpinStatusBadge = document.getElementById('teamSpinStatusBadge');\n  const teamSidebarPdfBox = document.getElementById('teamSidebarPdfBox');\n  const teamSidebarDownloadPdfBtn = document.getElementById('teamSidebarDownloadPdfBtn');\n\n  const recentSpinsList = document.getElementById('recentSpinsList');\n  const viewProblemsBtn = document.getElementById('viewProblemsBtn');\n\n  const problemModal = document.getElementById('problemModal');\n  const closeProblemModal = document.getElementById('closeProblemModal');\n  const modalDomainTag = document.getElementById('modalDomainTag');\n  const modalDifficultyTag = document.getElementById('modalDifficultyTag');\n  const modalSourceTag = document.getElementById('modalSourceTag');\n  const modalProblemTitle = document.getElementById('modalProblemTitle');\n  const modalProblemDescription = document.getElementById('modalProblemDescription');\n  const modalProblemText = document.getElementById('modalProblemText');\n  const modalSolutionText = document.getElementById('modalSolutionText');\n  const modalTagsContainer = document.getElementById('modalTagsContainer');\n  const modalCycleStatusText = document.getElementById('modalCycleStatusText');\n  const cycleCompletionAlert = document.getElementById('cycleCompletionAlert');\n  const copyProblemBtn = document.getElementById('copyProblemBtn');\n  const modalDownloadPdfBtn = document.getElementById('modalDownloadPdfBtn');\n  const dismissProblemModalBtn = document.getElementById('dismissProblemModalBtn');\n\n  const exploreModal = document.getElementById('exploreModal');\n  const closeExploreModal = document.getElementById('closeExploreModal');\n  const exploreSearchInput = document.getElementById('exploreSearchInput');\n  const exploreDomainFilter = document.getElementById('exploreDomainFilter');\n  const exploreProblemsTableBody = document.getElementById('exploreProblemsTableBody');\n\n  // ─── INIT ───────────────────────────────────────────────────────────────────\n  async function init() {\n    setupEventListeners();\n    setupCanvas();\n    drawWheel();\n\n    if (teamSession && teamSession.sessionToken && teamSession.team) {\n      // Resume existing session & verify status\n      await verifyAndResumeSession();\n    } else {\n      showEntryGate();\n    }\n  }\n\n  async function verifyAndResumeSession() {\n    try {\n      const tid = teamSession.team?.teamId ? `&teamId=${encodeURIComponent(teamSession.team.teamId)}` : '';\n      const res = await fetch(`/api/team/status?sessionToken=${encodeURIComponent(teamSession.sessionToken)}${tid}`);\n      if (res.ok) {\n        const data = await res.json();\n        teamSession.team = data.team;\n        teamHasSpun = Boolean(data.hasSpun);\n        assignedProblem = data.assignedProblem || (data.team && data.team.assignedProblem) || (data.team?.spins && data.team.spins[0]) || null;\n        teamSession.hasSpun = teamHasSpun;\n        teamSession.assignedProblem = assignedProblem;\n        localStorage.setItem('spinquest_team_session', JSON.stringify(teamSession));\n        showMainApp(data.team);\n      } else {\n        // Fallback to local session\n        teamHasSpun = Boolean(teamSession.hasSpun);\n        assignedProblem = teamSession.assignedProblem || null;\n        showMainApp(teamSession.team);\n      }\n\n      // Auto-sync problem allocation with server database\n      if (teamHasSpun && assignedProblem && teamSession?.team?.teamId) {\n        fetch('/api/team/sync-spin', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({\n            teamId: teamSession.team.teamId,\n            domain: assignedProblem.domain || activeDomain,\n            problem: assignedProblem,\n            githubLink: teamSession.team.githubLink || ''\n          })\n        }).catch(() => {});\n      }\n    } catch (e) {\n      teamHasSpun = Boolean(teamSession.hasSpun);\n      assignedProblem = teamSession.assignedProblem || null;\n      showMainApp(teamSession.team);\n    }\n  }\n\n  // ─── ENTRY GATE ─────────────────────────────────────────────────────────────\n  function showEntryGate() {\n    entryGate.classList.remove('hidden');\n    mainApp.classList.add('hidden');\n  }\n\n  function showMainApp(team) {\n    entryGate.classList.add('hidden');\n    mainApp.classList.remove('hidden');\n    renderTeamInfo(team);\n    if (team && team.domain) {\n      activeDomain = team.domain;\n    }\n    fetchDomains();\n\n    const activeProblem = assignedProblem || teamSession?.assignedProblem || team?.assignedProblem || (team?.spins && team.spins[0]);\n\n    if (team && team.isAdmin) {\n      unlockWheel();\n      if (activeProblem) {\n        assignedCardDomain.textContent = activeProblem.domain;\n        assignedCardTitle.textContent = activeProblem.title;\n        assignedCardDesc.textContent = activeProblem.description;\n        assignedProblemCard.classList.remove('hidden');\n        teamSidebarPdfBox.classList.remove('hidden');\n        renderAssignedProblemList(activeProblem);\n      }\n    } else if (teamHasSpun || activeProblem) {\n      lockWheelForAssignedProblem(activeProblem);\n    } else {\n      unlockWheel();\n    }\n  }\n\n  function renderTeamInfo(team) {\n    teamNavName.textContent = team ? (team.teamName || team.teamId) : '—';\n    teamInfoId.textContent = team ? team.teamId : '—';\n    teamInfoName.textContent = team ? (team.teamName || team.teamId) : '—';\n    updateGithubUI(team ? team.githubLink : '');\n\n    if (team && team.isAdmin) {\n      teamSpinStatusBadge.textContent = 'Admin Mode (Unlimited Spins)';\n      teamSpinStatusBadge.style.color = '#a855f7';\n      if (assignedProblem) {\n        teamSidebarPdfBox.classList.remove('hidden');\n      } else {\n        teamSidebarPdfBox.classList.add('hidden');\n      }\n    } else if (teamHasSpun) {\n      teamSpinStatusBadge.textContent = '1 / 1 (Used)';\n      teamSpinStatusBadge.style.color = '#38bdf8';\n      teamSidebarPdfBox.classList.remove('hidden');\n    } else {\n      teamSpinStatusBadge.textContent = '0 / 1 (Available)';\n      teamSpinStatusBadge.style.color = 'var(--accent-emerald)';\n      teamSidebarPdfBox.classList.add('hidden');\n    }\n  }\n\n  function updateGithubUI(githubUrl) {\n    const clean = (githubUrl || '').trim();\n    if (clean) {\n      if (teamInfoGithub) {\n        teamInfoGithub.textContent = clean;\n        teamInfoGithub.href = clean;\n      }\n      if (teamGithubDisplay) teamGithubDisplay.classList.remove('hidden');\n      if (teamGithubForm) teamGithubForm.classList.add('hidden');\n      if (editGithubBtn) editGithubBtn.classList.remove('hidden');\n      if (mainGithubInput) mainGithubInput.value = clean;\n\n      if (assignedCardGithubValue) {\n        assignedCardGithubValue.innerHTML = `<a href=\"${escapeHTML(clean)}\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--accent-cyan); text-decoration:underline;\">${escapeHTML(clean)}</a>`;\n      }\n      if (assignedCardGithubActionBtn) {\n        assignedCardGithubActionBtn.innerHTML = `✏️ Edit Link`;\n      }\n    } else {\n      if (teamGithubDisplay) teamGithubDisplay.classList.add('hidden');\n      if (teamGithubForm) teamGithubForm.classList.remove('hidden');\n      if (editGithubBtn) editGithubBtn.classList.add('hidden');\n      if (mainGithubInput) mainGithubInput.value = '';\n\n      if (assignedCardGithubValue) {\n        assignedCardGithubValue.textContent = 'Not linked yet';\n      }\n      if (assignedCardGithubActionBtn) {\n        assignedCardGithubActionBtn.innerHTML = `+ Place GitHub Link`;\n      }\n    }\n  }\n\n  async function handleSaveGithub(e) {\n    if (e) e.preventDefault();\n    const githubLink = (mainGithubInput ? mainGithubInput.value : '').trim();\n    if (!githubLink) {\n      showToast('Please enter your GitHub repository URL', 'warning');\n      return;\n    }\n\n    if (saveGithubBtn) {\n      saveGithubBtn.disabled = true;\n      saveGithubBtn.textContent = 'Saving...';\n    }\n\n    try {\n      const res = await fetch('/api/team/github', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          sessionToken: teamSession?.sessionToken,\n          teamId: teamSession?.team?.teamId,\n          githubLink\n        })\n      });\n\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Failed to save GitHub link');\n\n      if (teamSession && teamSession.team) {\n        teamSession.team.githubLink = githubLink;\n        localStorage.setItem('spinquest_team_session', JSON.stringify(teamSession));\n      }\n\n      updateGithubUI(githubLink);\n      showToast('GitHub repository link placed successfully! 🚀', 'success');\n    } catch (err) {\n      showToast(err.message, 'error');\n    } finally {\n      if (saveGithubBtn) {\n        saveGithubBtn.disabled = false;\n        saveGithubBtn.textContent = 'Save';\n      }\n    }\n  }\n\n  function handleEditGithub() {\n    if (teamGithubDisplay) teamGithubDisplay.classList.add('hidden');\n    if (teamGithubForm) teamGithubForm.classList.remove('hidden');\n    if (mainGithubInput) {\n      mainGithubInput.focus();\n      mainGithubInput.select();\n    }\n  }\n\n  // ─── TEAM REGISTRATION ──────────────────────────────────────────────────────\n  async function handleTeamRegister(e) {\n    e.preventDefault();\n    entryErrorMsg.classList.add('hidden');\n    entryErrorMsg.textContent = '';\n\n    const teamId = entryTeamId.value.trim();\n    const teamName = entryTeamName.value.trim();\n    const githubLink = entryGithubLink.value.trim();\n\n    if (!teamId) { showEntryError('Please enter your Reg ID / Team ID.'); return; }\n\n    entrySubmitLabel.textContent = 'Entering...';\n    entrySubmitBtn.disabled = true;\n\n    try {\n      const res = await fetch('/api/team/register', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ teamId, teamName, githubLink })\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Registration failed');\n\n      teamHasSpun = Boolean(data.hasSpun);\n      assignedProblem = data.assignedProblem || null;\n\n      teamSession = {\n        sessionToken: data.sessionToken,\n        team: data.team,\n        hasSpun: teamHasSpun,\n        assignedProblem: assignedProblem\n      };\n      localStorage.setItem('spinquest_team_session', JSON.stringify(teamSession));\n\n      if (data.isReturning) {\n        if (data.team && data.team.isAdmin) {\n          showToast(`Welcome back, Admin! ⚡ Main page test access granted.`, 'info');\n        } else if (teamHasSpun) {\n          showToast(`Welcome back, ${data.team.teamName}! Your assigned problem statement is ready. 📄`, 'info');\n        } else {\n          showToast(`Welcome back, ${data.team.teamName}! You have 1 spin available. ⚡`, 'info');\n        }\n      } else {\n        if (data.team && data.team.isAdmin) {\n          showToast(`Welcome Admin! ⚡ Main page test access granted.`, 'success');\n        } else {\n          showToast(`Welcome, ${data.team.teamName}! 🚀 You have 1 spin to draw your challenge.`, 'success');\n        }\n      }\n\n      showMainApp(data.team);\n    } catch (err) {\n      showEntryError(err.message);\n    } finally {\n      entrySubmitLabel.textContent = 'Verify & Enter';\n      entrySubmitBtn.disabled = false;\n    }\n  }\n\n  function showEntryError(msg) {\n    entryErrorMsg.textContent = msg;\n    entryErrorMsg.classList.remove('hidden');\n  }\n\n  function handleLogout() {\n    const currentName = teamSession?.team?.teamName || 'your team';\n    if (!confirm(`Are you sure you want to log out of \"${currentName}\"?`)) return;\n    localStorage.removeItem('spinquest_team_session');\n    teamSession = null;\n    teamHasSpun = false;\n    assignedProblem = null;\n    if (entryTeamId) entryTeamId.value = '';\n    if (entryTeamName) entryTeamName.value = '';\n    if (entryGithubLink) entryGithubLink.value = '';\n    unlockWheel();\n    showEntryGate();\n    showToast('Logged out successfully. 🚪', 'info');\n  }\n  const handleSwitchTeam = handleLogout;\n\n  // ─── DOMAIN API ─────────────────────────────────────────────────────────────\n  async function fetchDomains() {\n    try {\n      const res = await fetch('/api/domains');\n      const data = await res.json();\n      domains = data.domains;\n      if (!domains.find(d => d.name.toLowerCase() === activeDomain.toLowerCase()) && domains.length > 0) {\n        activeDomain = domains[0].name;\n      }\n      renderDomains();\n      updateActiveDomainUI();\n      updateCycleDisplay();\n      populateExploreFilter();\n      drawWheel();\n    } catch (err) {\n      showToast('Failed to load domains: ' + err.message, 'error');\n    }\n  }\n\n  function renderDomains() {\n    domainListContainer.innerHTML = '';\n    domains.forEach(d => {\n      const theme = getDomainTheme(d.name);\n      const isAct = d.name.toLowerCase() === activeDomain.toLowerCase();\n      const item = document.createElement('div');\n      item.className = `domain-item ${isAct ? 'active' : ''}`;\n      item.innerHTML = `\n        <div class=\"domain-item-left\">\n          <span class=\"domain-icon\">${theme.icon}</span>\n          <span class=\"domain-name\">${escapeHTML(d.name)}</span>\n        </div>\n        <div class=\"domain-item-right\">\n          <span class=\"domain-count-badge\">${d.count} PS</span>\n        </div>\n      `;\n      item.addEventListener('click', () => {\n        if (teamHasSpun) {\n          showToast('Domain is locked because your team has already drawn a problem statement.', 'info');\n          return;\n        }\n        selectDomain(d.name);\n      });\n      domainListContainer.appendChild(item);\n    });\n  }\n\n  function selectDomain(name) {\n    activeDomain = name;\n    updateActiveDomainUI();\n    renderDomains();\n    updateCycleDisplay();\n    drawWheel();\n  }\n\n  function updateActiveDomainUI() {\n    navActiveDomainText.textContent = activeDomain;\n    spinDomainTarget.textContent = activeDomain;\n    if (!teamHasSpun) {\n      spinStatusMessage.innerHTML = `Ready to spin for <strong>${escapeHTML(activeDomain)}</strong> (1 spin limit)`;\n    }\n  }\n\n  function populateExploreFilter() {\n    exploreDomainFilter.innerHTML = '<option value=\"All\">All Domains</option>';\n    domains.forEach(d => {\n      const opt = document.createElement('option');\n      opt.value = d.name;\n      opt.textContent = `${d.name} (${d.count} PS)`;\n      exploreDomainFilter.appendChild(opt);\n    });\n  }\n\n  // ─── CYCLE TRACKER ──────────────────────────────────────────────────────────\n  function getSeenList(domain) {\n    if (!seenProblems[domain]) seenProblems[domain] = [];\n    return seenProblems[domain];\n  }\n\n  function addSeenProblem(domain, problemId) {\n    const list = getSeenList(domain);\n    if (!list.includes(problemId)) {\n      list.push(problemId);\n      seenProblems[domain] = list;\n      localStorage.setItem('spinquest_seen_problems', JSON.stringify(seenProblems));\n    }\n    updateCycleDisplay();\n  }\n\n  function resetCycle(domain) {\n    if (teamHasSpun) {\n      showToast('Cycle is locked. Your team has already drawn its challenge.', 'info');\n      return;\n    }\n    seenProblems[domain] = [];\n    localStorage.setItem('spinquest_seen_problems', JSON.stringify(seenProblems));\n    updateCycleDisplay();\n    showToast(`Cycle reset for ${domain}! All problems are now available.`, 'info');\n  }\n\n  function updateCycleDisplay() {\n    const currentDomainObj = domains.find(d => d.name.toLowerCase() === activeDomain.toLowerCase());\n    const total = currentDomainObj ? currentDomainObj.count : 0;\n    const seen = getSeenList(activeDomain).length;\n    const remaining = Math.max(0, total - seen);\n    const percent = total > 0 ? Math.min(100, Math.round((seen / total) * 100)) : 0;\n    if (cycleProgressBar) cycleProgressBar.style.width = `${percent}%`;\n    if (cycleCountText) cycleCountText.textContent = `${seen} / ${total} seen`;\n    if (cycleRemainingText) cycleRemainingText.textContent = `${remaining} remaining in cycle`;\n  }\n\n  // ─── CANVAS WHEEL ───────────────────────────────────────────────────────────\n  let ctx = null;\n  const numSlices = 12;\n\n  function setupCanvas() {\n    ctx = wheelCanvas.getContext('2d');\n  }\n\n  function drawWheel() {\n    if (!ctx && wheelCanvas) {\n      ctx = wheelCanvas.getContext('2d');\n    }\n    if (!ctx) return;\n    const width = wheelCanvas.width;\n    const center = width / 2;\n    const radius = center - 16;\n    ctx.clearRect(0, 0, width, width);\n    ctx.save();\n    ctx.translate(center, center);\n    ctx.rotate(currentAngle);\n    const sliceAngle = (Math.PI * 2) / numSlices;\n    const activeTheme = getDomainTheme(activeDomain);\n    const palette = [\n      activeTheme.color, '#1e293b', activeTheme.dark, '#334155',\n      activeTheme.color, '#0f172a', '#64748b', activeTheme.dark,\n      activeTheme.color, '#1e293b', '#475569', '#0f172a'\n    ];\n    for (let i = 0; i < numSlices; i++) {\n      const startAngle = i * sliceAngle;\n      const endAngle = startAngle + sliceAngle;\n      ctx.beginPath(); ctx.moveTo(0, 0);\n      ctx.arc(0, 0, radius, startAngle, endAngle); ctx.closePath();\n      ctx.fillStyle = palette[i % palette.length]; ctx.fill();\n      ctx.lineWidth = 2; ctx.strokeStyle = 'rgba(255,255,255,0.15)'; ctx.stroke();\n      ctx.save();\n      ctx.rotate(startAngle + sliceAngle / 2);\n      ctx.textAlign = 'right'; ctx.fillStyle = '#ffffff';\n      ctx.font = 'bold 14px Plus Jakarta Sans, sans-serif';\n      const label = (i % 2 === 0) ? `${activeTheme.icon} PS #${i + 1}` : `✨ CHALLENGE`;\n      ctx.fillText(label, radius - 24, 5);\n      ctx.beginPath();\n      ctx.arc(radius - 8, 0, 4, 0, Math.PI * 2);\n      ctx.fillStyle = (i % 2 === 0) ? '#38bdf8' : '#f43f5e';\n      ctx.shadowColor = ctx.fillStyle; ctx.shadowBlur = 8; ctx.fill(); ctx.shadowBlur = 0;\n      ctx.restore();\n    }\n    ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2);\n    ctx.lineWidth = 8; ctx.strokeStyle = '#2a3a52'; ctx.stroke();\n    ctx.restore();\n  }\n\n  // ─── EXTRACT STRUCTURED PROBLEM DETAILS (Title | Problem | Expected Solution) ─\n  function extractProblemParts(problem) {\n    if (!problem) return { title: 'Assigned Problem Statement', problem: '', expectedSolution: '', tags: [] };\n    const title = problem.title || problem.problemTitle || 'Assigned Problem Statement';\n    let probText = problem.problem || problem.problemText || '';\n    let solText = problem.expectedSolution || problem.solution || '';\n\n    if (!probText || !solText) {\n      const rawDesc = problem.description || problem.problemDescription || '';\n      const probIdx = rawDesc.search(/(?:^|\\n)\\s*Problem\\s*:\\s*/i);\n      const solIdx = rawDesc.search(/(?:^|\\n)\\s*Expected\\s+Solution\\s*:\\s*/i);\n\n      if (probIdx !== -1 && solIdx !== -1 && solIdx > probIdx) {\n        const afterProb = rawDesc.substring(probIdx).replace(/^(?:^|\\n)\\s*Problem\\s*:\\s*/i, '');\n        const nextSol = afterProb.search(/(?:^|\\n)\\s*Expected\\s+Solution\\s*:\\s*/i);\n        if (nextSol !== -1) {\n          probText = afterProb.substring(0, nextSol).trim();\n          solText = afterProb.substring(nextSol).replace(/^(?:^|\\n)\\s*Expected\\s+Solution\\s*:\\s*/i, '').trim();\n        }\n      } else if (solIdx !== -1) {\n        probText = rawDesc.substring(0, solIdx).trim();\n        solText = rawDesc.substring(solIdx).replace(/^(?:^|\\n)\\s*Expected\\s+Solution\\s*:\\s*/i, '').trim();\n      } else {\n        probText = rawDesc.trim();\n        solText = 'Design and implement a complete, production-grade software solution addressing the core challenges, with clean architecture and deployment artifacts.';\n      }\n    }\n\n    return {\n      title,\n      problem: probText,\n      expectedSolution: solText,\n      domain: problem.domain || activeDomain || 'Hackathon Track',\n      difficulty: problem.difficulty || problem.problemDifficulty || 'Intermediate',\n      tags: problem.tags || []\n    };\n  }\n\n  // ─── LOCK / UNLOCK 1-SPIN SYSTEM ──────────────────────────────────────────\n  function lockWheelForAssignedProblem(problem) {\n    teamHasSpun = true;\n    assignedProblem = problem;\n    if (teamSession) {\n      teamSession.hasSpun = true;\n      teamSession.assignedProblem = problem;\n      try {\n        localStorage.setItem('spinquest_team_session', JSON.stringify(teamSession));\n      } catch (e) {}\n    }\n    const parts = extractProblemParts(problem);\n\n    // Center Stage Controls Lock\n    spinMainBtn.disabled = true;\n    spinMainBtn.classList.add('btn-locked');\n    spinMainBtn.innerHTML = `<span>🔒 PROBLEM ASSIGNED (1/1 SPIN USED)</span>`;\n    spinCenterBtn.classList.add('center-btn-locked');\n    spinStatusMessage.innerHTML = `🔒 Official Allocation: <strong>${escapeHTML(parts.title)}</strong>`;\n    keyboardHint.textContent = '🔒 Spin completed. Each team receives strictly 1 problem statement.';\n\n    // Show Allocated Challenge Card with Title, Problem & Expected Solution\n    assignedCardDomain.textContent = parts.domain;\n    assignedCardTitle.textContent = parts.title;\n    if (assignedCardProblem) assignedCardProblem.textContent = parts.problem;\n    if (assignedCardSolution) assignedCardSolution.textContent = parts.expectedSolution;\n    if (assignedCardDesc) assignedCardDesc.textContent = parts.problem;\n    assignedProblemCard.classList.remove('hidden');\n\n    // Sidebar Team Info\n    teamSpinStatusBadge.textContent = '1 / 1 (Used)';\n    teamSpinStatusBadge.style.color = '#38bdf8';\n    teamSidebarPdfBox.classList.remove('hidden');\n\n    // Show in Assigned Problem List\n    renderAssignedProblemList(problem);\n  }\n\n  function unlockWheel() {\n    teamHasSpun = false;\n    assignedProblem = null;\n    spinMainBtn.disabled = false;\n    spinMainBtn.classList.remove('btn-locked');\n    spinMainBtn.innerHTML = `<span class=\"btn-icon\">⚡</span><span>SPIN PROBLEM WHEEL</span>`;\n    spinCenterBtn.classList.remove('center-btn-locked');\n    keyboardHint.innerHTML = 'Tip: Press <kbd>Spacebar</kbd> anytime to spin! (1 spin allowed)';\n    assignedProblemCard.classList.add('hidden');\n    teamSpinStatusBadge.textContent = '0 / 1 (Available)';\n    teamSpinStatusBadge.style.color = 'var(--accent-emerald)';\n    teamSidebarPdfBox.classList.add('hidden');\n    recentSpinsList.innerHTML = `<div class=\"empty-state\">No spins yet. Choose a domain and spin! (1 spin allowed)</div>`;\n    drawWheel();\n  }\n\n  function renderAssignedProblemList(problem) {\n    recentSpinsList.innerHTML = `\n      <div class=\"history-item\" style=\"border-left: 3px solid var(--accent-cyan); background: rgba(6,182,212,0.06);\">\n        <div class=\"history-item-top\">\n          <span class=\"history-domain\">${escapeHTML(problem.domain)}</span>\n          <span class=\"history-time\" style=\"color:#38bdf8;\">Assigned</span>\n        </div>\n        <div class=\"history-title\" style=\"font-weight:700;\">${escapeHTML(problem.title)}</div>\n        <div style=\"font-size:0.75rem; color:var(--text-muted); margin-top:4px;\">\n          Difficulty: ${escapeHTML(problem.difficulty || 'Intermediate')}\n        </div>\n      </div>\n    `;\n  }\n\n  // ─── SPIN LOGIC ─────────────────────────────────────────────────────────────\n  async function triggerSpin() {\n    if (isSpinning) return;\n    const isAdmin = Boolean(teamSession?.team?.isAdmin);\n    if (teamHasSpun && !isAdmin) {\n      showToast('Your team has already completed its 1 allowed spin! 🔒', 'info');\n      if (assignedProblem) openProblemModal(assignedProblem);\n      return;\n    }\n\n    const seenIds = getSeenList(activeDomain);\n    spinStatusMessage.innerHTML = `🎲 Rolling problem statement from <strong>${escapeHTML(activeDomain)}</strong>...`;\n    isSpinning = true;\n    spinMainBtn.disabled = true;\n    spinCenterBtn.style.pointerEvents = 'none';\n\n    try {\n      const response = await fetch('/api/spin', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          domain: activeDomain,\n          seenIds,\n          sessionToken: teamSession ? teamSession.sessionToken : null,\n          teamId: teamSession ? teamSession.team?.teamId : null\n        })\n      });\n\n      const spinResult = await response.json();\n\n      if (!response.ok) {\n        // 429 = spin lock (concurrent request) — retry once after a short delay\n        if (response.status === 429) {\n          await new Promise(r => setTimeout(r, 1500));\n          isSpinning = false;\n          spinMainBtn.disabled = false;\n          spinCenterBtn.style.pointerEvents = 'auto';\n          triggerSpin();\n          return;\n        }\n        if (spinResult.alreadySpun && spinResult.problem) {\n          lockWheelForAssignedProblem(spinResult.problem);\n          throw new Error(spinResult.error || 'Your team has already drawn a problem statement.');\n        }\n        throw new Error(spinResult.error || 'Failed to draw problem statement');\n      }\n\n      startWheelAnimation(() => onSpinComplete(spinResult));\n    } catch (err) {\n      isSpinning = false;\n      if (!teamHasSpun) {\n        spinMainBtn.disabled = false;\n        spinCenterBtn.style.pointerEvents = 'auto';\n        spinStatusMessage.innerHTML = `⚠️ Error: ${err.message}`;\n      }\n      showToast(err.message, 'error');\n    }\n  }\n\n  function startWheelAnimation(onFinish) {\n    const totalRotations = 5 + Math.random() * 4;\n    const targetDelta = totalRotations * Math.PI * 2 + (Math.random() * Math.PI * 2);\n    const startAngle = currentAngle;\n    const finalAngle = startAngle + targetDelta;\n    const duration = 3800;\n    const startTime = performance.now();\n    let lastTickAngle = currentAngle;\n\n    function animate(now) {\n      const elapsed = now - startTime;\n      const progress = Math.min(1, elapsed / duration);\n      const ease = 1 - Math.pow(1 - progress, 4);\n      currentAngle = startAngle + targetDelta * ease;\n      const sliceAngle = (Math.PI * 2) / numSlices;\n      if (Math.abs(currentAngle - lastTickAngle) >= sliceAngle) {\n        lastTickAngle = currentAngle;\n        playTickSound();\n        if (wheelPointer) {\n          wheelPointer.classList.add('tick');\n          setTimeout(() => wheelPointer && wheelPointer.classList.remove('tick'), 50);\n        }\n      }\n      drawWheel();\n      if (progress < 1) {\n        spinAnimationFrame = requestAnimationFrame(animate);\n      } else {\n        isSpinning = false;\n        if (onFinish) onFinish();\n      }\n    }\n    spinAnimationFrame = requestAnimationFrame(animate);\n  }\n\n  async function onSpinComplete(result) {\n    const { problem, cycleCompleted, totalInDomain, remainingInCycle } = result;\n\n    if (window.confetti) {\n      window.confetti({ particleCount: 90, spread: 80, origin: { y: 0.6 } });\n    }\n\n    if (cycleCompleted) {\n      seenProblems[activeDomain] = [problem.id];\n      cycleCompletionAlert.classList.remove('hidden');\n    } else {\n      addSeenProblem(activeDomain, problem.id);\n      cycleCompletionAlert.classList.add('hidden');\n    }\n    localStorage.setItem('spinquest_seen_problems', JSON.stringify(seenProblems));\n    updateCycleDisplay();\n\n    // Log spin permanently to team record\n    if (teamSession && (teamSession.sessionToken || teamSession.team?.teamId)) {\n      try {\n        await fetch('/api/team/log-spin', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({\n            sessionToken: teamSession.sessionToken,\n            teamId: teamSession.team?.teamId,\n            teamName: teamSession.team?.teamName,\n            domain: activeDomain,\n            problem\n          })\n        });\n      } catch (e) {\n        // Non-fatal fallback\n      }\n    }\n\n    // Lock permanently to 1 spin (regular teams only; admin can test multiple spins)\n    const isAdmin = Boolean(teamSession?.team?.isAdmin);\n    assignedProblem = problem;\n\n    if (!isAdmin) {\n      teamHasSpun = true;\n      if (teamSession) {\n        teamSession.hasSpun = true;\n        teamSession.assignedProblem = problem;\n        localStorage.setItem('spinquest_team_session', JSON.stringify(teamSession));\n      }\n      lockWheelForAssignedProblem(problem);\n    } else {\n      teamHasSpun = false;\n      if (teamSession) {\n        teamSession.hasSpun = false;\n        teamSession.assignedProblem = problem;\n        localStorage.setItem('spinquest_team_session', JSON.stringify(teamSession));\n      }\n      const parts = extractProblemParts(problem);\n      assignedCardDomain.textContent = parts.domain;\n      assignedCardTitle.textContent = parts.title;\n      if (assignedCardProblem) assignedCardProblem.textContent = parts.problem;\n      if (assignedCardSolution) assignedCardSolution.textContent = parts.expectedSolution;\n      if (assignedCardDesc) assignedCardDesc.textContent = parts.problem;\n      assignedProblemCard.classList.remove('hidden');\n      teamSidebarPdfBox.classList.remove('hidden');\n      renderAssignedProblemList(problem);\n      spinMainBtn.disabled = false;\n      spinCenterBtn.style.pointerEvents = 'auto';\n      spinStatusMessage.innerHTML = `✅ Test Allocation: <strong>${escapeHTML(parts.title)}</strong> (Admin can spin again)`;\n    }\n\n    openProblemModal(problem);\n    showToast('Challenge officially allocated! You can now download your PDF. 📄', 'success');\n  }\n\n  // ─── PROBLEM MODAL ──────────────────────────────────────────────────────────\n  function openProblemModal(problem) {\n    const parts = extractProblemParts(problem);\n    modalDomainTag.textContent = parts.domain;\n    modalDifficultyTag.textContent = parts.difficulty;\n    modalSourceTag.textContent = `1/1 Spin Allocated`;\n    modalProblemTitle.textContent = parts.title;\n\n    if (modalProblemText) modalProblemText.textContent = parts.problem;\n    if (modalSolutionText) modalSolutionText.textContent = parts.expectedSolution;\n    if (modalProblemDescription) modalProblemDescription.textContent = `Problem:\\n${parts.problem}\\n\\nExpected Solution:\\n${parts.expectedSolution}`;\n\n    modalTagsContainer.innerHTML = '';\n    if (parts.tags && parts.tags.length > 0) {\n      parts.tags.forEach(t => {\n        const span = document.createElement('span');\n        span.className = 'tag-badge';\n        span.textContent = '#' + t;\n        modalTagsContainer.appendChild(span);\n      });\n    }\n\n    modalCycleStatusText.textContent = `Official Hackathon Allocation for ${teamSession?.team?.teamName || 'Your Team'}`;\n    openModal(problemModal);\n  }\n\n  // ─── VISITOR PDF DOWNLOAD ──────────────────────────────────────────────────\n  function printProblemCertificate(team, problem) {\n    try {\n      const printWin = window.open('', '_blank');\n      if (!printWin) {\n        showToast('Please allow popups to open and save your problem statement PDF.', 'info');\n        return;\n      }\n      const teamName = team?.teamName || 'Team';\n      const teamId = team?.teamId || 'N/A';\n      const leader = team?.leader || '';\n      const college = team?.college || '';\n      const members = team?.members || '';\n      const githubLink = team?.githubLink || 'Not provided';\n\n      const parts = extractProblemParts(problem);\n      const title = parts.title;\n      const probText = parts.problem;\n      const solText = parts.expectedSolution;\n      const domain = parts.domain || activeDomain || 'Hackathon Track';\n      const diff = parts.difficulty || 'Intermediate';\n      const tags = (parts.tags && parts.tags.length) ? ('#' + parts.tags.join('   #')) : '';\n\n      const html = `<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Problem-Statement-${escapeHTML(teamId)}</title>\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #fff; color: #0f172a; padding: 32px; max-width: 820px; margin: 0 auto; }\n    .header { background: #0a0d14; color: #fff; padding: 22px; border-radius: 8px; text-align: center; margin-bottom: 20px; }\n    .header h1 { font-size: 24px; color: #06b6d4; letter-spacing: 1px; }\n    .header p { font-size: 13px; color: #94a3b8; margin-top: 5px; }\n    .badge { display: inline-block; background: #1e293b; color: #38bdf8; padding: 4px 12px; border-radius: 4px; font-size: 10px; font-weight: bold; margin-top: 8px; letter-spacing: 0.5px; }\n    \n    .box { border: 1px solid #cbd5e1; border-radius: 8px; padding: 16px; margin-bottom: 16px; background: #f8fafc; }\n    .box-title { font-size: 11px; font-weight: bold; color: #0284c7; text-transform: uppercase; margin-bottom: 6px; }\n    .team-name { font-size: 16px; font-weight: 700; color: #0f172a; }\n    .team-meta { font-size: 12.5px; color: #475569; margin-top: 4px; line-height: 1.5; }\n    \n    .domain-bar { background: #1e293b; color: #fff; padding: 10px 16px; border-radius: 6px; font-size: 12.5px; font-weight: 600; display: flex; justify-content: space-between; margin-bottom: 16px; }\n    .domain-title { color: #38bdf8; }\n    \n    .title-card { background: #f1f5f9; border: 1px solid #94a3b8; border-radius: 8px; padding: 14px 18px; margin-bottom: 16px; }\n    .title-label { font-size: 10px; font-weight: 800; color: #0284c7; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 4px; }\n    .title-text { font-size: 16px; font-weight: 700; color: #0f172a; line-height: 1.35; }\n    \n    .section-card { border-radius: 8px; padding: 16px 18px; margin-bottom: 16px; }\n    .card-problem { background: #f0f9ff; border: 1.5px solid #38bdf8; border-left: 5px solid #0284c7; }\n    .card-solution { background: #ecfdf5; border: 1.5px solid #10b981; border-left: 5px solid #059669; }\n    \n    .card-label { font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; }\n    .label-problem { color: #0369a1; }\n    .label-solution { color: #047857; }\n    \n    .card-content { font-size: 13px; line-height: 1.6; color: #1e293b; white-space: pre-line; }\n    \n    .tags { font-size: 12px; color: #475569; font-weight: 600; margin-bottom: 16px; padding: 8px 12px; background: #f8fafc; border-radius: 6px; }\n    .rules { background: #fffbeb; border: 1px solid #fde68a; border-radius: 8px; padding: 14px; font-size: 11.5px; color: #92400e; line-height: 1.6; }\n    .footer { text-align: center; margin-top: 24px; font-size: 10.5px; color: #94a3b8; border-top: 1px solid #e2e8f0; padding-top: 12px; }\n    @media print {\n      body { padding: 8px; }\n      @page { margin: 1cm; size: A4; }\n      .section-card { page-break-inside: avoid; }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"header\">\n    <h1>CODIENYCH 1.0</h1>\n    <p>Official Problem Statement Allocation Certificate</p>\n    <div class=\"badge\">VERIFIED HACKATHON ALLOCATION • 1 OF 1 PROBLEM ASSIGNMENT</div>\n  </div>\n\n  <div class=\"box\">\n    <div class=\"box-title\">Registered Team Details (CODIENYCH 1.0)</div>\n    <div class=\"team-name\">${escapeHTML(teamName)}</div>\n    <div class=\"team-meta\">\n      <strong>Reg ID:</strong> ${escapeHTML(teamId)} &nbsp;|&nbsp; <strong>Leader:</strong> ${escapeHTML(leader || 'Team Leader')} ${college ? `&nbsp;|&nbsp; <strong>College:</strong> ${escapeHTML(college)}` : ''}\n      ${members ? `<br><strong>Members:</strong> ${escapeHTML(members)}` : ''}\n      ${githubLink && githubLink !== 'Not provided' ? `<br><strong>GitHub:</strong> ${escapeHTML(githubLink)}` : ''}\n    </div>\n  </div>\n\n  <div class=\"domain-bar\">\n    <span class=\"domain-title\">Domain: ${escapeHTML(domain)}</span>\n    <span>Difficulty: ${escapeHTML(diff)}</span>\n  </div>\n\n  <div class=\"title-card\">\n    <div class=\"title-label\">ASSIGNED PROBLEM TITLE:</div>\n    <div class=\"title-text\">${escapeHTML(title)}</div>\n  </div>\n\n  <div class=\"section-card card-problem\">\n    <div class=\"card-label label-problem\">📌 1. PROBLEM STATEMENT</div>\n    <div class=\"card-content\">${escapeHTML(probText)}</div>\n  </div>\n\n  <div class=\"section-card card-solution\">\n    <div class=\"card-label label-solution\">💡 2. EXPECTED SOLUTION &amp; DELIVERABLES</div>\n    <div class=\"card-content\">${escapeHTML(solText)}</div>\n  </div>\n\n  ${tags ? `<div class=\"tags\">Recommended Tech / Tags: ${escapeHTML(tags)}</div>` : ''}\n\n  <div class=\"rules\">\n    <strong>📋 Competition Guidelines &amp; Submission Criteria:</strong><br>\n    • Single Problem Allocation: Each team is granted strictly 1 spin and 1 problem statement.<br>\n    • Version Control: Commit all project code, documentation, and architecture diagrams to your Git repository.<br>\n    • Authenticity: Solution must be conceptualized and coded exclusively during this hackathon event.<br>\n    • Evaluation Metrics: Innovation, problem coverage, engineering quality, usability, and presentation.\n  </div>\n\n  <div class=\"footer\">\n    Official Document • Team: ${escapeHTML(teamName)} (${escapeHTML(teamId)}) • Generated for Hackathon Submission\n  </div>\n\n  <script>\n    window.onload = function() {\n      setTimeout(function() { window.print(); }, 200);\n    };\n  </script>\n</body>\n</html>`;\n      printWin.document.write(html);\n      printWin.document.close();\n      showToast('Print dialog opened. Select \"Save as PDF\" to save! 📄', 'success');\n    } catch (e) {\n      console.error('Error opening print certificate:', e);\n    }\n  }\n\n  function downloadProblemPdf() {\n    if (!teamSession) {\n      showToast('Session expired. Please register your team first.', 'error');\n      return;\n    }\n    const currentProblem = assignedProblem || (teamSession && teamSession.assignedProblem);\n    if (!currentProblem) {\n      showToast('Please spin the wheel first to receive a problem statement!', 'info');\n      return;\n    }\n\n    showToast('Generating official Problem Statement PDF... 📄', 'info');\n\n    const teamIdClean = (teamSession.team?.teamId || 'Team').replace(/[^a-zA-Z0-9_-]/g, '_');\n    const bodyData = {\n      sessionToken: teamSession.sessionToken,\n      teamId: teamSession.team?.teamId,\n      teamName: teamSession.team?.teamName,\n      githubLink: teamSession.team?.githubLink,\n      problem: currentProblem\n    };\n\n    fetch('/api/team/problem-pdf', {\n      method: 'POST',\n      headers: {\n        'Content-Type': 'application/json'\n      },\n      body: JSON.stringify(bodyData)\n    })\n      .then(async res => {\n        if (!res.ok) {\n          const errText = await res.text();\n          throw new Error(errText || 'Server error while generating PDF');\n        }\n        return res.blob();\n      })\n      .then(blob => {\n        if (blob.size < 100) {\n          throw new Error('Downloaded PDF content was empty');\n        }\n        const blobUrl = URL.createObjectURL(blob);\n        const a = document.createElement('a');\n        a.href = blobUrl;\n        a.download = `Problem-Statement-${teamIdClean}.pdf`;\n        document.body.appendChild(a);\n        a.click();\n        a.remove();\n        setTimeout(() => URL.revokeObjectURL(blobUrl), 1000);\n        showToast('PDF downloaded successfully! 📥 Good luck with your project!', 'success');\n      })\n      .catch(err => {\n        console.warn('Direct PDF download hit an issue, launching print certificate fallback:', err.message);\n        printProblemCertificate(teamSession.team, currentProblem);\n      });\n  }\n\n  // ─── EXPLORE MODAL ──────────────────────────────────────────────────────────\n  async function loadExploreProblems() {\n    const search = exploreSearchInput.value.trim();\n    const domain = exploreDomainFilter.value;\n    let url = `/api/problems?domain=${encodeURIComponent(domain)}`;\n    if (search) url += `&search=${encodeURIComponent(search)}`;\n    try {\n      const res = await fetch(url);\n      const data = await res.json();\n      renderExploreTable(data.problems);\n    } catch (err) {\n      exploreProblemsTableBody.innerHTML = `<tr><td colspan=\"4\" style=\"text-align:center;color:#f43f5e;\">Error loading problems</td></tr>`;\n    }\n  }\n\n  function renderExploreTable(problems) {\n    if (problems.length === 0) {\n      exploreProblemsTableBody.innerHTML = `<tr><td colspan=\"4\" style=\"text-align:center;padding:24px;color:#64748b;\">No problem statements found.</td></tr>`;\n      return;\n    }\n    exploreProblemsTableBody.innerHTML = '';\n    problems.forEach(p => {\n      const tr = document.createElement('tr');\n      tr.innerHTML = `\n        <td><span class=\"domain-tag\" style=\"font-size:0.7rem;\">${escapeHTML(p.domain)}</span></td>\n        <td>\n          <strong style=\"color:#ffffff;\">${escapeHTML(p.title)}</strong>\n          <p style=\"font-size:0.75rem;color:#94a3b8;margin-top:4px;max-width:380px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;\">${escapeHTML(p.description)}</p>\n        </td>\n        <td><span class=\"difficulty-tag\" style=\"font-size:0.7rem;\">${p.difficulty || 'Intermediate'}</span></td>\n        <td style=\"font-size:0.75rem;color:#64748b;\">${escapeHTML(p.source || 'Default')}</td>\n      `;\n      exploreProblemsTableBody.appendChild(tr);\n    });\n  }\n\n  // ─── MODALS ─────────────────────────────────────────────────────────────────\n  function openModal(modal) { modal.classList.remove('hidden'); }\n  function closeModal(modal) { modal.classList.add('hidden'); }\n\n  // ─── EVENT LISTENERS ────────────────────────────────────────────────────────\n  function setupEventListeners() {\n    if (teamEntryForm) teamEntryForm.addEventListener('submit', handleTeamRegister);\n    if (logoutBtn) logoutBtn.addEventListener('click', handleLogout);\n    if (teamGithubForm) teamGithubForm.addEventListener('submit', handleSaveGithub);\n    if (editGithubBtn) editGithubBtn.addEventListener('click', handleEditGithub);\n    if (assignedCardGithubActionBtn) assignedCardGithubActionBtn.addEventListener('click', handleEditGithub);\n\n    spinCenterBtn.addEventListener('click', triggerSpin);\n    spinMainBtn.addEventListener('click', triggerSpin);\n    if (wheelCanvas) wheelCanvas.addEventListener('click', triggerSpin);\n\n    window.addEventListener('keydown', e => {\n      if (e.code === 'Space' && !['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName)) {\n        e.preventDefault();\n        triggerSpin();\n      }\n    });\n\n    if (resetCycleBtn) resetCycleBtn.addEventListener('click', () => resetCycle(activeDomain));\n\n    // PDF Download handlers\n    modalDownloadPdfBtn.addEventListener('click', downloadProblemPdf);\n    assignedCardDownloadPdfBtn.addEventListener('click', downloadProblemPdf);\n    teamSidebarDownloadPdfBtn.addEventListener('click', downloadProblemPdf);\n\n    // View full statement from card\n    assignedCardViewBtn.addEventListener('click', () => {\n      if (assignedProblem) openProblemModal(assignedProblem);\n    });\n\n    closeProblemModal.addEventListener('click', () => closeModal(problemModal));\n    if (dismissProblemModalBtn) dismissProblemModalBtn.addEventListener('click', () => closeModal(problemModal));\n\n    copyProblemBtn.addEventListener('click', () => {\n      const parts = extractProblemParts(assignedProblem || (teamSession && teamSession.assignedProblem));\n      const text = `[${parts.domain}] ${parts.title}\\n\\nPROBLEM STATEMENT:\\n${parts.problem}\\n\\nEXPECTED SOLUTION & DELIVERABLES:\\n${parts.expectedSolution}`;\n      navigator.clipboard.writeText(text)\n        .then(() => showToast('Problem statement copied to clipboard! 📋', 'success'))\n        .catch(() => showToast('Could not copy to clipboard', 'error'));\n    });\n\n    viewProblemsBtn.addEventListener('click', () => {\n      openModal(exploreModal);\n      loadExploreProblems();\n    });\n\n    closeExploreModal.addEventListener('click', () => closeModal(exploreModal));\n    exploreSearchInput.addEventListener('input', debounce(loadExploreProblems, 300));\n    exploreDomainFilter.addEventListener('change', loadExploreProblems);\n\n    [problemModal, exploreModal].forEach(modal => {\n      modal.addEventListener('click', e => { if (e.target === modal) closeModal(modal); });\n    });\n  }\n\n  // ─── UTILITIES ──────────────────────────────────────────────────────────────\n  function showToast(message, type = 'info') {\n    const container = document.getElementById('toastContainer');\n    const toast = document.createElement('div');\n    toast.className = `toast toast-${type}`;\n    const icon = type === 'success' ? '✅' : type === 'error' ? '⚠️' : 'ℹ️';\n    toast.innerHTML = `<span>${icon}</span><span>${escapeHTML(message)}</span>`;\n    container.appendChild(toast);\n    setTimeout(() => {\n      toast.style.opacity = '0'; toast.style.transform = 'translateY(10px)';\n      toast.style.transition = 'all 0.3s ease';\n      setTimeout(() => toast.remove(), 300);\n    }, 4000);\n  }\n\n  function escapeHTML(str) {\n    if (!str) return '';\n    return str.replace(/[&<>'\"]/g, tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', \"'\": '&#39;', '\"': '&quot;' }[tag] || tag));\n  }\n\n  function debounce(func, wait) {\n    let timeout;\n    return function (...args) {\n      clearTimeout(timeout);\n      timeout = setTimeout(() => func.apply(this, args), wait);\n    };\n  }\n\n  window.addEventListener('DOMContentLoaded', init);\n})();\n",
  "admin-app.js": "// SpinQuest PS — Admin Dashboard Logic\n(function () {\n  'use strict';\n\n  // ─── STATE ──────────────────────────────────────────────────────────────────\n  let adminToken = localStorage.getItem('spinquest_admin_token') || null;\n  let allTeams = [];\n  let allDomains = [];\n  let allProblems = [];\n  let allDocuments = [];\n  let selectedAdminFile = null;\n  let activeTab = 'tabTeams';\n\n  // ─── DOM REFS ───────────────────────────────────────────────────────────────\n  const loginScreen = document.getElementById('adminLoginScreen');\n  const dashboard = document.getElementById('adminDashboard');\n  const loginForm = document.getElementById('adminLoginForm');\n  const loginError = document.getElementById('adminLoginError');\n  const adminUsername = document.getElementById('adminUsername');\n  const adminPassword = document.getElementById('adminPassword');\n  const toggleAdminPwd = document.getElementById('toggleAdminPwd');\n  const adminWelcomeText = document.getElementById('adminWelcomeText');\n  const adminLogoutBtn = document.getElementById('adminLogoutBtn');\n\n  // Teams & Master Sheet Controls\n  const statTotalTeams = document.getElementById('statTotalTeams');\n  const statTotalAllocated = document.getElementById('statTotalAllocated');\n  const statTotalPending = document.getElementById('statTotalPending');\n  const statActiveDomains = document.getElementById('statActiveDomains');\n  const teamsTableBody = document.getElementById('teamsTableBody');\n  const teamSearchInput = document.getElementById('teamSearchInput');\n  const teamStatusFilter = document.getElementById('teamStatusFilter');\n  const teamDomainFilter = document.getElementById('teamDomainFilter');\n  const exportCsvBtn = document.getElementById('exportCsvBtn');\n  const backupJsonBtn = document.getElementById('backupJsonBtn');\n  const triggerRestoreBtn = document.getElementById('triggerRestoreBtn');\n  const restoreJsonInput = document.getElementById('restoreJsonInput');\n  const refreshTeamsBtn = document.getElementById('refreshTeamsBtn');\n  const downloadPdfBtn = document.getElementById('downloadPdfBtn');\n\n  // Team Details Modal\n  const teamDetailsModal = document.getElementById('teamDetailsModal');\n  const closeTeamModalBtn = document.getElementById('closeTeamModalBtn');\n  const modalDismissBtn = document.getElementById('modalDismissBtn');\n  const modalResetSpinBtn = document.getElementById('modalResetSpinBtn');\n  const modalDownloadPdfBtn = document.getElementById('modalDownloadPdfBtn');\n  const modalTeamId = document.getElementById('modalTeamId');\n  const modalTeamName = document.getElementById('modalTeamName');\n  const modalTeamStatusBadge = document.getElementById('modalTeamStatusBadge');\n  const modalLeader = document.getElementById('modalLeader');\n  const modalPhone = document.getElementById('modalPhone');\n  const modalEmail = document.getElementById('modalEmail');\n  const modalTrack = document.getElementById('modalTrack');\n  const modalCollege = document.getElementById('modalCollege');\n  const modalMembers = document.getElementById('modalMembers');\n  const modalUtr = document.getElementById('modalUtr');\n  const modalGithub = document.getElementById('modalGithub');\n  const modalProblemSection = document.getElementById('modalProblemSection');\n  const modalProblemBox = document.getElementById('modalProblemBox');\n  const modalProblemTitle = document.getElementById('modalProblemTitle');\n  const modalProblemDesc = document.getElementById('modalProblemDesc');\n  const modalProblemText = document.getElementById('modalProblemText');\n  const modalSolutionText = document.getElementById('modalSolutionText');\n  const modalProblemDiff = document.getElementById('modalProblemDiff');\n  const modalProblemDomain = document.getElementById('modalProblemDomain');\n  let selectedModalTeam = null;\n\n  // Domains\n  const newDomainName = document.getElementById('newDomainName');\n  const addDomainBtn = document.getElementById('addDomainBtn');\n  const domainsTableBody = document.getElementById('domainsTableBody');\n\n  // Problems\n  const psSearchInput = document.getElementById('psSearchInput');\n  const psDomainFilter = document.getElementById('psDomainFilter');\n  const psTableBody = document.getElementById('psTableBody');\n  const clearAllPsBtn = document.getElementById('clearAllPsBtn');\n  const showAddPsFormBtn = document.getElementById('showAddPsFormBtn');\n  const addPsFormWrap = document.getElementById('addPsFormWrap');\n  const cancelAddPsBtn = document.getElementById('cancelAddPsBtn');\n  const addPsForm = document.getElementById('addPsForm');\n  const psNewDomain = document.getElementById('psNewDomain');\n  const psNewDifficulty = document.getElementById('psNewDifficulty');\n  const psNewTitle = document.getElementById('psNewTitle');\n  const psNewDesc = document.getElementById('psNewDesc');\n  const psNewTags = document.getElementById('psNewTags');\n\n  // Upload\n  const adminUploadForm = document.getElementById('adminUploadForm');\n  const adminDropZone = document.getElementById('adminDropZone');\n  const adminFileInput = document.getElementById('adminFileInput');\n  const adminSelectedFile = document.getElementById('adminSelectedFile');\n  const adminFileName = document.getElementById('adminFileName');\n  const adminFileSize = document.getElementById('adminFileSize');\n  const adminRemoveFile = document.getElementById('adminRemoveFile');\n  const adminUploadBtn = document.getElementById('adminUploadBtn');\n  const uploadDomainSelect = document.getElementById('uploadDomainSelect');\n  const uploadResultBox = document.getElementById('uploadResultBox');\n  const uploadResultMsg = document.getElementById('uploadResultMsg');\n\n  // Documents\n  const docsTableBody = document.getElementById('docsTableBody');\n  const refreshDocsBtn = document.getElementById('refreshDocsBtn');\n  const resetDataBtn = document.getElementById('resetDataBtn');\n\n  // Tabs\n  const tabBtns = document.querySelectorAll('.admin-tab[data-atab]');\n  const tabContents = document.querySelectorAll('.admin-tab-content');\n\n  // ─── INIT ───────────────────────────────────────────────────────────────────\n  async function init() {\n    setupListeners();\n    if (adminToken) {\n      const valid = await verifyToken();\n      if (valid) {\n        showDashboard();\n        loadTabData(activeTab);\n      } else {\n        localStorage.removeItem('spinquest_admin_token');\n        adminToken = null;\n        showLogin();\n      }\n    } else {\n      showLogin();\n    }\n  }\n\n  async function verifyToken() {\n    try {\n      const res = await fetch('/api/admin/verify', { headers: { 'Authorization': 'Bearer ' + adminToken } });\n      if (!res.ok) return false;\n      const data = await res.json();\n      return Boolean(data.valid);\n    } catch {\n      return false;\n    }\n  }\n\n  function handleAuthFailure(msg = 'Session expired. Please log in as admin.') {\n    localStorage.removeItem('spinquest_admin_token');\n    adminToken = null;\n    showLogin();\n    if (msg) showToast(msg, 'error');\n  }\n\n  // ─── AUTH ───────────────────────────────────────────────────────────────────\n  function showLogin() { loginScreen.classList.remove('hidden'); dashboard.classList.add('hidden'); }\n  function showDashboard() { loginScreen.classList.add('hidden'); dashboard.classList.remove('hidden'); }\n\n  async function handleLogin(e) {\n    if (e && e.preventDefault) e.preventDefault();\n    loginError.classList.add('hidden');\n    loginError.textContent = '';\n    const btn = loginForm.querySelector('button[type=\"submit\"]');\n    const uVal = (adminUsername.value || '').trim();\n    const pVal = (adminPassword.value || '').trim();\n\n    if (!uVal || !pVal) {\n      loginError.textContent = 'Please enter both username and password';\n      loginError.classList.remove('hidden');\n      return;\n    }\n\n    if (btn) {\n      btn.textContent = 'Signing in…';\n      btn.disabled = true;\n    }\n\n    try {\n      const res = await fetch('/api/admin/login', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ username: uVal, password: pVal })\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Login failed. Please check credentials.');\n      adminToken = data.token;\n      localStorage.setItem('spinquest_admin_token', adminToken);\n      if (adminWelcomeText) adminWelcomeText.textContent = `Logged in as ${uVal}`;\n      showDashboard();\n      await loadTabData(activeTab);\n      showToast('Admin access granted ✅', 'success');\n    } catch (err) {\n      console.error('Admin login error:', err);\n      loginError.textContent = err.message || 'Login failed. Please check credentials.';\n      loginError.classList.remove('hidden');\n    } finally {\n      if (btn) {\n        btn.textContent = 'Sign In as Admin';\n        btn.disabled = false;\n      }\n    }\n  }\n\n  function handleLogout() {\n    localStorage.removeItem('spinquest_admin_token');\n    adminToken = null;\n    showLogin();\n    showToast('Logged out successfully.', 'info');\n  }\n\n  // ─── TABS ───────────────────────────────────────────────────────────────────\n  function switchTab(tabId) {\n    activeTab = tabId;\n    tabBtns.forEach(b => b.classList.toggle('active', b.dataset.atab === tabId));\n    tabContents.forEach(c => c.classList.toggle('hidden', c.id !== tabId));\n    loadTabData(tabId);\n  }\n\n  async function loadTabData(tabId) {\n    if (tabId === 'tabTeams') await loadTeams();\n    else if (tabId === 'tabDomains') await loadDomains();\n    else if (tabId === 'tabProblems') await loadProblems();\n    else if (tabId === 'tabDocuments') await loadDocuments();\n    else if (tabId === 'tabUpload') await populateUploadDomainSelect();\n    else if (tabId === 'tabAddTeams') await loadCustomTeams();\n  }\n\n  // ─── TEAMS & MASTER SHEET ───────────────────────────────────────────────────\n  async function loadTeams() {\n    teamsTableBody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"9\">Loading teams...</td></tr>`;\n    try {\n      const res = await fetch('/api/admin/teams', { headers: { 'Authorization': 'Bearer ' + adminToken } });\n      if (res.status === 401) {\n        handleAuthFailure('Admin session expired. Please log in again.');\n        return;\n      }\n      if (!res.ok) throw new Error('Failed to load teams (HTTP ' + res.status + ')');\n      const data = await res.json();\n      allTeams = data.teams || [];\n      renderTeamsStats(data);\n      populateTeamDomainFilter();\n      renderTeamsTable(allTeams);\n      setupPdfDownloadBtn();\n    } catch (err) {\n      console.error('loadTeams error:', err);\n      teamsTableBody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"9\" style=\"color:#f43f5e;\">Error: ${err.message}</td></tr>`;\n    }\n  }\n\n  function renderTeamsStats(data) {\n    const { teams = [], total = 0, allocatedCount = 0, pendingCount = 0 } = data;\n    if (statTotalTeams) statTotalTeams.textContent = total || teams.length;\n    if (statTotalAllocated) statTotalAllocated.textContent = allocatedCount;\n    if (statTotalPending) statTotalPending.textContent = pendingCount;\n    const tracks = [...new Set(teams.map(t => t.domain || t.originalTrack).filter(Boolean))];\n    if (statActiveDomains) statActiveDomains.textContent = tracks.length || 5;\n  }\n\n  function populateTeamDomainFilter() {\n    if (!teamDomainFilter) return;\n    const currentVal = teamDomainFilter.value;\n    const tracks = [...new Set(allTeams.map(t => t.domain || t.originalTrack).filter(Boolean))].sort();\n    teamDomainFilter.innerHTML = '<option value=\"All\">All Tracks</option>';\n    tracks.forEach(tr => {\n      const opt = document.createElement('option');\n      opt.value = tr;\n      opt.textContent = tr;\n      if (tr === currentVal) opt.selected = true;\n      teamDomainFilter.appendChild(opt);\n    });\n  }\n\n  function renderTeamsTable(teams) {\n    const search = (teamSearchInput?.value || '').trim().toLowerCase();\n    const statusVal = teamStatusFilter ? teamStatusFilter.value : 'All';\n    const domainVal = teamDomainFilter ? teamDomainFilter.value : 'All';\n\n    const filtered = teams.filter(team => {\n      // 1. Status filter\n      const hasSpun = Boolean(team.spins && team.spins.length > 0);\n      if (statusVal === 'Allocated' && !hasSpun) return false;\n      if (statusVal === 'Pending' && hasSpun) return false;\n\n      // 2. Domain / Track filter\n      const track = team.domain || team.originalTrack || '';\n      if (domainVal !== 'All' && track.toLowerCase() !== domainVal.toLowerCase()) return false;\n\n      // 3. Search filter across all details\n      if (search) {\n        const textToSearch = [\n          team.teamId,\n          team.regId,\n          team.teamName,\n          team.leader,\n          team.college,\n          team.members,\n          team.phone,\n          team.email,\n          track,\n          hasSpun ? (team.spins[0].title || team.spins[0].problemTitle) : ''\n        ].filter(Boolean).join(' ').toLowerCase();\n\n        if (!textToSearch.includes(search)) return false;\n      }\n\n      return true;\n    });\n\n    if (filtered.length === 0) {\n      teamsTableBody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"9\">No matching teams found.</td></tr>`;\n      return;\n    }\n\n    teamsTableBody.innerHTML = '';\n    filtered.forEach((team, idx) => {\n      const tr = document.createElement('tr');\n      const hasSpun = team.spins && team.spins.length > 0;\n      const spin = hasSpun ? team.spins[0] : null;\n\n      // Leader & Contact\n      const leaderHtml = `\n        <div style=\"font-weight:600;color:#ffffff;font-size:0.83rem;\">${escHTML(team.leader || '—')}</div>\n        ${team.phone ? `<div style=\"font-size:0.75rem;color:#38bdf8;margin-top:2px;\">📞 ${escHTML(team.phone)}</div>` : ''}\n        ${team.email ? `<div style=\"font-size:0.7rem;color:var(--text-muted);\">${escHTML(team.email)}</div>` : ''}\n      `;\n\n      // College\n      const collegeHtml = `<div style=\"font-size:0.78rem;color:#cbd5e1;line-height:1.35;max-width:210px;\">${escHTML(team.college || '—')}</div>`;\n\n      // Track / Domain\n      const trackName = team.domain || team.originalTrack || 'General';\n      const domainHtml = `<span class=\"domain-tag\" style=\"font-size:0.72rem;padding:3px 8px;white-space:nowrap;\">${escHTML(trackName)}</span>`;\n\n      // Allocated Problem Statement\n      let problemHtml = `<span style=\"color:#f59e0b;font-size:0.78rem;font-style:italic;\">⏳ Waiting for spin draw</span>`;\n      let statusHtml = `<span style=\"color:#f59e0b;font-weight:700;font-size:0.78rem;\">⏳ Pending</span>`;\n\n      if (spin) {\n        const title = spin.title || spin.problemTitle || 'Assigned Problem';\n        const desc = spin.description || spin.problemDescription || '';\n        const diff = spin.difficulty || spin.problemDifficulty || 'Intermediate';\n\n        problemHtml = `\n          <div style=\"max-width: 320px;\">\n            <strong style=\"color:#ffffff; font-size:0.84rem; display:block; margin-bottom:3px; line-height:1.3;\">\n              ${escHTML(title)}\n            </strong>\n            <p style=\"font-size:0.74rem; color:#94a3b8; line-height:1.35; margin:0 0 4px; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden;\">\n              ${escHTML(desc)}\n            </p>\n            <span class=\"difficulty-tag\" style=\"font-size:0.65rem; padding:1px 6px;\">\n              ${escHTML(diff)}\n            </span>\n          </div>\n        `;\n\n        const timeStr = spin.spunAt ? new Date(spin.spunAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '';\n        statusHtml = `\n          <span style=\"display:inline-flex; align-items:center; gap:4px; color:#34d399; font-weight:700; font-size:0.78rem;\">\n            🟢 Allocated\n          </span>\n          <div style=\"font-size:0.7rem; color:var(--text-muted); margin-top:2px;\">${timeStr}</div>\n        `;\n      }\n\n      // Actions\n      const actionsHtml = `\n        <div style=\"display:flex;gap:6px;align-items:center;\">\n          <button class=\"btn btn-secondary btn-sm view-team-details\" data-tid=\"${escHTML(team.teamId)}\" style=\"padding:4px 9px;font-size:0.74rem;\" title=\"View all team details\">\n            👁️ Details\n          </button>\n          ${hasSpun \n            ? `<button class=\"btn btn-accent btn-sm download-single-team-pdf\" data-tid=\"${escHTML(team.teamId)}\" style=\"padding:4px 9px;font-size:0.74rem;\" title=\"Download PDF assignment\">\n                📄 PDF\n               </button>`\n            : `<button class=\"btn btn-outline btn-sm\" disabled style=\"padding:4px 9px;font-size:0.74rem;opacity:0.35;\" title=\"Team has not spun yet\">\n                📄 PDF\n               </button>`\n          }\n        </div>\n      `;\n\n      tr.innerHTML = `\n        <td style=\"color:var(--text-muted);font-size:0.78rem;\">${idx + 1}</td>\n        <td><code style=\"font-size:0.8rem;color:#38bdf8;font-weight:700;\">${escHTML(team.teamId)}</code></td>\n        <td style=\"font-weight:700;font-size:0.85rem;color:#ffffff;\">${escHTML(team.teamName)}</td>\n        <td>${leaderHtml}</td>\n        <td>${collegeHtml}</td>\n        <td>${domainHtml}</td>\n        <td>${problemHtml}</td>\n        <td>${statusHtml}</td>\n        <td>${actionsHtml}</td>\n      `;\n      teamsTableBody.appendChild(tr);\n    });\n\n    // Wire Details buttons\n    teamsTableBody.querySelectorAll('.view-team-details').forEach(btn => {\n      btn.addEventListener('click', () => {\n        const tid = btn.dataset.tid;\n        const team = allTeams.find(t => t.teamId.toLowerCase() === tid.toLowerCase());\n        if (team) openTeamDetailsModal(team);\n      });\n    });\n\n    // Wire individual team PDF download buttons\n    teamsTableBody.querySelectorAll('.download-single-team-pdf').forEach(btn => {\n      btn.addEventListener('click', () => {\n        const tid = btn.dataset.tid;\n        downloadIndividualTeamPdf(tid);\n      });\n    });\n  }\n\n  // Helper: Extract structured problem details (Title | Problem | Expected Solution)\n  function extractProblemParts(problem) {\n    if (!problem) return { title: 'Assigned Problem Statement', problem: '', expectedSolution: '', tags: [] };\n    const title = problem.title || problem.problemTitle || 'Assigned Problem Statement';\n    let probText = problem.problem || problem.problemText || '';\n    let solText = problem.expectedSolution || problem.solution || '';\n\n    if (!probText || !solText) {\n      const rawDesc = problem.description || problem.problemDescription || '';\n      const probIdx = rawDesc.search(/(?:^|\\n)\\s*Problem\\s*:\\s*/i);\n      const solIdx = rawDesc.search(/(?:^|\\n)\\s*Expected\\s+Solution\\s*:\\s*/i);\n\n      if (probIdx !== -1 && solIdx !== -1 && solIdx > probIdx) {\n        const afterProb = rawDesc.substring(probIdx).replace(/^(?:^|\\n)\\s*Problem\\s*:\\s*/i, '');\n        const nextSol = afterProb.search(/(?:^|\\n)\\s*Expected\\s+Solution\\s*:\\s*/i);\n        if (nextSol !== -1) {\n          probText = afterProb.substring(0, nextSol).trim();\n          solText = afterProb.substring(nextSol).replace(/^(?:^|\\n)\\s*Expected\\s+Solution\\s*:\\s*/i, '').trim();\n        }\n      } else if (solIdx !== -1) {\n        probText = rawDesc.substring(0, solIdx).trim();\n        solText = rawDesc.substring(solIdx).replace(/^(?:^|\\n)\\s*Expected\\s+Solution\\s*:\\s*/i, '').trim();\n      } else {\n        probText = rawDesc.trim();\n        solText = 'Design and implement a complete, production-grade software solution addressing the core challenges, with clean architecture and deployment artifacts.';\n      }\n    }\n\n    return {\n      title,\n      problem: probText,\n      expectedSolution: solText,\n      domain: problem.domain || '',\n      difficulty: problem.difficulty || problem.problemDifficulty || 'Intermediate',\n      tags: problem.tags || []\n    };\n  }\n\n  // ─── TEAM DETAILS MODAL ─────────────────────────────────────────────────────\n  function openTeamDetailsModal(team) {\n    selectedModalTeam = team;\n    modalTeamId.textContent = team.teamId || team.regId;\n    modalTeamName.textContent = team.teamName;\n\n    const hasSpun = team.spins && team.spins.length > 0;\n    modalTeamStatusBadge.textContent = hasSpun ? '🟢 Allocated' : '⏳ Pending Draw';\n    modalTeamStatusBadge.style.color = hasSpun ? '#34d399' : '#f59e0b';\n\n    modalLeader.textContent = team.leader || 'Not specified';\n    modalPhone.textContent = team.phone || 'Not specified';\n    modalEmail.textContent = team.email || 'Not specified';\n    modalTrack.textContent = team.domain || team.originalTrack || 'General';\n    modalCollege.textContent = team.college || 'Not specified';\n    modalMembers.textContent = team.members || 'Not specified';\n    modalUtr.textContent = team.utr || 'Not recorded';\n\n    if (team.githubLink) {\n      modalGithub.innerHTML = `<a href=\"${escHTML(team.githubLink)}\" target=\"_blank\" rel=\"noopener\" style=\"color:#38bdf8;\">${escHTML(team.githubLink)}</a>`;\n    } else {\n      modalGithub.textContent = 'Not provided';\n    }\n\n    if (hasSpun) {\n      const spin = team.spins[0];\n      const parts = extractProblemParts(spin);\n      modalProblemTitle.textContent = parts.title;\n      if (modalProblemText) modalProblemText.textContent = parts.problem;\n      if (modalSolutionText) modalSolutionText.textContent = parts.expectedSolution;\n      if (modalProblemDesc) modalProblemDesc.textContent = parts.problem;\n      modalProblemDiff.textContent = parts.difficulty;\n      modalProblemDomain.textContent = spin.domain || team.domain || 'Challenge';\n      modalProblemSection.style.display = 'block';\n      modalDownloadPdfBtn.style.display = 'inline-block';\n      modalResetSpinBtn.style.display = 'inline-block';\n    } else {\n      modalProblemSection.style.display = 'none';\n      modalDownloadPdfBtn.style.display = 'none';\n      modalResetSpinBtn.style.display = 'none';\n    }\n\n    teamDetailsModal.classList.remove('hidden');\n  }\n\n  function closeTeamDetailsModal() {\n    teamDetailsModal.classList.add('hidden');\n    selectedModalTeam = null;\n  }\n\n  async function handleResetSpin() {\n    if (!selectedModalTeam) return;\n    if (!confirm(`Are you sure you want to reset the spin for \"${selectedModalTeam.teamName}\"? They will be allowed to spin the wheel again.`)) return;\n\n    try {\n      const res = await fetch('/api/admin/teams/reset-spin', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + adminToken },\n        body: JSON.stringify({ teamId: selectedModalTeam.teamId })\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Failed to reset spin');\n      showToast(data.message || 'Spin reset successfully!', 'success');\n      closeTeamDetailsModal();\n      loadTeams();\n    } catch (err) {\n      showToast(err.message, 'error');\n    }\n  }\n\n  // ─── EXPORT CSV & BACKUP/RESTORE ────────────────────────────────────────────\n  function exportTeamsCsv() {\n    if (allTeams.length === 0) {\n      showToast('No teams to export', 'error');\n      return;\n    }\n    const headers = [\n      '#', 'Reg ID', 'Team Name', 'Leader', 'Phone', 'Email',\n      'College', 'Members', 'Original Track', 'Assigned Domain',\n      'Status', 'Problem Title', 'Problem Description', 'Difficulty',\n      'Allocated At', 'GitHub Link', 'UTR Ref'\n    ];\n\n    const escapeCsv = (str) => {\n      if (str === null || str === undefined) return '\"\"';\n      const s = String(str).replace(/\"/g, '\"\"');\n      return `\"${s}\"`;\n    };\n\n    const rows = allTeams.map((team, idx) => {\n      const hasSpun = team.spins && team.spins.length > 0;\n      const spin = hasSpun ? team.spins[0] : null;\n      return [\n        idx + 1,\n        team.teamId || team.regId,\n        team.teamName,\n        team.leader || '',\n        team.phone || '',\n        team.email || '',\n        team.college || '',\n        team.members || '',\n        team.originalTrack || '',\n        team.domain || '',\n        hasSpun ? 'Allocated' : 'Pending',\n        spin ? (spin.title || spin.problemTitle || '') : '',\n        spin ? (spin.description || spin.problemDescription || '') : '',\n        spin ? (spin.difficulty || spin.problemDifficulty || '') : '',\n        spin && spin.spunAt ? new Date(spin.spunAt).toLocaleString() : '',\n        team.githubLink || '',\n        team.utr || ''\n      ].map(escapeCsv).join(',');\n    });\n\n    const csvContent = '\\uFEFF' + [headers.map(escapeCsv).join(','), ...rows].join('\\r\\n');\n    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });\n    const url = URL.createObjectURL(blob);\n    const link = document.createElement('a');\n    link.href = url;\n    link.download = 'CODIENYCH-1.0-Master-Allocation-Sheet.csv';\n    document.body.appendChild(link);\n    link.click();\n    link.remove();\n    URL.revokeObjectURL(url);\n    showToast('Exported CSV spreadsheet! 📥', 'success');\n  }\n\n  function backupJsonData() {\n    const backupObj = {\n      exportedAt: new Date().toISOString(),\n      teams: allTeams,\n      problems: allProblems,\n      domains: allDomains\n    };\n    const blob = new Blob([JSON.stringify(backupObj, null, 2)], { type: 'application/json' });\n    const url = URL.createObjectURL(blob);\n    const link = document.createElement('a');\n    link.href = url;\n    link.download = `codienych-database-backup-${Date.now()}.json`;\n    document.body.appendChild(link);\n    link.click();\n    link.remove();\n    URL.revokeObjectURL(url);\n    showToast('Database JSON backup downloaded! 💾', 'success');\n  }\n\n  async function handleRestoreJsonFile(e) {\n    const file = e.target.files[0];\n    if (!file) return;\n    try {\n      const text = await file.text();\n      const parsed = JSON.parse(text);\n      if (!parsed.teams || !Array.isArray(parsed.teams)) {\n        throw new Error('Invalid backup file. Missing teams array.');\n      }\n      if (!confirm(`Restore ${parsed.teams.length} teams from backup \"${file.name}\"?`)) {\n        restoreJsonInput.value = '';\n        return;\n      }\n      const res = await fetch('/api/admin/backup/restore', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + adminToken },\n        body: JSON.stringify({ backupData: parsed })\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Restore failed');\n      showToast(data.message || 'Database restored successfully!', 'success');\n      loadTeams();\n    } catch (err) {\n      showToast('Restore error: ' + err.message, 'error');\n    } finally {\n      restoreJsonInput.value = '';\n    }\n  }\n\n  function downloadIndividualTeamPdf(teamId) {\n    showToast(`Downloading PDF for Team ${teamId}... 📄`, 'info');\n    fetch(`/api/team/problem-pdf?teamId=${encodeURIComponent(teamId)}`)\n      .then(res => {\n        if (!res.ok) throw new Error('Failed to generate PDF for this team');\n        return res.blob();\n      })\n      .then(blob => {\n        const url = URL.createObjectURL(blob);\n        const link = document.createElement('a');\n        link.href = url;\n        link.download = `Problem-Statement-${teamId}.pdf`;\n        document.body.appendChild(link);\n        link.click();\n        link.remove();\n        URL.revokeObjectURL(url);\n        showToast(`Team ${teamId} PDF downloaded! 📥`, 'success');\n      })\n      .catch(err => showToast(err.message, 'error'));\n  }\n\n  function setupPdfDownloadBtn() {\n    const token = adminToken;\n    downloadPdfBtn.href = '#';\n    downloadPdfBtn.onclick = (e) => {\n      e.preventDefault();\n      showToast('Generating Master Event Report PDF... 📄', 'info');\n      fetch('/api/admin/teams/pdf', { headers: { 'Authorization': 'Bearer ' + token } })\n        .then(r => {\n          if (!r.ok) throw new Error('PDF generation failed');\n          return r.blob();\n        })\n        .then(blob => {\n          const url = URL.createObjectURL(blob);\n          const link = document.createElement('a');\n          link.href = url;\n          link.download = 'CODIENYCH-1.0-Teams-Report.pdf';\n          document.body.appendChild(link);\n          link.click();\n          link.remove();\n          URL.revokeObjectURL(url);\n          showToast('Master event report PDF downloaded! 📥', 'success');\n        })\n        .catch(err => showToast('PDF error: ' + err.message, 'error'));\n    };\n  }\n\n  // ─── DOMAINS ────────────────────────────────────────────────────────────────\n  async function loadDomains() {\n    try {\n      const res = await fetch('/api/domains');\n      const data = await res.json();\n      allDomains = data.domains;\n      renderDomainsTable();\n      populateDomainSelects();\n    } catch (err) {\n      domainsTableBody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"3\" style=\"color:#f43f5e;\">Error: ${err.message}</td></tr>`;\n    }\n  }\n\n  function renderDomainsTable() {\n    if (allDomains.length === 0) {\n      domainsTableBody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"3\">No domains found.</td></tr>`;\n      return;\n    }\n    domainsTableBody.innerHTML = '';\n    allDomains.forEach(d => {\n      const tr = document.createElement('tr');\n      tr.innerHTML = `\n        <td style=\"font-weight:600;\">${escHTML(d.name)}</td>\n        <td>${d.count} PS</td>\n        <td><button class=\"expand-btn delete-domain-btn\" data-dname=\"${escHTML(d.name)}\">🗑️ Delete</button></td>\n      `;\n      domainsTableBody.appendChild(tr);\n    });\n    domainsTableBody.querySelectorAll('.delete-domain-btn').forEach(btn => {\n      btn.addEventListener('click', () => {\n        if (confirm(`Delete domain \"${btn.dataset.dname}\"? This will also delete all its problem statements.`)) {\n          deleteDomain(btn.dataset.dname);\n        }\n      });\n    });\n  }\n\n  async function addDomain() {\n    const name = newDomainName.value.trim();\n    if (!name) { showToast('Enter a domain name', 'error'); return; }\n    try {\n      const res = await fetch('/api/domains', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + adminToken },\n        body: JSON.stringify({ name })\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Failed to add domain');\n      newDomainName.value = '';\n      showToast(`Domain \"${name}\" added!`, 'success');\n      loadDomains();\n    } catch (err) { showToast(err.message, 'error'); }\n  }\n\n  async function deleteDomain(name) {\n    try {\n      const res = await fetch(`/api/domains/${encodeURIComponent(name)}`, {\n        method: 'DELETE',\n        headers: { 'Authorization': 'Bearer ' + adminToken }\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Failed to delete domain');\n      showToast(`Domain \"${name}\" removed.`, 'success');\n      loadDomains();\n    } catch (err) { showToast(err.message, 'error'); }\n  }\n\n  // ─── PROBLEMS ───────────────────────────────────────────────────────────────\n  async function loadProblems() {\n    const search = psSearchInput ? psSearchInput.value.trim() : '';\n    const domain = psDomainFilter ? psDomainFilter.value : 'All';\n    let url = `/api/problems?domain=${encodeURIComponent(domain)}`;\n    if (search) url += `&search=${encodeURIComponent(search)}`;\n    try {\n      const res = await fetch(url);\n      const data = await res.json();\n      allProblems = data.problems;\n      renderProblemsTable();\n      if (psDomainFilter && psDomainFilter.options.length <= 1) populatePsDomainFilter();\n    } catch (err) {\n      psTableBody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"5\" style=\"color:#f43f5e;\">Error: ${err.message}</td></tr>`;\n    }\n  }\n\n  function renderProblemsTable() {\n    if (allProblems.length === 0) {\n      psTableBody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"5\">No problem statements found.</td></tr>`;\n      return;\n    }\n    psTableBody.innerHTML = '';\n    allProblems.forEach(p => {\n      const tr = document.createElement('tr');\n      tr.innerHTML = `\n        <td><span class=\"domain-tag\" style=\"font-size:0.7rem;\">${escHTML(p.domain)}</span></td>\n        <td>\n          <strong style=\"font-size:0.85rem;\">${escHTML(p.title)}</strong>\n          <p style=\"font-size:0.75rem;color:#94a3b8;margin-top:3px;max-width:380px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;\">${escHTML(p.description)}</p>\n        </td>\n        <td><span class=\"difficulty-tag\" style=\"font-size:0.7rem;\">${escHTML(p.difficulty || 'Intermediate')}</span></td>\n        <td style=\"font-size:0.75rem;color:#64748b;\">${escHTML(p.source || 'Default')}</td>\n        <td><button class=\"expand-btn delete-ps-btn\" data-pid=\"${escHTML(p.id)}\">🗑️ Delete</button></td>\n      `;\n      psTableBody.appendChild(tr);\n    });\n    psTableBody.querySelectorAll('.delete-ps-btn').forEach(btn => {\n      btn.addEventListener('click', () => {\n        if (confirm('Delete this problem statement?')) deleteProblem(btn.dataset.pid);\n      });\n    });\n  }\n\n  async function deleteProblem(id) {\n    try {\n      const res = await fetch(`/api/problems/${id}`, {\n        method: 'DELETE', headers: { 'Authorization': 'Bearer ' + adminToken }\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Failed to delete');\n      showToast('Problem statement deleted.', 'success');\n      loadProblems();\n    } catch (err) { showToast(err.message, 'error'); }\n  }\n\n  async function addProblemManually(e) {\n    e.preventDefault();\n    const payload = {\n      domain: psNewDomain.value, difficulty: psNewDifficulty.value,\n      title: psNewTitle.value.trim(), description: psNewDesc.value.trim(),\n      tags: psNewTags.value.split(',').map(t => t.trim()).filter(Boolean)\n    };\n    try {\n      const res = await fetch('/api/problems', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + adminToken },\n        body: JSON.stringify(payload)\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Failed to add');\n      showToast('Problem statement added!', 'success');\n      addPsFormWrap.classList.add('hidden');\n      addPsForm.reset();\n      loadProblems();\n    } catch (err) { showToast(err.message, 'error'); }\n  }\n\n  function populatePsDomainFilter() {\n    const domainsForFilter = [...new Set(allProblems.map(p => p.domain))];\n    psDomainFilter.innerHTML = '<option value=\"All\">All Domains</option>';\n    domainsForFilter.forEach(d => {\n      const o = document.createElement('option'); o.value = d; o.textContent = d;\n      psDomainFilter.appendChild(o);\n    });\n  }\n\n  // ─── DOCUMENTS ──────────────────────────────────────────────────────────────\n  async function loadDocuments() {\n    try {\n      const res = await fetch('/api/documents', { headers: { 'Authorization': 'Bearer ' + adminToken } });\n      if (res.status === 401 || res.status === 403) return handleAuthFailure('Session expired. Please log in.');\n      const data = await res.json();\n      allDocuments = data.documents || [];\n      renderDocumentsTable();\n    } catch (err) {\n      docsTableBody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"5\" style=\"color:#f43f5e;\">Error: ${err.message}</td></tr>`;\n    }\n  }\n\n  function renderDocumentsTable() {\n    if (allDocuments.length === 0) {\n      docsTableBody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"5\">No documents uploaded yet.</td></tr>`;\n      return;\n    }\n    docsTableBody.innerHTML = '';\n    allDocuments.forEach(doc => {\n      const tr = document.createElement('tr');\n      tr.innerHTML = `\n        <td style=\"font-size:0.85rem;\">📄 ${escHTML(doc.filename)}</td>\n        <td><span class=\"domain-tag\" style=\"font-size:0.7rem;\">${escHTML(doc.domain)}</span></td>\n        <td style=\"font-size:0.85rem;\">${doc.extractedCount || doc.problemCount || '—'}</td>\n        <td style=\"font-size:0.78rem;color:var(--text-muted);\">${new Date(doc.uploadedAt).toLocaleString()}</td>\n        <td><button class=\"expand-btn delete-doc-btn\" data-did=\"${escHTML(doc.id)}\">🗑️ Delete</button></td>\n      `;\n      docsTableBody.appendChild(tr);\n    });\n    docsTableBody.querySelectorAll('.delete-doc-btn').forEach(btn => {\n      btn.addEventListener('click', () => {\n        if (confirm('Delete this document and all its extracted problems?')) deleteDocument(btn.dataset.did);\n      });\n    });\n  }\n\n  async function deleteDocument(id) {\n    try {\n      const res = await fetch(`/api/documents/${id}`, {\n        method: 'DELETE', headers: { 'Authorization': 'Bearer ' + adminToken }\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Failed to delete');\n      showToast('Document deleted.', 'success');\n      loadDocuments();\n    } catch (err) { showToast(err.message, 'error'); }\n  }\n\n  async function resetSampleData() {\n    if (!confirm('This will replace ALL current problems with the default sample dataset. Continue?')) return;\n    try {\n      const res = await fetch('/api/reset-data', {\n        method: 'POST', headers: { 'Authorization': 'Bearer ' + adminToken }\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Failed to reset');\n      showToast(`Default data restored! ${data.totalProblems} problems loaded.`, 'success');\n      loadDocuments();\n    } catch (err) { showToast(err.message, 'error'); }\n  }\n\n  // ─── UPLOAD ─────────────────────────────────────────────────────────────────\n  async function populateUploadDomainSelect() {\n    try {\n      const res = await fetch('/api/domains');\n      const data = await res.json();\n      uploadDomainSelect.innerHTML = '<option value=\"\">— Select Domain —</option>';\n      psNewDomain.innerHTML = '';\n      data.domains.forEach(d => {\n        const o1 = document.createElement('option'); o1.value = d.name; o1.textContent = d.name;\n        uploadDomainSelect.appendChild(o1);\n        const o2 = document.createElement('option'); o2.value = d.name; o2.textContent = d.name;\n        psNewDomain.appendChild(o2);\n      });\n    } catch (err) { /* non-critical */ }\n  }\n\n  async function handleUpload(e) {\n    e.preventDefault();\n    if (!selectedAdminFile) { showToast('Select a file first', 'error'); return; }\n    const domain = uploadDomainSelect.value;\n    if (!domain) { showToast('Select a target domain', 'error'); return; }\n    const formData = new FormData();\n    formData.append('file', selectedAdminFile);\n    formData.append('domain', domain);\n    adminUploadBtn.textContent = 'Uploading…'; adminUploadBtn.disabled = true;\n    uploadResultBox.classList.add('hidden');\n    try {\n      const res = await fetch('/api/upload', {\n        method: 'POST',\n        headers: { 'Authorization': 'Bearer ' + adminToken },\n        body: formData\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Upload failed');\n      uploadResultMsg.textContent = `Extracted ${data.extractedCount || '?'} problem statements from \"${selectedAdminFile.name}\" for domain \"${domain}\".`;\n      uploadResultBox.classList.remove('hidden');\n      clearFileSelection();\n      showToast('Upload successful! 🎉', 'success');\n      loadProblems();\n      loadDomains();\n      loadDocuments();\n    } catch (err) { showToast('Upload error: ' + err.message, 'error'); }\n    finally {\n      adminUploadBtn.textContent = 'Extract & Add Problem Statements';\n      adminUploadBtn.disabled = !selectedAdminFile;\n    }\n  }\n\n  function handleFileSelect(file) {\n    if (!file) return;\n    selectedAdminFile = file;\n    adminFileName.textContent = file.name;\n    adminFileSize.textContent = (file.size / 1024).toFixed(1) + ' KB';\n    adminSelectedFile.classList.remove('hidden');\n    adminDropZone.style.display = 'none';\n    adminUploadBtn.disabled = false;\n  }\n\n  function clearFileSelection() {\n    selectedAdminFile = null;\n    adminFileInput.value = '';\n    adminSelectedFile.classList.add('hidden');\n    adminDropZone.style.display = '';\n    adminUploadBtn.disabled = true;\n  }\n\n  // ─── DOMAIN SELECTS HELPERS ─────────────────────────────────────────────────\n  function populateDomainSelects() {\n    populateUploadDomainSelect();\n  }\n\n  // ─── EVENT LISTENERS ────────────────────────────────────────────────────────\n  function setupListeners() {\n    loginForm.addEventListener('submit', handleLogin);\n    adminLogoutBtn.addEventListener('click', handleLogout);\n    toggleAdminPwd.addEventListener('click', () => {\n      const isPass = adminPassword.type === 'password';\n      adminPassword.type = isPass ? 'text' : 'password';\n      toggleAdminPwd.textContent = isPass ? '🙈' : '👁️';\n    });\n\n    // Tabs\n    tabBtns.forEach(btn => btn.addEventListener('click', () => switchTab(btn.dataset.atab)));\n\n    // Teams & Master Sheet\n    refreshTeamsBtn.addEventListener('click', loadTeams);\n    teamSearchInput.addEventListener('input', debounce(() => renderTeamsTable(allTeams), 300));\n    if (teamStatusFilter) teamStatusFilter.addEventListener('change', () => renderTeamsTable(allTeams));\n    if (teamDomainFilter) teamDomainFilter.addEventListener('change', () => renderTeamsTable(allTeams));\n    if (exportCsvBtn) exportCsvBtn.addEventListener('click', exportTeamsCsv);\n    if (backupJsonBtn) backupJsonBtn.addEventListener('click', backupJsonData);\n    if (triggerRestoreBtn && restoreJsonInput) {\n      triggerRestoreBtn.addEventListener('click', () => restoreJsonInput.click());\n      restoreJsonInput.addEventListener('change', handleRestoreJsonFile);\n    }\n\n    // Modal controls\n    if (closeTeamModalBtn) closeTeamModalBtn.addEventListener('click', closeTeamDetailsModal);\n    if (modalDismissBtn) modalDismissBtn.addEventListener('click', closeTeamDetailsModal);\n    if (modalResetSpinBtn) modalResetSpinBtn.addEventListener('click', handleResetSpin);\n    if (modalDownloadPdfBtn) modalDownloadPdfBtn.addEventListener('click', () => {\n      if (selectedModalTeam) downloadIndividualTeamPdf(selectedModalTeam.teamId);\n    });\n    // Close modal when clicking the backdrop outside the modal card\n    if (teamDetailsModal) {\n      teamDetailsModal.addEventListener('click', (e) => {\n        if (e.target === teamDetailsModal) closeTeamDetailsModal();\n      });\n    }\n\n    // Domains\n    addDomainBtn.addEventListener('click', addDomain);\n    newDomainName.addEventListener('keydown', e => { if (e.key === 'Enter') addDomain(); });\n\n    // Problems\n    if (clearAllPsBtn) {\n      clearAllPsBtn.addEventListener('click', async () => {\n        if (!confirm('⚠️ Are you sure you want to permanently delete ALL problem statements and documents? This will completely empty the problem statement repository.')) {\n          return;\n        }\n        try {\n          const res = await fetch('/api/admin/clear-all-problems', {\n            method: 'POST',\n            headers: { 'Authorization': 'Bearer ' + adminToken }\n          });\n          const data = await res.json();\n          if (res.ok && data.success) {\n            showToast('All problem statements have been deleted successfully. The repository is now fresh and empty.', 'success');\n            loadProblems();\n            loadDomains();\n            loadDocuments();\n          } else {\n            showToast(data.error || 'Failed to clear problem statements', 'error');\n          }\n        } catch (err) {\n          showToast('Error: ' + err.message, 'error');\n        }\n      });\n    }\n    showAddPsFormBtn.addEventListener('click', () => {\n      addPsFormWrap.classList.toggle('hidden');\n      populateUploadDomainSelect();\n    });\n    cancelAddPsBtn.addEventListener('click', () => addPsFormWrap.classList.add('hidden'));\n    addPsForm.addEventListener('submit', addProblemManually);\n    if (psSearchInput) psSearchInput.addEventListener('input', debounce(loadProblems, 300));\n    if (psDomainFilter) psDomainFilter.addEventListener('change', loadProblems);\n\n    // Upload\n    adminDropZone.addEventListener('click', () => adminFileInput.click());\n    adminFileInput.addEventListener('change', e => handleFileSelect(e.target.files[0]));\n    adminRemoveFile.addEventListener('click', clearFileSelection);\n    adminDropZone.addEventListener('dragover', e => { e.preventDefault(); adminDropZone.classList.add('drag-over'); });\n    adminDropZone.addEventListener('dragleave', () => adminDropZone.classList.remove('drag-over'));\n    adminDropZone.addEventListener('drop', e => {\n      e.preventDefault(); adminDropZone.classList.remove('drag-over');\n      handleFileSelect(e.dataTransfer.files[0]);\n    });\n    adminDropZone.querySelectorAll('.browse-link').forEach(l => l.addEventListener('click', e => {\n      e.stopPropagation(); adminFileInput.click();\n    }));\n    adminUploadForm.addEventListener('submit', handleUpload);\n\n    // Documents\n    refreshDocsBtn.addEventListener('click', loadDocuments);\n    resetDataBtn.addEventListener('click', resetSampleData);\n\n    // Add Teams tab\n    const addTeamForm = document.getElementById('addTeamForm');\n    const refreshCustomTeamsBtn = document.getElementById('refreshCustomTeamsBtn');\n    if (addTeamForm) addTeamForm.addEventListener('submit', handleAddTeam);\n    if (refreshCustomTeamsBtn) refreshCustomTeamsBtn.addEventListener('click', loadCustomTeams);\n  }\n\n  // ─── UTILITIES ──────────────────────────────────────────────────────────────\n  function showToast(message, type = 'info') {\n    const container = document.getElementById('toastContainer');\n    const toast = document.createElement('div');\n    toast.className = `toast toast-${type}`;\n    const icon = type === 'success' ? '✅' : type === 'error' ? '⚠️' : 'ℹ️';\n    toast.innerHTML = `<span>${icon}</span><span>${escHTML(message)}</span>`;\n    container.appendChild(toast);\n    setTimeout(() => {\n      toast.style.opacity = '0'; toast.style.transform = 'translateY(10px)';\n      toast.style.transition = 'all 0.3s ease';\n      setTimeout(() => toast.remove(), 300);\n    }, 4000);\n  }\n\n  function escHTML(str) {\n    if (!str) return '';\n    return String(str).replace(/[&<>'\"]/g, tag => ({\n      '&': '&amp;', '<': '&lt;', '>': '&gt;', \"'\": '&#39;', '\"': '&quot;'\n    }[tag] || tag));\n  }\n\n  function debounce(func, wait) {\n    let timeout;\n    return function (...args) {\n      clearTimeout(timeout);\n      timeout = setTimeout(() => func.apply(this, args), wait);\n    };\n  }\n\n  if (document.readyState === 'loading') {\n    window.addEventListener('DOMContentLoaded', init);\n  } else {\n    init();\n  }\n\n  // ─── ADD TEAMS TAB ──────────────────────────────────────────────────────────\n\n  async function loadCustomTeams() {\n    const tbody = document.getElementById('customTeamsTableBody');\n    const countEl = document.getElementById('customTeamsCount');\n    if (!tbody) return;\n    tbody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"4\">Loading...</td></tr>`;\n    try {\n      const res = await fetch('/api/admin/teams/custom', {\n        headers: { 'Authorization': 'Bearer ' + adminToken }\n      });\n      if (!res.ok) throw new Error('Failed to fetch custom teams');\n      const data = await res.json();\n      renderCustomTeams(data.customTeams || []);\n      if (countEl) {\n        countEl.textContent = data.total === 0\n          ? 'No custom teams added yet.'\n          : `${data.total} custom team${data.total !== 1 ? 's' : ''} added by admin`;\n      }\n    } catch (err) {\n      tbody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"4\" style=\"color:#f43f5e;\">Error loading teams: ${escHTML(err.message)}</td></tr>`;\n    }\n  }\n\n  function renderCustomTeams(teams) {\n    const tbody = document.getElementById('customTeamsTableBody');\n    if (!tbody) return;\n    if (teams.length === 0) {\n      tbody.innerHTML = `<tr class=\"empty-table-row\"><td colspan=\"4\">No custom teams yet. Use the form to add teams.</td></tr>`;\n      return;\n    }\n    tbody.innerHTML = teams.map(t => `\n      <tr>\n        <td>\n          <code style=\"color:#38bdf8;font-size:0.82rem;\">${escHTML(t.regId)}</code>\n          ${t.addedAt ? `<br><small style=\"color:var(--text-muted);font-size:0.68rem;\">${new Date(t.addedAt).toLocaleDateString()}</small>` : ''}\n        </td>\n        <td style=\"font-size:0.85rem;\">${escHTML(t.teamName)}</td>\n        <td><span style=\"font-size:0.75rem;padding:2px 7px;background:rgba(6,182,212,0.12);color:#38bdf8;border-radius:4px;\">${escHTML(t.domain || '—')}</span></td>\n        <td>\n          <button class=\"btn btn-sm\" style=\"padding:3px 10px;font-size:0.75rem;background:rgba(244,63,94,0.12);color:#f43f5e;border:1px solid rgba(244,63,94,0.25);border-radius:5px;cursor:pointer;\"\n            onclick=\"window._deleteCustomTeam(${JSON.stringify(t.regId)}, ${JSON.stringify(t.teamName)})\">\n            🗑️ Remove\n          </button>\n        </td>\n      </tr>\n    `).join('');\n  }\n\n  // Expose delete handler globally for inline onclick\n  window._deleteCustomTeam = async function(regId, teamName) {\n    if (!confirm(`Remove custom team \"${teamName}\" (${regId})?\\n\\nThis removes their login access. Their spin data is preserved.`)) return;\n    try {\n      const res = await fetch('/api/admin/teams/delete-custom/' + encodeURIComponent(regId), {\n        method: 'DELETE',\n        headers: { 'Authorization': 'Bearer ' + adminToken }\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Delete failed');\n      showToast(data.message || 'Team removed', 'success');\n      await loadCustomTeams();\n    } catch (err) {\n      showToast('Error: ' + err.message, 'error');\n    }\n  };\n\n  async function handleAddTeam(e) {\n    e.preventDefault();\n    const btn = document.getElementById('addTeamSubmitBtn');\n    const label = document.getElementById('addTeamBtnLabel');\n    const msgEl = document.getElementById('addTeamMsg');\n\n    const regId = (document.getElementById('newTeamRegId')?.value || '').trim();\n    const teamName = (document.getElementById('newTeamName')?.value || '').trim();\n    const domain = document.getElementById('newTeamDomain')?.value || '';\n    const leader = (document.getElementById('newTeamLeader')?.value || '').trim();\n    const phone = (document.getElementById('newTeamPhone')?.value || '').trim();\n    const college = (document.getElementById('newTeamCollege')?.value || '').trim();\n    const members = (document.getElementById('newTeamMembers')?.value || '').trim();\n\n    if (!regId || !teamName) {\n      showMsg(msgEl, 'Reg ID and Team Name are required.', 'error');\n      return;\n    }\n\n    if (btn) btn.disabled = true;\n    if (label) label.textContent = 'Adding…';\n    msgEl.classList.add('hidden');\n\n    try {\n      const res = await fetch('/api/admin/teams/add-custom', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + adminToken },\n        body: JSON.stringify({ regId, teamName, domain, leader, college, members, phone })\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Failed to add team');\n\n      showMsg(msgEl, '✅ ' + data.message, 'success');\n      showToast(data.message, 'success');\n\n      // Clear form fields\n      document.getElementById('newTeamRegId').value = '';\n      document.getElementById('newTeamName').value = '';\n      document.getElementById('newTeamLeader').value = '';\n      document.getElementById('newTeamPhone').value = '';\n      document.getElementById('newTeamCollege').value = '';\n      document.getElementById('newTeamMembers').value = '';\n\n      // Refresh the list on the right\n      await loadCustomTeams();\n    } catch (err) {\n      showMsg(msgEl, '❌ ' + err.message, 'error');\n    } finally {\n      if (btn) btn.disabled = false;\n      if (label) label.textContent = '➕ Add Team';\n    }\n  }\n\n  function showMsg(el, text, type) {\n    if (!el) return;\n    el.textContent = text;\n    el.style.background = type === 'success' ? 'rgba(52,211,153,0.12)' : 'rgba(244,63,94,0.12)';\n    el.style.color = type === 'success' ? '#34d399' : '#f43f5e';\n    el.style.border = type === 'success' ? '1px solid rgba(52,211,153,0.25)' : '1px solid rgba(244,63,94,0.25)';\n    el.classList.remove('hidden');\n    setTimeout(() => el.classList.add('hidden'), 6000);\n  }\n\n})();\n"
};
